 public.my_personal_vault_status() to authenticated;
;

-- >>>>> 0149_qa_space_media_inventory.sql
-- QA-only non-destructive media ownership inventory for archive planning.
-- Do not delete original Storage objects or old shared rows.
create table if not exists public.space_media_inventory (
 bucket_id text not null,
 object_path text not null,
 source_table text not null,
 source_id uuid not null,
 source_space_id uuid not null,
 original_visibility text not null
   check(original_visibility in ('private','shared','unclassified')),
 owner_id uuid,
 storage_object_exists boolean not null default true,
 media_sha256 text, -- NULL until actual file bytes are read and hashed
 encrypted_archive_verified boolean not null default false,
 indexed_at timestamptz not null default now(),
 primary key(bucket_id,object_path)
);
create index if not exists space_media_by_space_visibility_idx
 on public.space_media_inventory(source_space_id,original_visibility);
alter table public.space_media_inventory enable row level security;
revoke all on public.space_media_inventory from public,anon,authenticated;

-- All six known media references: photos, notes, trips, comments, and
-- activity image/voice components. No URL strings are treated as file keys.
with referenced as (
 select
 'onespace-memory-photos'::text bucket_id, p.object_path,
 'memory_photos'::text source_table, p.id source_id,
 m.space_id source_space_id,
 case when m.visibility in ('private','shared') then m.visibility
 else 'unclassified' end original_visibility,
 case when m.visibility='private' then m.created_by else null end owner_id
 from public.memory_photos p join public.memories m on m.id=p.memory_id
 where p.object_path is not null

 union all
 select 'onespace-note-images',p.object_path,'note_images',p.id,
 n.space_id,
 case when n.visibility in ('private','shared') then n.visibility
 else 'unclassified' end,
 case when n.visibility='private' then n.created_by else null end
 from public.note_images p join public.notes n on n.id=p.note_id
 where p.object_path is not null

 union all
 select 'onespace-trip-documents',p.object_path,'trip_attachments',p.id,
 t.space_id,
 case when t.visibility in ('private','shared') then t.visibility
 else 'unclassified' end,
 case when t.visibility='private' then t.created_by else null end
 from public.trip_attachments p join public.shared_trips t on t.id=p.trip_id
 where p.object_path is not null

 union all
 select 'onespace-activity-voice',p.voice_path,'activity_comments',p.id,
 a.space_id,
 case when a.visibility in ('private','shared') then a.visibility
 else 'unclassified' end,
 case when a.visibility='private' then a.created_by else null end
 from public.activity_comments p join public.activities a on a.id=p.activity_id
 where p.voice_path is not null

 union all
 select 'onespace-activity-media',p.payload->>'object_path',
 'activity_components',p.id,a.space_id,
 case when a.visibility in ('private','shared') then a.visibility
 else 'unclassified' end,
 case when a.visibility='private' then a.created_by else null end
 from public.activity_components p join public.activities a on a.id=p.activity_id
 where p.kind='image' and nullif(p.payload->>'object_path','') is not null

 union all
 select 'onespace-activity-voice',p.payload->>'voice_path',
 'activity_components',p.id,a.space_id,
 case when a.visibility in ('private','shared') then a.visibility
 else 'unclassified' end,
 case when a.visibility='private' then a.created_by else null end
 from public.activity_components p join public.activities a on a.id=p.activity_id
 where p.kind='voice' and nullif(p.payload->>'voice_path','') is not null
)
insert into public.space_media_inventory
(bucket_id,object_path,source_table,source_id,source_space_id,
 original_visibility,owner_id,storage_object_exists)
select r.bucket_id,r.object_path,r.source_table,r.source_id,r.source_space_id,
 r.original_visibility,r.owner_id,o.id is not null
from referenced r
left join storage.objects o on o.bucket_id=r.bucket_id and o.name=r.object_path
on conflict(bucket_id,object_path) do update set
 original_visibility=excluded.original_visibility,
 owner_id=excluded.owner_id,
 source_space_id=excluded.source_space_id,
 storage_object_exists=excluded.storage_object_exists,
 indexed_at=now();

-- No archive-ready or delete-ready status is granted by this metadata scan.
-- Actual authenticated Storage read, byte count, SHA-256, immutable export,
-- and per-recipient encryption still need verification first.
;

-- >>>>> 0150_qa_personal_vault_delete_tombstones.sql
-- QA: do not resurrect deliberately deleted private content on later restore.
-- An eventual vetted relationship-retirement worker must SET LOCAL
-- onespace.retiring_space='on' before cascading old-space rows, preserving
-- owner-controlled vault snapshots across that specific transition.
alter table public.personal_vault_dependents
  add column if not exists restorable boolean not null default true;

create or replace function private.tombstone_personal_vault_record()
returns trigger language plpgsql security definer set search_path=''
as $$
declare uid uuid;
begin
 if current_setting('onespace.retiring_space',true)='on' then return old; end if;
 if tg_table_name='personal_days_off' then
   uid:=old.user_id;
 else
   if old.visibility is distinct from 'private' then return old; end if;
   uid:=old.created_by;
 end if;
 if uid is not null then
   update public.personal_vault_records set restorable=false,
     current_visibility='deleted',snapshot='{}'::jsonb,
     last_mirrored_at=now()
   where owner_id=uid and source_table=tg_table_name
     and source_id=old.id;
 end if;
 return old;
end $$;
revoke execute on function private.tombstone_personal_vault_record()
 from public,anon,authenticated;

do $$
declare tab text;
begin
 foreach tab in array array[
 'activities','daily_checkins','goals','items_to_sort','memories',
 'notes','occasion_plans','places','reminders','saved_contacts',
 'shared_trips','space_counters','space_events','tasks','personal_days_off']
 loop
   execute format('drop trigger if exists qa_personal_vault_delete on public.%I',tab);
   execute format('create trigger qa_personal_vault_delete after delete on public.%I
      for each row execute function private.tombstone_personal_vault_record()',tab);
 end loop;
end $$;

create or replace function private.tombstone_personal_vault_dependent()
returns trigger language plpgsql security definer set search_path=''
as $$
declare uid uuid;
begin
 if current_setting('onespace.retiring_space',true)='on' then return old; end if;
 if tg_table_name in
  ('occasion_budget_items','occasion_plan_steps','occasion_proposals')
 then uid:=old.created_by;
 elsif tg_table_name='reminder_recipients' then uid:=old.recipient_id;
 else raise exception 'Unrecognized private dependent'; end if;
 if uid is not null then
   update public.personal_vault_dependents set
     restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
   where owner_id=uid and source_table=tg_table_name and source_id=old.id;
 end if;
 return old;
end $$;
revoke execute on function private.tombstone_personal_vault_dependent()
 from public,anon,authenticated;
do $$
declare tab text;
begin
 foreach tab in array array[
  'occasion_budget_items','occasion_plan_steps',
  'occasion_proposals','reminder_recipients']
 loop
  execute format('drop trigger if exists qa_personal_vault_dependent_delete on public.%I',tab);
  execute format('create trigger qa_personal_vault_dependent_delete after delete on public.%I
    for each row execute function private.tombstone_personal_vault_dependent()',tab);
 end loop;
end $$;
;

-- >>>>> 0151_qa_lifecycle_job_registry.sql
-- QA lifecycle registry. Reconciles the already-deployed staging ledger into
-- the feature-complete R461 migration sequence; never modifies live memberships.
create table if not exists public.space_lifecycle_jobs (
  id uuid primary key default gen_random_uuid(),
  original_space_id uuid not null,
  requested_by uuid not null,
  owner_at_request uuid not null,
  invited_partner_at_request uuid,
  action text not null check (action in (
    'partner_leaves','owner_removes_partner','owner_deletes_space',
    'owner_deletes_account','partner_deletes_account')),
  status text not null default 'awaiting_verified_export' check (status in (
    'awaiting_verified_export','exporting','exports_verified','transitioning',
    'retired','cleanup_queued','completed','failed','cancelled')),
  owner_continuous_space boolean not null,
  new_owner_space_id uuid,
  requested_at timestamptz not null default now(),
  last_transition_at timestamptz not null default now(),
  completed_at timestamptz,
  failure_reason text,
  constraint lifecycle_done_timestamp check (
    status <> 'completed' or completed_at is not null)
);
create table if not exists public.space_lifecycle_job_participants (
  job_id uuid not null references public.space_lifecycle_jobs(id) on delete cascade,
  user_id uuid not null,
  member_role text not null check (member_role in ('owner','partner')),
  primary key (job_id,user_id)
);
create unique index if not exists one_active_lifecycle_per_space
  on public.space_lifecycle_jobs(original_space_id)
  where status not in ('completed','failed','cancelled');
create index if not exists lifecycle_jobs_status_idx
  on public.space_lifecycle_jobs(status,requested_at);
create index if not exists lifecycle_participants_user_idx
  on public.space_lifecycle_job_participants(user_id,job_id);
alter table public.space_lifecycle_jobs enable row level security;
alter table public.space_lifecycle_job_participants enable row level security;
revoke all on table public.space_lifecycle_jobs, public.space_lifecycle_job_participants
  from public,anon,authenticated;
grant select,insert,update,delete on public.space_lifecycle_jobs,
  public.space_lifecycle_job_participants to service_role;
-- No direct user policies: only scoped signed-in RPC functions stage/cancel jobs.
;

-- >>>>> 0152_qa_lifecycle_staging_rpc.sql
-- QA staging RPCs: verbatim checkpoint of the verified QA live functions.
-- Non-destructive: requests only stage immutable participant snapshots; no separation worker.

CREATE OR REPLACE FUNCTION private.my_space_lifecycle_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  sid uuid;
  owner_id uuid;
  member_count integer;
  archive_count integer := 0;
  expected_count integer := 0;
  pending jsonb;
begin
  if me is null then raise exception 'Sign in required'; end if;
  if (select count(*) from public.space_members where user_id=me) > 1 then
    raise exception 'Multiple active memberships require support';
  end if;
  select sm.space_id, s.created_by into sid,owner_id
  from public.space_members sm join public.spaces s on s.id=sm.space_id
  where sm.user_id=me limit 1;
  if sid is null then return jsonb_build_object('has_space',false,
    'role','unpaired','member_count',0,'can_leave',false,
    'can_remove_partner',false,'can_delete_space',false,
    'active_job',null,'archives_expected',0,'archives_verified',0,
    'safe_to_finalize',false); end if;
  select count(*) into member_count from public.space_members where space_id=sid;
  expected_count := member_count*2;
  select count(distinct (a.recipient_id,a.archive_kind)) into archive_count
  from public.space_archives a
  where a.old_space_id=sid
    and a.recipient_id in (select user_id from public.space_members where space_id=sid)
    and a.archive_kind in ('private','shared')
    and a.encrypted_bytes_verified
    and a.ciphertext_sha256 ~ '^[0-9a-f]{64}$'
    and a.byte_length>0
    and a.ready_at is not null
    and a.status in ('ready','purge_due')
    and (a.status<>'ready' or a.expires_at>now())
    and exists (select 1 from storage.objects o
      where o.bucket_id='onespace-archives' and o.name=a.encrypted_object_path);
  select jsonb_build_object('id',j.id,'action',j.action,'status',j.status,
    'requested_by_me',j.requested_by=me,'requested_at',j.requested_at)
    into pending
  from public.space_lifecycle_jobs j
  where j.original_space_id=sid and j.status not in ('completed','failed','cancelled')
  order by j.requested_at desc limit 1;
  return jsonb_build_object('has_space',true,'role',case when owner_id=me then 'owner' else 'partner' end,
    'member_count',member_count,'can_leave',owner_id<>me,
    'can_remove_partner',owner_id=me and member_count=2,
    'can_delete_space',owner_id=me,'active_job',pending,
    'archives_expected',expected_count,'archives_verified',archive_count,
    'safe_to_finalize',false,
    'reason','Actual separation requires verified encrypted private/shared exports, media integrity and an authorized transition worker');
end $function$
;

CREATE OR REPLACE FUNCTION private.request_space_lifecycle_action(p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  sid uuid;
  owner_id uuid;
  partner_id uuid;
  member_count integer;
  pending_id uuid;
  job_id uuid;
begin
  if me is null then raise exception 'Sign in required'; end if;
  if p_action not in ('partner_leaves','owner_removes_partner','owner_deletes_space') then
    raise exception 'Unsupported space action';
  end if;
  if (select count(*) from public.space_members where user_id=me)<>1 then
    raise exception 'A single active space is required';
  end if;
  select s.id,s.created_by into sid,owner_id
  from public.spaces s join public.space_members sm on sm.space_id=s.id
  where sm.user_id=me for update of s;
  if sid is null then raise exception 'Not a member of a space'; end if;
  select count(*) into member_count from public.space_members where space_id=sid;
  select user_id into partner_id from public.space_members
  where space_id=sid and user_id<>owner_id limit 1;
  if member_count<1 or member_count>2 then raise exception 'Invalid membership state'; end if;
  if p_action='partner_leaves' and (me=owner_id or member_count<>2) then
    raise exception 'Only the invited partner can leave';
  end if;
  if p_action='owner_removes_partner' and (me<>owner_id or member_count<>2) then
    raise exception 'Only the owner of a paired space can remove the partner';
  end if;
  if p_action='owner_deletes_space' and me<>owner_id then
    raise exception 'Only the original owner can delete the space';
  end if;
  select j.id into pending_id from public.space_lifecycle_jobs j
   where j.original_space_id=sid
   and j.status not in ('completed','failed','cancelled') limit 1;
  if pending_id is not null then raise exception 'A lifecycle request is already in progress'; end if;
  insert into public.space_lifecycle_jobs
    (original_space_id,requested_by,owner_at_request,invited_partner_at_request,
     action,status,owner_continuous_space)
   values (sid,me,owner_id,partner_id,p_action,'awaiting_verified_export',
     p_action<>'owner_deletes_space') returning id into job_id;
  insert into public.space_lifecycle_job_participants(job_id,user_id,member_role)
  select job_id,user_id,case when user_id=owner_id then 'owner' else 'partner' end
  from public.space_members where space_id=sid;
  return jsonb_build_object('id',job_id,'status','awaiting_verified_export',
    'action',p_action,'separation_completed',false,
    'message','Request recorded. Members and data remain unchanged until secure archive verification and transition.');
end $function$
;

CREATE OR REPLACE FUNCTION private.cancel_space_lifecycle_action(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid := auth.uid(); updated_rows integer;
begin
  if me is null then raise exception 'Sign in required'; end if;
  update public.space_lifecycle_jobs j
  set status='cancelled',last_transition_at=now()
  where j.id=p_job_id and j.requested_by=me
    and j.status='awaiting_verified_export'
    and not exists(select 1 from public.space_archives a where a.old_space_id=j.original_space_id
      and a.status in ('ready','purge_due','purged'));
  get diagnostics updated_rows = row_count;
  return updated_rows=1;
end $function$
;

CREATE OR REPLACE FUNCTION public.my_space_lifecycle_status()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select private.my_space_lifecycle_status(); $function$
;

CREATE OR REPLACE FUNCTION public.request_space_lifecycle_action(p_action text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select private.request_space_lifecycle_action(p_action); $function$
;

CREATE OR REPLACE FUNCTION public.cancel_space_lifecycle_action(p_job_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$ select private.cancel_space_lifecycle_action(p_job_id); $function$
;

revoke all on function private.my_space_lifecycle_status() from public,anon;
grant execute on function private.my_space_lifecycle_status() to authenticated;
revoke all on function private.request_space_lifecycle_action(text) from public,anon;
grant execute on function private.request_space_lifecycle_action(text) to authenticated;
revoke all on function private.cancel_space_lifecycle_action(uuid) from public,anon;
grant execute on function private.cancel_space_lifecycle_action(uuid) to authenticated;
revoke all on function public.my_space_lifecycle_status() from public,anon;
grant execute on function public.my_space_lifecycle_status() to authenticated;
revoke all on function public.request_space_lifecycle_action(text) from public,anon;
grant execute on function public.request_space_lifecycle_action(text) to authenticated;
revoke all on function public.cancel_space_lifecycle_action(uuid) from public,anon;
grant execute on function public.cancel_space_lifecycle_action(uuid) to authenticated;
;

-- >>>>> 0153_qa_lifecycle_readiness_rpc.sql
-- QA-only fail-closed readiness auditor; no account or data mutation.
-- Snapshot of deployed backend; safe_to_separate always FALSE until a fully vetted
-- dependent-record exporter and lifecycle transition worker exist.

CREATE OR REPLACE FUNCTION private.space_lifecycle_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  sid uuid;
  space_owner uuid;
  member_count integer;
  member_valid boolean;
  t record;
  has_visibility boolean;
  has_creator boolean;
  table_total bigint;
  table_private bigint;
  table_shared bigint;
  total_roots bigint := 0;
  private_roots bigint := 0;
  shared_roots bigint := 0;
  unknown_roots bigint := 0;
  root_tables integer := 0;
  unclassified_tables jsonb := '[]'::jsonb;
  media_inventory_count integer := 0;
  media_unverified integer := 0;
  media_missing_inventory bigint := 0;
  unmatched_storage bigint := 0;
  verified_archives integer := 0;
  archives_expected integer;
  ready boolean;
begin
  if me is null then raise exception 'Sign in required'; end if;
  if (select count(*) from public.space_members where user_id=me) <> 1 then
    return jsonb_build_object('has_space',false,'safe_to_separate',false,
      'reason','No single active space found for this account');
  end if;
  select sm.space_id,s.created_by into sid,space_owner
  from public.space_members sm join public.spaces s on s.id=sm.space_id
  where sm.user_id=me limit 1;
  if sid is null then raise exception 'Space not found'; end if;
  select count(*) into member_count from public.space_members
  where space_id=sid;
  member_valid:=member_count between 1 and 2
    and exists(select 1 from public.space_members where space_id=sid and user_id=space_owner);

  -- Scan every root space-linked table, not just the former fixed list.
  -- Unknown/unclassified records block finalization rather than being discarded.
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables tabs
      on tabs.table_schema=c.table_schema and tabs.table_name=c.table_name
    where c.table_schema='public' and c.column_name='space_id'
      and tabs.table_type='BASE TABLE' and c.table_name<>'space_members'
    order by c.table_name
  loop
    root_tables:=root_tables+1;
    select exists(select 1 from information_schema.columns x
      where x.table_schema='public' and x.table_name=t.table_name
        and x.column_name='visibility'), exists(
      select 1 from information_schema.columns x
      where x.table_schema='public' and x.table_name=t.table_name
        and x.column_name='created_by')
    into has_visibility,has_creator;

    if has_visibility and has_creator then
      execute format(
        'select count(*),
          count(*) filter (where visibility=''private'' and
            created_by in (select user_id from public.space_members where space_id=$1)),
          count(*) filter (where visibility=''shared'' and
            created_by in (select user_id from public.space_members where space_id=$1))
         from public.%I where space_id=$1',t.table_name)
      into table_total,table_private,table_shared using sid;
    else
      execute format('select count(*) from public.%I where space_id=$1',t.table_name)
      into table_total using sid;
      table_private:=0;
      table_shared:=0;
    end if;
    total_roots:=total_roots+table_total;
    private_roots:=private_roots+table_private;
    shared_roots:=shared_roots+table_shared;
    unknown_roots:=unknown_roots+table_total-table_private-table_shared;
    if table_total>table_private+table_shared then
      unclassified_tables:=unclassified_tables || to_jsonb(t.table_name);
    end if;
  end loop;

  select count(*),count(*) filter(where not storage_object_exists
     or not encrypted_archive_verified or original_visibility='unclassified')
    into media_inventory_count,media_unverified
  from public.space_media_inventory where source_space_id=sid;

  -- Direct attachment references whose media has not yet been inventoried.
  -- Activity media encoded inside JSON must still be handled by the exporter.
  select
    (select count(*) from public.memory_photos f join public.memories r on r.id=f.memory_id
       where r.space_id=sid and not exists
       (select 1 from public.space_media_inventory v where v.source_space_id=sid
         and v.bucket_id='onespace-memory-photos' and v.object_path=f.object_path))
    +(select count(*) from public.note_images f join public.notes r on r.id=f.note_id
       where r.space_id=sid and not exists
       (select 1 from public.space_media_inventory v where v.source_space_id=sid
         and v.bucket_id='onespace-note-images' and v.object_path=f.object_path))
    +(select count(*) from public.trip_attachments f join public.shared_trips r on r.id=f.trip_id
       where r.space_id=sid and not exists
       (select 1 from public.space_media_inventory v where v.source_space_id=sid
         and v.bucket_id='onespace-trip-documents' and v.object_path=f.object_path))
    +(select count(*) from public.activity_comments f join public.activities r on r.id=f.activity_id
       where r.space_id=sid and f.voice_path is not null and not exists
       (select 1 from public.space_media_inventory v where v.source_space_id=sid
         and v.bucket_id='onespace-activity-voice' and v.object_path=f.voice_path))
    +(select count(*) from public.items_to_sort f
       where f.space_id=sid and f.file_path is not null and not exists
       (select 1 from public.space_media_inventory v where v.source_space_id=sid
         and v.bucket_id='onespace-share-in' and v.object_path=f.file_path))
    into media_missing_inventory;

  -- Candidate leftovers: references stored in JSON are not yet counted here.
  -- They are held for reconciliation, never automatically deleted by this function.
  select count(*) into unmatched_storage
  from storage.objects so
  where so.bucket_id in ('onespace-activity-media','onespace-activity-voice',
    'onespace-memory-photos','onespace-note-images','onespace-trip-documents',
    'onespace-share-in')
   and not exists (select 1 from public.space_media_inventory v
     where v.bucket_id=so.bucket_id and v.object_path=so.name)
   and not exists (select 1 from public.memory_photos x
     where so.bucket_id='onespace-memory-photos' and x.object_path=so.name)
   and not exists (select 1 from public.note_images x
     where so.bucket_id='onespace-note-images' and x.object_path=so.name)
   and not exists (select 1 from public.trip_attachments x
     where so.bucket_id='onespace-trip-documents' and x.object_path=so.name)
   and not exists (select 1 from public.activity_comments x
     where so.bucket_id='onespace-activity-voice' and x.voice_path=so.name)
   and not exists (select 1 from public.items_to_sort x
     where so.bucket_id='onespace-share-in' and x.file_path=so.name);

  archives_expected:=member_count*2;
  select count(distinct (a.recipient_id,a.archive_kind)) into verified_archives
  from public.space_archives a
  where a.old_space_id=sid
    and a.recipient_id in (select user_id from public.space_members where space_id=sid)
    and a.archive_kind in ('private','shared')
    and a.encrypted_bytes_verified
    and a.encrypted_object_path like a.recipient_id::text||'/%'
    and a.ciphertext_sha256 ~ '^[0-9a-f]{64}$'
    and a.byte_length>0 and a.ready_at is not null and a.expires_at>now()
    and a.status in ('ready','purge_due')
    and exists (select 1 from storage.objects so where so.bucket_id='onespace-archives'
      and so.name=a.encrypted_object_path);

  ready:=member_valid and unknown_roots=0
    and media_unverified=0 and media_missing_inventory=0
    and unmatched_storage=0
    and verified_archives=archives_expected;

  return jsonb_build_object(
    'has_space',true,'safe_to_separate',false,
    'root_archive_preconditions_met',ready,
    'role',case when space_owner=me then 'owner' else 'partner' end,
    'member_count',member_count,'members_valid',member_valid,
    'space_tables_inspected',root_tables,'space_linked_records',total_roots,
    'private_root_records',private_roots,'shared_root_records',shared_roots,
    'unclassified_root_records',unknown_roots,
    'unclassified_tables',unclassified_tables,
    'media_inventory_count',media_inventory_count,
    'media_unverified',media_unverified,
    'media_missing_inventory',media_missing_inventory,
    'storage_reconciliation_pending',unmatched_storage>0,
    'archives_expected',archives_expected,'archives_verified',verified_archives,
    'reason',case when not member_valid then 'Space membership integrity must be repaired'
      when unknown_roots>0 then 'Some space records are not classified as private/shared'
      when media_unverified>0 or media_missing_inventory>0 then 'Media inventory and encryption checks are incomplete'
      when unmatched_storage>0 then 'Stored files require reconciliation before separation'
      when verified_archives<>archives_expected then 'Encrypted private/shared archives have not been verified for every member'
      else 'Root and direct-media checks passed; nested dependent records, full archive verification and a transition worker remain pending' end);
end $function$
;

CREATE OR REPLACE FUNCTION public.space_lifecycle_readiness()
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$select private.space_lifecycle_readiness()$function$
;

