      from walk w join edges e on e.parent=w.current_oid
      join pg_catalog.pg_class c on c.oid=e.child
      join pg_catalog.pg_class p on p.oid=e.parent
      where w.depth<5 and not e.child=any(w.visited)
    ), matches as (
