-- >>>>> 0160_qa_private_shared_structured_archive_preview.sql
-- QA-only structured archive PREVIEW: account-scoped, no media bytes,
-- NO destructive or restore permission, and no claim of nested completeness.
-- Preview is deliberately separate from verified archive packages.
create or replace function private.my_structured_archive_preview(p_kind text)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
  me uuid:=auth.uid();
  sid uuid;
  tab text;
  rows jsonb:='[]'::jsonb;
  part jsonb;
  n bigint;
  total bigint:=0;
begin
  if me is null then raise exception 'Sign in required'; end if;
  if p_kind not in ('private','shared') or p_kind is null then
    raise exception 'Archive kind must be private or shared';
  end if;
  if (select count(*) from public.space_members where user_id=me)<>1 then
    raise exception 'Archive preview requires a single current space';
  end if;
  select sm.space_id into sid from public.space_members sm where sm.user_id=me;
  if p_kind='private' then
    select count(*) into total from public.personal_vault_records v
    where v.owner_id=me and v.source_space_id=sid and v.restorable
      and v.current_visibility='private';
    if total>2000 then raise exception 'Preview too large; batch export required'; end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'type',v.source_table,'original_id',v.source_id,
      'structured',private.qa_structured_value(v.snapshot))
      order by v.source_table,v.source_id),'[]'::jsonb)
      into rows
      from public.personal_vault_records v
      where v.owner_id=me and v.source_space_id=sid and v.restorable
        and v.current_visibility='private';
  else
    foreach tab in array array[
      'activities','daily_checkins','goals','items_to_sort','memories',
      'notes','occasion_plans','places','reminders','saved_contacts',
      'shared_trips','space_counters','space_events','tasks']
    loop
      -- Shared data may contain contributions from both current members.
      -- Reject inconsistent ownership rather than exporting it.
      execute format(
        'select count(*) from public.%I t
          where t.space_id=$1 and t.visibility=''shared''
          and not exists(select 1 from public.space_members sm
            where sm.space_id=$1 and sm.user_id=t.created_by)',tab)
        into n using sid;
      if n>0 then raise exception 'Shared content requires ownership repair'; end if;
      execute format(
        'select coalesce(jsonb_agg(jsonb_build_object(
           ''type'',%L,''original_id'',t.id,
           ''structured'',private.qa_structured_value(to_jsonb(t)))
           order by t.id),''[]''::jsonb)
         from public.%I t where t.space_id=$1 and t.visibility=''shared''',
        tab,tab)
        into part using sid;
      total:=total+jsonb_array_length(part);
      if total>2000 then raise exception 'Preview too large; batch export required'; end if;
      rows:=rows||part;
    end loop;
  end if;
  return jsonb_build_object(
    'version',1,'kind',p_kind,'source_space_id',sid,'recipient_id',me,
    'records',rows,'record_count',total,'media_included',false,
    'documents_included',false,'nested_dependents_complete',false,
    'is_verified_archive',false,'can_restore',false,
    'warning','This is a restricted structured root preview; related records and restoration require separate verified handling');
end $fn$;
revoke all on function private.my_structured_archive_preview(text) from public,anon;
grant execute on function private.my_structured_archive_preview(text) to authenticated;
create or replace function public.my_structured_archive_preview(p_kind text)
returns jsonb language sql security invoker set search_path=''
as $fn$ select private.my_structured_archive_preview(p_kind) $fn$;
revoke all on function public.my_structured_archive_preview(text) from public,anon;
grant execute on function public.my_structured_archive_preview(text) to authenticated;
;

-- >>>>> 0161_qa_private_dependent_reparent_safety.sql
-- QA: dependent ownership is a real relationship, not a stale FK snapshot.
-- Reparenting or changing the owner must invalidate previous vault ownership.
create or replace function private.mirror_personal_vault_dependent()
returns trigger language plpgsql security definer set search_path='' as $fn$
declare
  v_owner uuid;
  v_parent_type text;
  v_parent uuid;
  v_previous_owner uuid;
  v_previous_parent uuid;
begin
  if tg_table_name in ('occasion_budget_items','occasion_plan_steps','occasion_proposals') then
    v_owner:=new.created_by;
    v_parent_type:='occasion_plans';
    v_parent:=new.plan_id;
    if tg_op='UPDATE' then
      v_previous_owner:=old.created_by;
      v_previous_parent:=old.plan_id;
    end if;
  elsif tg_table_name='reminder_recipients' then
    v_owner:=new.recipient_id;
    v_parent_type:='reminders';
    v_parent:=new.reminder_id;
    if tg_op='UPDATE' then
      v_previous_owner:=old.recipient_id;
      v_previous_parent:=old.reminder_id;
    end if;
  else
    raise exception 'Unexpected private dependent source';
  end if;
  if tg_op='UPDATE' and
    (v_previous_owner is distinct from v_owner or v_previous_parent is distinct from v_parent)
    and v_previous_owner is not null then
    update public.personal_vault_dependents
       set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
     where owner_id=v_previous_owner and source_table=tg_table_name and source_id=old.id;
  end if;

  if v_owner is null then return new; end if;
  insert into public.personal_vault_dependents(
    owner_id,parent_table,parent_id,source_table,source_id,source_space_id,snapshot)
  select v_owner,v_parent_type,v_parent,tg_table_name,new.id,v.source_space_id,
         private.qa_structured_value(to_jsonb(new))
    from public.personal_vault_records v
   where v.owner_id=v_owner and v.source_table=v_parent_type
     and v.source_id=v_parent and v.restorable and v.current_visibility='private'
  on conflict(owner_id,source_table,source_id) do update set
    parent_table=excluded.parent_table,parent_id=excluded.parent_id,
    source_space_id=excluded.source_space_id,
    snapshot=excluded.snapshot,restorable=true,last_mirrored_at=now();
  return new;
end $fn$;
revoke all on function private.mirror_personal_vault_dependent() from public,anon,authenticated;

create or replace function private.mirror_personal_days_off()
returns trigger language plpgsql security definer set search_path='' as $fn$
begin
  if tg_op='UPDATE' and old.user_id is distinct from new.user_id then
    update public.personal_vault_records
      set restorable=false,current_visibility='ownership_changed',
          snapshot='{}'::jsonb,last_mirrored_at=now()
     where owner_id=old.user_id and source_table='personal_days_off'
       and source_id=old.id;
  end if;
  if new.user_id is null then return new; end if;
  if not exists(select 1 from public.space_members sm
      where sm.space_id=new.space_id and sm.user_id=new.user_id) then
    raise exception 'Personal day owner must belong to the space';
  end if;
  insert into public.personal_vault_records(
    owner_id,source_table,source_id,source_space_id,
    original_visibility,current_visibility,restorable,snapshot)
  values(new.user_id,'personal_days_off',new.id,new.space_id,
         'private','private',true,private.qa_structured_value(to_jsonb(new)))
  on conflict(owner_id,source_table,source_id) do update set
    source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
    current_visibility='private',restorable=true,last_mirrored_at=now();
  return new;
end $fn$;
revoke all on function private.mirror_personal_days_off() from public,anon,authenticated;
;

-- >>>>> 0162_qa_structured_lifecycle_public_contract.sql
-- QA-only public-facing lifecycle contract aligned with founder-approved
-- structured archives. Uploaded media/documents are excluded from restoration.
-- Keep finalization FALSE until full dependent export/restore is proven.
-- Legacy internal media-inclusive readiness is NOT used to approve separation.

create or replace function public.my_space_lifecycle_status()
returns jsonb language sql security invoker set search_path=''
as $$
  select r || jsonb_build_object(
    'archive_policy','structured_private_shared_no_media_v1',
    'media_included',false,'documents_included',false,
    'safe_to_finalize',false,
    'reason','Structured private/shared archives and restore verification are incomplete; uploaded media and documents are excluded')
  from (select private.my_space_lifecycle_status() r) src
$$;

create or replace function public.space_lifecycle_readiness()
returns jsonb language sql security invoker set search_path=''
as $$
  select jsonb_build_object(
    'has_space',r->'has_space',
    'role',r->'role',
    'member_count',r->'member_count',
    'archive_policy','structured_private_shared_no_media_v1',
    'media_included',false,
    'documents_included',false,
    'archives_expected',r->'archives_expected',
    'archives_verified',r->'archives_verified',
    'safe_to_separate',false,
    'reason','Structured private/shared dependent-record archiving and restoration must be verified before separation; uploaded media and documents are excluded from the archive')
  from (select private.my_space_lifecycle_status() r) src
$$;

