-- >>>>> 0166_qa_safe_root_and_direct_child_classification.sql
-- QA-only milestone 2: classify independently reviewed scopes. NO data export or lifecycle execution.
-- The catalog remains FAIL CLOSED until all supported children have been serialized
-- with explicit authorship/space checks, verified encryption and real restoration.
do $guard$
begin
  if (select count(*) from private.qa_archive_table_policy
      where approved=false and disposition='review_required'
      and source_table=any(array[
        'calendar_partner_reminders','gesture_message_overrides','gesture_schedules',
        'gesture_templates','object_shares','partner_checkin_requests',
        'space_notifications','space_tags','memory_photo_revisions',
        'occasion_plan_steps','occasion_proposals','shared_experience_interests',
        'shared_experience_reviews','trip_flight_options','trip_items','trip_messages'
      ]))<>16 then
    raise exception 'Archive catalog changed; re-review QA 0166 before applying';
  end if;
end $guard$;

-- Category definitions:
-- owner_private: only the matching author/sender/owner, never their partner
-- shared_only: current pair's mutual content; old shared archives remain read-only
-- private_shared: inherit parent record scope; private follows original author
-- system_excluded: operational delivery/sharing grants, not portable content
-- media_excluded: image/photo revision pointers and snapshots, not documents/text
with policy(source_table,relation_kind,disposition,policy_note) as (values
 ('calendar_partner_reminders','root','system_excluded','Event notification delivery tracking, not the calendar event; original space_events is archived'),
 ('gesture_message_overrides','root','owner_private','Only owner_id may archive their customized gesture text; never partner-visible unless sent separately'),
 ('gesture_schedules','root','owner_private','Only sender_id owns scheduling preference; recipient cannot inherit sender schedule'),
 ('gesture_templates','root','owner_private','Only creator_id owns reusable draft template; sending separately creates shared content'),
 ('object_shares','root','system_excluded','Revocable cross-person access grants must NOT survive separation or restore'),
 ('partner_checkin_requests','root','shared_only','Recipient and sender are the two RLS-authorized space members; archive old exchange read-only'),
 ('space_notifications','root','system_excluded','Delivery/read/push metadata is temporary; source content separately archived where eligible'),
 ('space_tags','root','shared_only','Relationship tag labels are mutual space metadata, never copied into a future relationship'),
 ('memory_photo_revisions','dependent','media_excluded','Photo/image revision snapshots and media references excluded by approved no-media policy'),
 ('occasion_plan_steps','dependent','private_shared','Inherit occasion_plans privacy; created_by must match current space membership'),
 ('occasion_proposals','dependent','private_shared','Inherit occasion_plans privacy; proposal is not an independent shared grant'),
 ('shared_experience_interests','dependent','shared_only','Inherit shared_experiences scope; user_id must be a member when packaging'),
 ('shared_experience_reviews','dependent','shared_only','Inherit shared_experiences scope; reviewer must be a member when packaging'),
 ('trip_flight_options','dependent','private_shared','Inherit shared_trips visibility; parent and author must be validated at packaging'),
 ('trip_items','dependent','private_shared','Inherit shared_trips visibility; parent and author must be validated at packaging'),
 ('trip_messages','dependent','private_shared','Inherit shared_trips visibility; parent and author must be validated at packaging')
)
update private.qa_archive_table_policy t
set disposition=p.disposition, approved=true, reviewed_at=now(),
    policy_note=p.policy_note||'; scope approved ONLY, portable encrypted serializer and restore pending'
from policy p
where t.source_table=p.source_table and t.relation_kind=p.relation_kind
  and t.disposition='review_required' and t.approved=false;
-- DO NOT change the public readiness flag; safe_to_archive and safe_to_separate remain false.
;

-- >>>>> 0167_qa_private_trip_children_vault_mirroring.sql
-- QA-only: preserve private trip child records across clean-space transitions.
-- No media files or blobs, no deletion/restore enablement, no Production changes.
create or replace function private.qa_mirror_trip_child()
returns trigger language plpgsql security definer set search_path='' as $fn$
declare
  v_owner uuid;
  v_visibility text;
  v_space uuid;
begin
  if tg_table_schema<>'public' or tg_table_name not in
    ('trip_flight_options','trip_items','trip_messages') then
    raise exception 'Unexpected private trip child source';
  end if;
  if tg_op='DELETE' then
    if current_setting('onespace.retiring_space',true) is distinct from 'on' then
      update public.personal_vault_dependents
        set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
       where owner_id=old.created_by and source_table=tg_table_name
         and source_id=old.id;
    end if;
    return old;
  end if;
  if tg_op='UPDATE' and
     (new.created_by is distinct from old.created_by
      or new.trip_id is distinct from old.trip_id) then
    update public.personal_vault_dependents
      set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
    where owner_id=old.created_by and source_table=tg_table_name
      and source_id=old.id;
  end if;
  select p.created_by,p.visibility,p.space_id into v_owner,v_visibility,v_space
  from public.shared_trips p where p.id=new.trip_id;
  if v_visibility='private' then
    if new.created_by is distinct from v_owner then
      raise exception 'Private trip child must belong to trip owner';
    end if;
    if not exists(select 1 from public.personal_vault_records v
       where v.owner_id=v_owner and v.source_table='shared_trips'
       and v.source_id=new.trip_id and v.source_space_id=v_space
       and v.current_visibility='private' and v.restorable) then
      raise exception 'Private trip root snapshot missing';
    end if;
    insert into public.personal_vault_dependents
      (owner_id,parent_table,parent_id,source_table,source_id,source_space_id,snapshot)
    values(new.created_by,'shared_trips',new.trip_id,tg_table_name,
           new.id,v_space,private.qa_structured_value(to_jsonb(new)))
    on conflict(owner_id,source_table,source_id) do update set
      parent_table=excluded.parent_table,parent_id=excluded.parent_id,
      source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
      restorable=true,last_mirrored_at=now();
  else
    -- Shared trip descendants must never remain marked as restorable private.
    update public.personal_vault_dependents
      set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
    where owner_id=new.created_by and source_table=tg_table_name
      and source_id=new.id;
  end if;
  return new;
end $fn$;
revoke all on function private.qa_mirror_trip_child() from public,anon,authenticated;

-- Called after the existing root-vault trigger whenever the trip's
-- visibility, account owner or space changes.
create or replace function private.qa_sync_private_trip_children(p_trip_id uuid)
returns void language plpgsql security definer set search_path='' as $fn$
declare
  v_trip public.shared_trips%rowtype;
  source_table text;
  mismatch_count bigint;
begin
  select * into v_trip from public.shared_trips where id=p_trip_id;
  if not found then return; end if;
  if v_trip.visibility<>'private' then
    update public.personal_vault_dependents
      set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
    where parent_table='shared_trips' and parent_id=p_trip_id;
    return;
  end if;
  if not exists(select 1 from public.personal_vault_records v
    where v.owner_id=v_trip.created_by and v.source_table='shared_trips'
    and v.source_id=v_trip.id and v.source_space_id=v_trip.space_id
    and v.restorable and v.current_visibility='private') then
    raise exception 'Private trip root vault must exist before child sync';
  end if;
  foreach source_table in array array[
    'trip_flight_options','trip_items','trip_messages'
  ] loop
    execute format('select count(*) from public.%I c
      where c.trip_id=$1 and c.created_by is distinct from $2',source_table)
    into mismatch_count using p_trip_id,v_trip.created_by;
    if mismatch_count>0 then
      raise exception 'Private trip contains child owned by another account';
    end if;
    execute format(
      'insert into public.personal_vault_dependents
        (owner_id,parent_table,parent_id,source_table,source_id,source_space_id,snapshot)
       select $1,''shared_trips'',$2,%L,c.id,$3,
         private.qa_structured_value(to_jsonb(c))
       from public.%I c where c.trip_id=$2 and c.created_by=$1
       on conflict(owner_id,source_table,source_id) do update set
         parent_table=excluded.parent_table,parent_id=excluded.parent_id,
         source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
         restorable=true,last_mirrored_at=now()',source_table,source_table)
    using v_trip.created_by,v_trip.id,v_trip.space_id;
  end loop;
end $fn$;
revoke all on function private.qa_sync_private_trip_children(uuid)
from public,anon,authenticated;

create or replace function private.qa_trip_children_on_parent_change()
returns trigger language plpgsql security definer set search_path='' as $fn$
begin
  if tg_op='UPDATE' and old.created_by is distinct from new.created_by then
    update public.personal_vault_dependents
      set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
    where owner_id=old.created_by and parent_table='shared_trips'
      and parent_id=old.id;
  end if;
  perform private.qa_sync_private_trip_children(new.id);
  return new;
end $fn$;
revoke all on function private.qa_trip_children_on_parent_change()
from public,anon,authenticated;

create trigger qa_trip_children_on_parent_change
after update of visibility,created_by,space_id on public.shared_trips
for each row execute function private.qa_trip_children_on_parent_change();

create trigger qa_trip_vault_mirror after insert or update or delete
on public.trip_flight_options for each row
execute function private.qa_mirror_trip_child();
create trigger qa_trip_vault_mirror after insert or update or delete
on public.trip_items for each row
execute function private.qa_mirror_trip_child();
create trigger qa_trip_vault_mirror after insert or update or delete
on public.trip_messages for each row
execute function private.qa_mirror_trip_child();

