;

-- >>>>> 0168_qa_allow_trip_vault_children.sql
-- QA-only 0168: allow three approved private trip child snapshot types.
-- Preserve the earlier occasion/reminder allowlist and reject all other types.
alter table public.personal_vault_dependents
  drop constraint if exists vault_child_type_allowed;
alter table public.personal_vault_dependents
  add constraint vault_child_type_allowed check (
    (parent_table='occasion_plans' and source_table in (
      'occasion_budget_items','occasion_plan_steps','occasion_proposals'))
    or (parent_table='reminders' and source_table='reminder_recipients')
    or (parent_table='shared_trips' and source_table in (
      'trip_flight_options','trip_items','trip_messages'))
  );
-- Zero private trip children were present before this controlled QA change.
-- Backfill after the new allowlist is active.
do $backfill$
declare trip_record record;
begin
  for trip_record in select id from public.shared_trips where visibility='private' loop
    perform private.qa_sync_private_trip_children(trip_record.id);
  end loop;
end $backfill$;
;

-- >>>>> 0169_qa_private_trip_nested_structured_preview.sql
-- QA-only 0169: deterministic, scoped private-trip structured package PREVIEW.
-- This is NOT a portable encrypted archive, not an authorized restore, and
-- MUST NEVER be accepted as proof for leave/remove/delete lifecycle gating.
create or replace function private.qa_private_trip_structured_package(p_trip_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path='' as $fn$
declare
  caller uuid := auth.uid();
  trip_record public.shared_trips%rowtype;
  source_table text;
  item_count integer;
  invalid_count integer;
  total_children integer := 0;
  payload jsonb;
  children jsonb := '{}'::jsonb;
  child_rows jsonb;
  fingerprint text;
begin
  if caller is null then raise exception 'Sign in required'; end if;
  if p_trip_id is null then raise exception 'Private trip not found'; end if;

  -- No caller-provided owner or space ID is ever trusted. A former partner
  -- and any unrelated account receive the same not-found error.
  select t.* into trip_record
  from public.shared_trips t
  join public.space_members sm on sm.space_id=t.space_id and sm.user_id=caller
  where t.id=p_trip_id and t.created_by=caller and t.visibility='private';
  if not found then raise exception 'Private trip not found'; end if;
  if (select count(*) from public.space_members sm where sm.user_id=caller)<>1 then
    raise exception 'Private trip not found';
  end if;

  if (select count(*) from private.qa_archive_table_policy p
      where p.source_table in ('shared_trips','trip_flight_options',
                               'trip_items','trip_messages')
        and p.approved and p.disposition='private_shared')<>4 then
    raise exception 'Private trip package scope has not been approved';
  end if;

  if not exists (
      select 1 from public.personal_vault_records v
       where v.owner_id=caller and v.source_table='shared_trips'
         and v.source_id=trip_record.id
         and v.source_space_id=trip_record.space_id
         and v.current_visibility='private' and v.restorable
         and v.snapshot=private.qa_structured_value(to_jsonb(trip_record))
    ) then
    raise exception 'Private trip vault is not synchronized';
  end if;

  foreach source_table in array array[
    'trip_flight_options','trip_items','trip_messages'
  ] loop
    -- Require exactly one valid owner/space/sanitized vault mirror per child.
    -- Never infer that a partner-authored child belongs to this owner.
    execute format(
      'select count(*),count(*) filter(
         where c.created_by is distinct from $2
            or v.source_id is null)
       from public.%I c
       left join public.personal_vault_dependents v
         on v.source_table=%L and v.source_id=c.id and v.owner_id=$2
        and v.parent_table=''shared_trips'' and v.parent_id=$1
        and v.source_space_id=$3 and v.restorable
        and v.snapshot=private.qa_structured_value(to_jsonb(c))
       where c.trip_id=$1',source_table,source_table
    ) into item_count,invalid_count
      using trip_record.id,caller,trip_record.space_id;
    if invalid_count>0 then
      raise exception 'Private trip child ownership or snapshot mismatch';
    end if;
    total_children:=total_children+item_count;
    if total_children>500 then
      raise exception 'Private trip package exceeds per-request record limit';
    end if;
    execute format(
      'select coalesce(jsonb_agg(
         jsonb_build_object(''source_id'',c.id,
          ''structured'',private.qa_structured_value(to_jsonb(c)))
         order by c.id::text),''[]''::jsonb)
       from public.%I c where c.trip_id=$1 and c.created_by=$2',source_table
    ) into child_rows using trip_record.id,caller;
    children:=children||jsonb_build_object(source_table,child_rows);
  end loop;

  -- Hash the stable structured payload only (no transient timestamps).
  -- SHA-256 detects corruption; it is NOT encryption or authenticity.
  payload:=jsonb_build_object(
    'schema','onespace.private-trip-structured-preview.v1',
    'source_space_id',trip_record.space_id,
    'owner_id',caller,
    'root',jsonb_build_object('table','shared_trips',
      'source_id',trip_record.id,
      'structured',private.qa_structured_value(to_jsonb(trip_record))),
    'children',children,
    'child_record_count',total_children);
  if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
    raise exception 'Private trip package exceeds 2 MiB preview limit';
  end if;
  fingerprint:=encode(extensions.digest(
      convert_to(payload::text,'UTF8'),'sha256'),'hex');

  return jsonb_build_object(
    'created_at',now(),
    'payload',payload,
    'payload_sha256',fingerprint,
    'media_included',false,
    'documents_included',false,
    'encrypted',false,
    'is_verified_archive',false,
    'can_restore',false,
    'safe_to_separate',false,
    'warning','Private trip structured preview only. No encrypted/downloadable archive or restore is available.');
end $fn$;
revoke all on function private.qa_private_trip_structured_package(uuid)
  from public,anon,authenticated;
grant execute on function private.qa_private_trip_structured_package(uuid)
  to authenticated;
;

-- >>>>> 0170_qa_strip_indirect_media_identifiers.sql
-- QA 0170: remove indirect uploaded media pointers and metadata.
-- Preserve ordinary text, captions, non-media links.
CREATE OR REPLACE FUNCTION private.qa_structured_value(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  typ text;
  item record;
  result jsonb;
  sanitized jsonb;
  k text;
begin
  if p_value is null then return 'null'::jsonb; end if;
  typ:=jsonb_typeof(p_value);
  if typ='object' then
    result:='{}'::jsonb;
    for item in select key,value from jsonb_each(p_value) loop
      k:=lower(item.key);
      -- Exclude file/media bodies, file pointers and embedded Quill media.
      -- Ordinary written content, including text of notes and links, remains.
      if k=any(array[
        'object_path','file_path','image_path','image_url','photo_path',
        'photo_url','thumbnail_path','thumbnail_url','voice_path','voice_url',
        'audio_path','audio_url','video_path','video_url','media_path',
        'media_url','attachment_path','attachment_url','document_path',
        'document_url','mime_type','byte_size','base64','data_uri',
        'binary','blob','photo','photos','image','images','audio',
        'voice','video','videos','media','attachment','attachments',
        'file','files','document','documents','thumbnail','thumbnails',
        'file_name','file_mime','file_size','voice_seconds',
        'photo_id','image_id','media_id','file_id','attachment_id',
        'document_id','cover_photo_id','cover_image_id','media_sha256'
      ])
      or k ~ '^photo_[0-9]+_id$'
      or k ~ '^image_[0-9]+_id$' then
        continue;
      end if;
      sanitized:=private.qa_structured_value(item.value);
      if sanitized is not null then
        result:=result||jsonb_build_object(item.key,sanitized);
      end if;
    end loop;
    return result;
  elsif typ='array' then
    result:='[]'::jsonb;
    for item in select value from jsonb_array_elements(p_value) loop
      sanitized:=private.qa_structured_value(item.value);
      -- Keep the array shape stable; a removed binary element becomes null.
      result:=result||jsonb_build_array(coalesce(sanitized,'null'::jsonb));
    end loop;
    return result;
  elsif typ='string' then
    if p_value #>> '{}' ~* '^\s*(data:(image|audio|video|application/(pdf|octet-stream))|blob:|file:|content://)' then
      return 'null'::jsonb;
    end if;
    -- Strip only the media URL inside a written sentence; do not discard
    -- surrounding notes, contact text or messages just because a link exists.
    -- Remove embedded media data URIs even when preceded by ordinary text.
    return to_jsonb(
      regexp_replace(
        regexp_replace(
          p_value #>> '{}',
          '(https?://[^[:space:]"<>]*/)?/storage/v1/object/[^[:space:]"<>]+',
          '[uploaded media excluded]','gi'),
        'data:(image|audio|video|application/(pdf|octet-stream))[^[:space:]"<>]*',
        '[uploaded media excluded]','gi')
    );
  end if;
  return p_value;
end $function$
;
;

-- >>>>> 0171_qa_allow_private_task_checklist_children.sql
-- QA 0171: permit only task checklist structured children in personal vault.
-- Existing occasion, reminder and trip child allowlist remains unchanged.
alter table public.personal_vault_dependents drop constraint vault_child_type_allowed;
alter table public.personal_vault_dependents add constraint vault_child_type_allowed check (
 (parent_table='occasion_plans' and source_table in
  ('occasion_budget_items','occasion_plan_steps','occasion_proposals'))
 or (parent_table='reminders' and source_table='reminder_recipients')
 or (parent_table='shared_trips' and source_table in
  ('trip_flight_options','trip_items','trip_messages'))
 or (parent_table='tasks' and source_table in
  ('task_checklist_items','task_checklist_checks'))
);
;

-- >>>>> 0172_qa_private_task_checklist_vault_mirroring.sql
-- QA 0172: preserve owner-only checklist items + completion checks.
-- The separate Personal Vault shadows current private source data; it does not
-- enable portable archive or restoration, and does not modify Production.
create or replace function private.qa_mirror_private_task_child()
returns trigger language plpgsql security definer set search_path='' as $fn$
declare
  child_id uuid;
  task_id uuid;
  child_actor uuid;
  old_actor uuid;
  old_task uuid;
  task_owner uuid;
  task_visibility text;
  task_space uuid;
begin
  if tg_table_schema<>'public' or tg_table_name not in
     ('task_checklist_items','task_checklist_checks') then
    raise exception 'Unexpected checklist vault source';
  end if;
  if tg_op='DELETE' then
    if current_setting('onespace.retiring_space',true) is distinct from 'on' then
      update public.personal_vault_dependents set
        restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
      where source_table=tg_table_name and source_id=old.id;
    end if;
    return old;
  end if;
  child_id:=new.id;
  if tg_table_name='task_checklist_items' then
    task_id:=new.task_id;
    child_actor:=new.created_by;
    if tg_op='UPDATE' then
      old_actor:=old.created_by;
      old_task:=old.task_id;
    end if;
  else
    task_id:=new.task_id;
    child_actor:=new.user_id;
    if tg_op='UPDATE' then
      old_actor:=old.user_id;
      old_task:=old.task_id;
    end if;
    -- A check's claimed task_id must be the actual item's task.
    if not exists (select 1 from public.task_checklist_items i
                   where i.id=new.item_id and i.task_id=new.task_id) then
      raise exception 'Checklist check and item task mismatch';
    end if;
  end if;

  if tg_op='UPDATE' and (old_actor is distinct from child_actor
                         or old_task is distinct from task_id) then
    update public.personal_vault_dependents set
      restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
     where source_table=tg_table_name and source_id=child_id;
  end if;

  select t.created_by,t.visibility,t.space_id
    into task_owner,task_visibility,task_space
    from public.tasks t where t.id=task_id;
  if not found then raise exception 'Checklist task not found'; end if;
  if task_visibility='private' then
    if child_actor is distinct from task_owner then
      raise exception 'Private checklist child must belong to task owner';
    end if;
    if not exists (
      select 1 from public.personal_vault_records v
       where v.source_table='tasks' and v.source_id=task_id
         and v.owner_id=task_owner and v.source_space_id=task_space
         and v.current_visibility='private' and v.restorable
    ) then
      raise exception 'Private task root snapshot missing';
    end if;
    insert into public.personal_vault_dependents(
        owner_id,parent_table,parent_id,source_table,source_id,
        source_space_id,snapshot)
    values(task_owner,'tasks',task_id,tg_table_name,child_id,task_space,
           private.qa_structured_value(to_jsonb(new)))
    on conflict(owner_id,source_table,source_id) do update set
      parent_table=excluded.parent_table,parent_id=excluded.parent_id,
      source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
      restorable=true,last_mirrored_at=now();
  else
    -- Shared checklist participation is never portable as a private record.
    update public.personal_vault_dependents
       set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
     where source_table=tg_table_name and source_id=child_id;
  end if;
  return new;
end $fn$;
revoke all on function private.qa_mirror_private_task_child()
  from public,anon,authenticated;

create or replace function private.qa_sync_private_task_checklist(p_task_id uuid)
returns void language plpgsql security definer set search_path='' as $fn$
declare
  root public.tasks%rowtype;
begin
  select * into root from public.tasks where id=p_task_id;
  if not found then return; end if;
  if root.visibility<>'private' then
    update public.personal_vault_dependents
      set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
    where parent_table='tasks' and parent_id=root.id;
    return;
  end if;
  if not exists (
    select 1 from public.personal_vault_records v
    where v.owner_id=root.created_by and v.source_table='tasks'
      and v.source_id=root.id and v.source_space_id=root.space_id
      and v.current_visibility='private' and v.restorable
  ) then raise exception 'Private task root vault missing';end if;
  -- Records from another member, possibly authored while shared, are never
  -- silently copied to the new private owner's vault. The future exporter
  -- must fail closed until that ownership conflict is separately resolved.
  insert into public.personal_vault_dependents(
     owner_id,parent_table,parent_id,source_table,source_id,
     source_space_id,snapshot)
  select root.created_by,'tasks',root.id,'task_checklist_items',i.id,
         root.space_id,private.qa_structured_value(to_jsonb(i))
    from public.task_checklist_items i
   where i.task_id=root.id and i.created_by=root.created_by
  on conflict(owner_id,source_table,source_id) do update set
    parent_table=excluded.parent_table,parent_id=excluded.parent_id,
    source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
    restorable=true,last_mirrored_at=now();

  insert into public.personal_vault_dependents(
     owner_id,parent_table,parent_id,source_table,source_id,
     source_space_id,snapshot)
  select root.created_by,'tasks',root.id,'task_checklist_checks',c.id,
         root.space_id,private.qa_structured_value(to_jsonb(c))
    from public.task_checklist_checks c
    join public.task_checklist_items i on i.id=c.item_id
   where i.task_id=root.id and c.task_id=root.id
     and c.user_id=root.created_by
  on conflict(owner_id,source_table,source_id) do update set
    parent_table=excluded.parent_table,parent_id=excluded.parent_id,
    source_space_id=excluded.source_space_id,snapshot=excluded.snapshot,
    restorable=true,last_mirrored_at=now();
end $fn$;
revoke all on function private.qa_sync_private_task_checklist(uuid)
  from public,anon,authenticated;

create or replace function private.qa_task_checklist_parent_changed()
returns trigger language plpgsql security definer set search_path='' as $fn$
begin
  if old.created_by is distinct from new.created_by
      or old.space_id is distinct from new.space_id then
    update public.personal_vault_dependents
     set restorable=false,snapshot='{}'::jsonb,last_mirrored_at=now()
     where parent_table='tasks' and parent_id=new.id;
  end if;
  perform private.qa_sync_private_task_checklist(new.id);
  return new;
end $fn$;
revoke all on function private.qa_task_checklist_parent_changed()
  from public,anon,authenticated;

create trigger qa_task_checklist_parent_changed
  after update of visibility,created_by,space_id on public.tasks
  for each row execute function private.qa_task_checklist_parent_changed();
create trigger qa_task_checklist_mirror
  after insert or update or delete on public.task_checklist_items
  for each row execute function private.qa_mirror_private_task_child();
create trigger qa_task_checklist_mirror
  after insert or update or delete on public.task_checklist_checks
  for each row execute function private.qa_mirror_private_task_child();

-- QA only: seed shadow copies for any existing private tasks, no root content changed.
do $backfill$
declare rec record;
begin
 for rec in select id from public.tasks where visibility='private' loop
   perform private.qa_sync_private_task_checklist(rec.id);
 end loop;
end $backfill$;
;

-- >>>>> 0173_qa_private_shared_checklist_child_policy.sql
-- QA 0173: explicit policy for task checklist descendants.
-- Child content inherits task visibility, but its actor must be validated.
-- Shared checklist completions remain part of the original couple's archived
-- history only. A private task must not absorb partner-authored descendants.
do $guard$
begin
  if (select count(*) from private.qa_archive_table_policy
      where source_table in ('task_checklist_items','task_checklist_checks')
      and relation_kind='dependent' and canonical_parent='tasks'
      and disposition='review_required' and not approved)<>2 then
    raise exception 'Checklist archive classification requires fresh review';
  end if;
end $guard$;
update private.qa_archive_table_policy
set disposition='private_shared',approved=true,reviewed_at=now(),
    policy_note='Inherit task privacy. Private items created_by, checks user_id and actual task_id must equal owner/parent. Any partner-authored descendant fails closed; shared historical pair data remains reference only. Mirroring verified, portable encryption/restore not yet implemented.'
where source_table in ('task_checklist_items','task_checklist_checks')
  and relation_kind='dependent' and canonical_parent='tasks'
  and disposition='review_required' and not approved;
-- Global safe_to_archive and safe_to_separate remain FALSE.
;

-- >>>>> 0174_qa_private_task_nested_structured_preview.sql
-- QA-only 0174: read-only, owner-authenticated structured checklist package.
-- NOT encrypted; NOT a downloadable archive; NOT an authorized restoration.
create or replace function private.qa_private_task_checklist_package(p_task_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
  caller uuid:=auth.uid();
  root public.tasks%rowtype;
  invalid_count bigint;
  item_count bigint;
  check_count bigint;
  items jsonb;
  checks jsonb;
  payload jsonb;
begin
  if caller is null then raise exception 'Sign in required';end if;
  select t.* into root from public.tasks t
   join public.space_members sm on sm.space_id=t.space_id and sm.user_id=caller
   where t.id=p_task_id and t.visibility='private' and t.created_by=caller;
  if not found then raise exception 'Private task not found';end if;
  if (select count(*) from public.space_members sm where sm.user_id=caller)<>1 then
    raise exception 'Private task not found';
  end if;
  if (select count(*) from private.qa_archive_table_policy p
    where p.approved and p.disposition='private_shared'
      and p.source_table in ('tasks','task_checklist_items','task_checklist_checks'))<>3
  then raise exception 'Checklist archive scope not approved'; end if;
  if not exists(select 1 from public.personal_vault_records v
    where v.owner_id=caller and v.source_table='tasks' and v.source_id=root.id
      and v.source_space_id=root.space_id and v.current_visibility='private'
      and v.restorable and v.snapshot=private.qa_structured_value(to_jsonb(root)))
  then raise exception 'Private task root vault is not synchronized'; end if;

  select count(*),count(*) filter(
    where i.created_by is distinct from caller or v.source_id is null)
  into item_count,invalid_count
  from public.task_checklist_items i
  left join public.personal_vault_dependents v
    on v.owner_id=caller and v.parent_table='tasks' and v.parent_id=root.id
      and v.source_table='task_checklist_items' and v.source_id=i.id
      and v.source_space_id=root.space_id and v.restorable
      and v.snapshot=private.qa_structured_value(to_jsonb(i))
  where i.task_id=root.id;
  if invalid_count>0 then
    raise exception 'Private checklist item ownership or snapshot mismatch';end if;

  select count(*),count(*) filter(
    where c.task_id is distinct from root.id
      or c.user_id is distinct from caller or v.source_id is null)
  into check_count,invalid_count
  from public.task_checklist_checks c
  join public.task_checklist_items i on i.id=c.item_id
  left join public.personal_vault_dependents v
    on v.owner_id=caller and v.parent_table='tasks' and v.parent_id=root.id
      and v.source_table='task_checklist_checks' and v.source_id=c.id
      and v.source_space_id=root.space_id and v.restorable
      and v.snapshot=private.qa_structured_value(to_jsonb(c))
  where i.task_id=root.id;
  if invalid_count>0 then
    raise exception 'Private checklist check ownership or snapshot mismatch';end if;
  if item_count+check_count>500 then
    raise exception 'Private checklist package exceeds 500 records';end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'source_id',i.id,'structured',private.qa_structured_value(to_jsonb(i)))
    order by i.id::text),'[]'::jsonb)
  into items from public.task_checklist_items i where i.task_id=root.id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'source_id',c.id,'structured',private.qa_structured_value(to_jsonb(c)))
    order by c.id::text),'[]'::jsonb)
  into checks
  from public.task_checklist_checks c
  join public.task_checklist_items i on i.id=c.item_id
  where i.task_id=root.id and c.task_id=root.id;
  payload:=jsonb_build_object(
    'schema','onespace.private-task-checklist-preview.v1',
    'owner_id',caller,'source_space_id',root.space_id,
    'root',jsonb_build_object('table','tasks','source_id',root.id,
          'structured',private.qa_structured_value(to_jsonb(root))),
    'children',jsonb_build_object('task_checklist_items',items,
                                   'task_checklist_checks',checks),
    'child_record_count',item_count+check_count);
  if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
    raise exception 'Private checklist package exceeds 2 MiB'; end if;
  return jsonb_build_object(
    'payload',payload,
    'payload_sha256',encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex'),
    'media_included',false,'documents_included',false,
    'encrypted',false,'is_verified_archive',false,'can_restore',false,
    'safe_to_separate',false,
    'warning','Private checklist structured preview only, not an encrypted/downloadable archive or restorable copy');
end $fn$;
revoke all on function private.qa_private_task_checklist_package(uuid)
from public,anon,authenticated;
grant execute on function private.qa_private_task_checklist_package(uuid) to authenticated;
;

-- >>>>> 0175_qa_exclude_transient_snoozes_and_scrapbook_grants.sql
-- QA 0175: exclude transient per-recipient snoozes and scrapbook access grants.
-- Content remains in activities, memories and other authorized structured tables.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
     where source_table in ('activity_attention_snoozes','scrapbook_invites')
       and relation_kind='dependent' and disposition='review_required'
       and not approved)<>2 then
   raise exception 'Operational archive exclusions require new scope review';
 end if;
end $guard$;
update private.qa_archive_table_policy
set disposition='system_excluded',approved=true,reviewed_at=now(),
    policy_note=case source_table
      when 'activity_attention_snoozes' then
        'Recipient-specific transient attention delay; source activity remains archived but an obsolete snooze must not resurrect'
      else
        'Revocable scrapbook collaboration invitation/access state; source memory/page content is separate and authorization must not restore into a new partnership'
    end
where source_table in ('activity_attention_snoozes','scrapbook_invites')
  and relation_kind='dependent' and disposition='review_required'
  and not approved;
-- No lifecycle safety switch is changed.
;

-- >>>>> 0176_qa_verified_bytes_required_for_ready_archive.sql
-- QA 0176: a "ready" or retired archive must have independently verified
-- encrypted bytes, not merely a filename and a purported SHA-256 string.
-- Production and live content are never changed by this migration.
do $guard$
begin
 if exists(select 1 from public.space_archives
      where status in ('ready','purge_due','purged')
        and encrypted_bytes_verified is distinct from true) then
   raise exception 'Existing unverified archive must be reconciled before strengthening readiness';
 end if;
end $guard$;
alter table public.space_archives drop constraint ready_archives_complete;
alter table public.space_archives add constraint ready_archives_complete check (
  status not in ('ready','purge_due','purged')
  or (
    ready_at is not null and expires_at is not null
    and encrypted_object_path is not null
    and ciphertext_sha256 ~ '^[0-9a-f]{64}$'
    and byte_length > 0
    and encrypted_bytes_verified is true
  )
);
-- This does not set ready, generate files, encrypt records or enable deletion.
;

-- >>>>> 0177_qa_export_private_gesture_scope_and_no_media.sql
-- QA 0177: prevent SECURITY DEFINER JSON export from leaking unsent
-- creator-private gesture templates and sender-private schedules to recipient.
-- Media pointers are also excluded using the existing QA structured sanitizer.
-- Does not authorize archive/restore, relationship separation or deletion.
CREATE OR REPLACE FUNCTION public.export_my_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  result jsonb;
  t record;
  rows jsonb;
begin
  if me is null then raise exception 'Sign in first'; end if;
  result := jsonb_build_object(
    'exported_at', now(),
    'format', 'OneSpace export v1',
    'note', 'Everything you created or received in OneSpace. Shared items your partner created are not included.',
    'profile', (select private.qa_structured_value(to_jsonb(p)) from public.profiles p where p.id = me));
  for t in
    select c.table_name,
      string_agg(format('%I = $1', c.column_name), ' or ') as cond
    from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema
      and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
    where c.table_schema = 'public'
      and c.column_name in ('created_by','user_id','sender_id','owner_id','author_id','recipient_id')
      and c.table_name not in ('account_deletion_requests')
    group by c.table_name order by c.table_name
  loop
    -- Two owner-only gesture tables also have a recipient_id field.
    -- That recipient is NOT authorized to export an unsent template or
    -- another person's private scheduling preferences. This function
    -- bypasses RLS, so it must never rely on the generic recipient match.
    if t.table_name='gesture_templates' then
      select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(r))), '[]'::jsonb)
        into rows from public.gesture_templates r where r.creator_id=me;
    elsif t.table_name='gesture_schedules' then
      select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(r))), '[]'::jsonb)
        into rows from public.gesture_schedules r where r.sender_id=me;
    else
      execute format(
        'select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(r))), ''[]''::jsonb)
         from public.%I r where %s',t.table_name,t.cond)
        into rows using me;
    end if;
    if t.table_name = 'push_devices' then
      rows := (select coalesce(jsonb_agg(e - 'token' - 'fcm_token'), '[]'::jsonb) from jsonb_array_elements(rows) e);
    end if;
    if jsonb_array_length(rows) > 0 then
      result := result || jsonb_build_object(t.table_name, rows);
    end if;
  end loop;
  return result;
end $function$
;
-- Preserve existing authenticated execution only; never allow anon.
