-- >>>>> 0181_qa_shared_experience_history_privacy_preview.sql
-- QA 0181: classify nested SHARED-experience history and render a
-- recipient-filtered, media-free, reference-only preview. Not a restore API.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
      where source_table in ('shared_experience_comments',
                             'shared_experience_revisions')
        and relation_kind='dependent'
        and canonical_parent='shared_experiences'
        and disposition='review_required'
        and not approved)<>2 then
   raise exception 'Shared-experience child privacy policy requires review';
 end if;
end $guard$;
update private.qa_archive_table_policy
 set disposition='shared_only',approved=true,reviewed_at=now(),
 policy_note=case source_table
   when 'shared_experience_comments' then
     'Shared-experience comments inherit shared parent but archived comments are visible only to original author; remove replies to hidden comments. Preserve written text, exclude media. Reference-only history; no restoration into next relationship.'
   else
     'Shared-experience revision audit trail inherits shared parent, includes both member contributions with media-free before/after snapshots. Reference-only history; never restore as a live record.'
 end
where source_table in ('shared_experience_comments',
                       'shared_experience_revisions')
  and relation_kind='dependent'
  and canonical_parent='shared_experiences'
  and disposition='review_required'
  and not approved;

create or replace function private.qa_shared_experience_history_preview(
 p_experience_id uuid
) returns jsonb
language plpgsql stable security definer set search_path='' as $fn$
declare
 caller uuid:=auth.uid();
 root public.shared_experiences%rowtype;
 notes jsonb;
 history jsonb;
 nc integer;
 nr integer;
 unknown_authors bigint;
 payload jsonb;
begin
 if caller is null then raise exception 'Sign in required';end if;
 select x.* into root
 from public.shared_experiences x
 join public.space_members m
   on m.space_id=x.space_id and m.user_id=caller
 where x.id=p_experience_id;
 if not found then raise exception 'Shared experience not found'; end if;
 if (select count(*) from public.space_members where user_id=caller)<>1 then
   raise exception 'Shared experience not found';
 end if;
 if (select count(*) from private.qa_archive_table_policy p
    where p.source_table in ('shared_experiences',
       'shared_experience_comments','shared_experience_revisions')
     and p.approved and p.disposition='shared_only')<>3 then
    raise exception 'Shared-experience history scope not approved';end if;
 -- Any current child authored by a user outside the couple is an integrity
 -- fault. Do not silently drop it from the archive's completeness counts.
 select count(*) into unknown_authors
 from public.shared_experience_comments c
 where c.experience_id=root.id
   and not exists(select 1 from public.space_members sm
     where sm.space_id=root.space_id and sm.user_id=c.created_by);
 if unknown_authors>0 then
   raise exception 'Shared-experience comment owner lineage mismatch';end if;
 select count(*) into unknown_authors
 from public.shared_experience_revisions r
 where r.experience_id=root.id
   and r.changed_by is not null
   and not exists(select 1 from public.space_members sm
     where sm.space_id=root.space_id and sm.user_id=r.changed_by);
 if unknown_authors>0 then
   raise exception 'Shared-experience revision author lineage mismatch';end if;
 select count(*) into nc
 from public.shared_experience_comments c
 where c.experience_id=root.id
   and (c.archived_at is null or c.created_by=caller);
 select count(*) into nr
 from public.shared_experience_revisions r
 where r.experience_id=root.id;
 if nc+nr>500 then
   raise exception 'Shared-experience history exceeds 500 records';end if;
 -- Do not keep a reply UUID if it would point to an archived comment that
 -- the recipient was not permitted to see.
 select coalesce(jsonb_agg(
   jsonb_build_object('source_id',c.id,
     'structured',
       case when c.reply_to is not null and not exists (
         select 1 from public.shared_experience_comments parent
          where parent.id=c.reply_to and parent.experience_id=root.id
            and (parent.archived_at is null or parent.created_by=caller))
       then private.qa_structured_value(to_jsonb(c))-'reply_to'
       else private.qa_structured_value(to_jsonb(c)) end)
   order by c.created_at,c.id),'[]'::jsonb)
 into notes
 from public.shared_experience_comments c
 where c.experience_id=root.id
   and (c.archived_at is null or c.created_by=caller);
 select coalesce(jsonb_agg(
     jsonb_build_object('source_id',r.id,
       'structured',private.qa_structured_value(to_jsonb(r)))
     order by r.changed_at,r.id),'[]'::jsonb)
 into history
 from public.shared_experience_revisions r
 where r.experience_id=root.id;
 payload:=jsonb_build_object(
   'schema','onespace.shared-experience-history-preview.v1',
   'kind','shared_reference_only',
   'recipient_id',caller,'source_space_id',root.space_id,
   'root',jsonb_build_object('table','shared_experiences',
     'source_id',root.id,
     'structured',private.qa_structured_value(to_jsonb(root))),
   'comments',notes,'revisions',history,
   'visible_comment_count',nc,'revision_count',nr
 );
 if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
   raise exception 'Shared-experience history exceeds 2 MiB';end if;
 return jsonb_build_object('payload',payload,
   'payload_sha256',encode(extensions.digest(
     convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Shared written history is reference-only; archived comments are visible only to their authors. This is not an encrypted archive.');
end $fn$;
revoke all on function private.qa_shared_experience_history_preview(uuid)
 from public,anon,authenticated;
grant execute on function private.qa_shared_experience_history_preview(uuid)
 to authenticated;
-- Global archive/lifecycle readiness remains FALSE.
;

-- >>>>> 0182_qa_nested_written_history_preview.sql
-- QA 0182: explicitly classify three written parent-scoped child types.
-- A single per-recipient preview checks owner lineage, but does NOT create
-- portable archive files or permit restoration/separation.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
     where source_table in ('scrapbook_pages','trip_revisions','saved_contact_revisions')
     and relation_kind='dependent' and disposition='review_required' and not approved)<>3
 then raise exception 'Nested written-history privacy scope needs fresh review'; end if;
end $guard$;
update private.qa_archive_table_policy p
set disposition='private_shared',approved=true,reviewed_at=now(),
policy_note=case p.source_table
 when 'scrapbook_pages' then
  'Inherit memory visibility, owner-check page creator/last editor for private parents; no photos, photo IDs or media bytes. Shared contributions only from current original couple; release is a preview, not a restore.'
 when 'trip_revisions' then
  'Inherit trip visibility; private revisions require parent owner actor; shared historical changed_by must belong to original pair, NULL system actor allowed only for shared. Nested before/after sanitized to exclude media.'
 when 'saved_contact_revisions' then
  'Inherit contact visibility; only original owner private revisions, shared pair authors verified, no file/media. Revision JSON before/after is sanitized. Never restore old shared history into new space.'
end
where p.source_table in ('scrapbook_pages','trip_revisions','saved_contact_revisions')
 and p.relation_kind='dependent'
 and p.disposition='review_required' and not p.approved;

create or replace function private.qa_nested_written_history_preview(
 p_parent_table text,p_parent_id uuid
) returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 caller uuid:=auth.uid();
 source_parent text;
 source_child text;
 parent_row jsonb;
 parent_owner uuid;
 parent_space uuid;
 parent_visibility text;
 child_fk text;
 actor_col text;
 invalid_rows int;
 row_count int;
 payload_children jsonb;
 payload jsonb;
begin
 if caller is null then raise exception 'Sign in required';end if;
 if p_parent_table='memories' then
    source_parent:='memories';source_child:='scrapbook_pages';
    child_fk:='memory_id';actor_col:='created_by';
 elsif p_parent_table='shared_trips' then
    source_parent:='shared_trips';source_child:='trip_revisions';
    child_fk:='trip_id';actor_col:='changed_by';
 elsif p_parent_table='saved_contacts' then
    source_parent:='saved_contacts';source_child:='saved_contact_revisions';
    child_fk:='contact_id';actor_col:='changed_by';
 else
   raise exception 'Unsupported written-history root';
 end if;
 if (select count(*) from private.qa_archive_table_policy
     where approved and disposition='private_shared'
       and source_table in (source_parent,source_child))<>2
 then raise exception 'Written-history archive scope not approved';end if;
 if (select count(*) from public.space_members sm where sm.user_id=caller)<>1
 then raise exception 'Written-history root not found';end if;
 execute format(
   'select to_jsonb(p) from public.%I p
     join public.space_members sm on sm.space_id=p.space_id
        and sm.user_id=$2
     where p.id=$1 and (p.visibility=''shared'' or p.created_by=$2)',
     source_parent)
 into parent_row using p_parent_id,caller;
 if parent_row is null then raise exception 'Written-history root not found'; end if;
 parent_owner:=(parent_row->>'created_by')::uuid;
 parent_space:=(parent_row->>'space_id')::uuid;
 parent_visibility:=parent_row->>'visibility';
 if parent_visibility not in ('shared','private') then
   raise exception 'Unsupported written-history visibility';
 end if;
 if parent_visibility='shared' and not exists(
    select 1 from public.space_members sm
    where sm.space_id=parent_space and sm.user_id=parent_owner)
 then raise exception 'Written-history root owner lineage mismatch';end if;
 -- Reject non-owner private contributions, and unknown/shared outsider
 -- contributions. Audit entries with NULL actor are accepted for shared
 -- parents as system-generated; for private parents we fail closed.
 execute format(
   'select count(*) from public.%I ch
      where ch.%I=$1 and (
       ( $2 = ''private'' and
           (ch.%I is distinct from $3
            %s))
       or ( $2 = ''shared'' and
          (ch.%I is not null and not exists (
            select 1 from public.space_members sm
             where sm.space_id=$4 and sm.user_id=ch.%I)))
      )',
    source_child,child_fk,actor_col,
    case when source_child='scrapbook_pages'
       then 'or (ch.updated_by is not null and ch.updated_by <> $3)'
       else '' end,
    actor_col,actor_col)
 into invalid_rows using p_parent_id,parent_visibility,parent_owner,parent_space;
 if invalid_rows<>0 then
   raise exception 'Written-history contributor lineage mismatch';end if;
 -- Shared scrapbook pages must have both the creator and any editor in
 -- this same original relationship. No prior partner may be transported.
 if source_child='scrapbook_pages' and parent_visibility='shared' then
   select count(*) into invalid_rows from public.scrapbook_pages page
   where page.memory_id=p_parent_id and page.updated_by is not null
     and not exists(select 1 from public.space_members sm
        where sm.space_id=parent_space and sm.user_id=page.updated_by);
   if invalid_rows<>0 then
      raise exception 'Written-history editor lineage mismatch';end if;
 end if;
 execute format('select count(*) from public.%I where %I=$1',
    source_child,child_fk) into row_count using p_parent_id;
 if row_count>500 then raise exception 'Written-history preview exceeds 500 records';end if;
 execute format(
   'select coalesce(jsonb_agg(
      jsonb_build_object(''source_id'',ch.id,
        ''structured'',private.qa_structured_value(to_jsonb(ch)))
       order by %s,ch.id),''[]''::jsonb)
     from public.%I ch where ch.%I=$1',
     case when source_child='scrapbook_pages' then 'ch.page_order'
          else 'ch.changed_at' end,source_child,child_fk)
   into payload_children using p_parent_id;
 payload:=jsonb_build_object(
   'schema','onespace.nested-written-history-preview.v1',
   'kind',case when parent_visibility='private'
        then 'private_owner_only' else 'shared_reference_only' end,
   'owner_id',parent_owner,'recipient_id',caller,
   'source_space_id',parent_space,
   'root',jsonb_build_object('table',source_parent,'source_id',p_parent_id,
     'structured',private.qa_structured_value(parent_row)),
   'child_table',source_child,'children',payload_children,
   'child_record_count',row_count
 );
 if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
   raise exception 'Written-history preview exceeds 2 MiB';end if;
 return jsonb_build_object(
   'payload',payload,
   'payload_sha256',encode(extensions.digest(
      convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Nested written-history preview only. No uploaded media and no shared-history restoration.');
end $fn$;
revoke all on function private.qa_nested_written_history_preview(text,uuid)
 from public,anon,authenticated;
grant execute on function private.qa_nested_written_history_preview(text,uuid)
 to authenticated;
;

-- >>>>> 0183_qa_activity_nested_written_preview.sql
-- QA 0183: activity component, comment, reaction, decision and revision
-- coverage, with strict per-recipient parent/author privacy checks.
-- Preview only: never a restored or verified encrypted archive.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
   where source_table in ('activity_comments','activity_component_reactions',
       'activity_component_revisions','activity_components',
       'activity_decisions','activity_revisions')
     and relation_kind='dependent' and canonical_parent='activities'
     and disposition='review_required' and not approved)<>6 then
   raise exception 'Activity descendant classification requires review';end if;
end $guard$;
update private.qa_archive_table_policy
set disposition='private_shared',approved=true,reviewed_at=now(),
  policy_note='Activity child inherits the parent privacy. For private parents, all child contributions must be authored solely by root owner; for shared parents, all authors belong to original pair. Null system actors are blocked for private parents. Embedded media payload/voice paths excluded. Structured preview only; restore mapping and portable encryption unimplemented.'
where source_table in ('activity_comments','activity_component_reactions',
  'activity_component_revisions','activity_components',
  'activity_decisions','activity_revisions')
 and relation_kind='dependent' and canonical_parent='activities'
 and disposition='review_required' and not approved;

create or replace function private.qa_activity_nested_structured_preview(p_activity_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 caller uuid:=auth.uid();
 root public.activities%rowtype;
 t text;
 actor_col text;
 ordering text;
 child_rows jsonb;
 children jsonb:='{}'::jsonb;
 total_rows int:=0;
 bad int;
 n int;
 all_tables text[]:=array[
   'activity_components','activity_comments',
   'activity_component_reactions','activity_decisions',
   'activity_component_revisions','activity_revisions'];
 payload jsonb;
begin
 if caller is null then raise exception 'Sign in required';end if;
 select a.* into root from public.activities a
 join public.space_members m on m.space_id=a.space_id and m.user_id=caller
 where a.id=p_activity_id and
      (a.visibility='shared' or a.created_by=caller);
 if not found then raise exception 'Activity preview not found';end if;
 if (select count(*) from public.space_members where user_id=caller)<>1
 then raise exception 'Activity preview not found';end if;
 if root.visibility not in ('private','shared')
 then raise exception 'Unsupported activity visibility';end if;
 if not exists(select 1 from public.space_members m
       where m.space_id=root.space_id and m.user_id=root.created_by)
 then raise exception 'Activity owner lineage mismatch';end if;
 if (select count(*) from private.qa_archive_table_policy
     where source_table=any(array['activities']||all_tables)
       and approved and disposition='private_shared')<>7
 then raise exception 'Activity structured archive scope incomplete';end if;
 foreach t in array all_tables loop
   actor_col:=case t
     when 'activity_components' then 'created_by'
     when 'activity_comments' then 'author_id'
     when 'activity_component_reactions' then 'user_id'
     when 'activity_decisions' then 'created_by'
     else 'changed_by' end;
   -- Snapshot fields including image/voice IDs and Storage paths are
   -- recursively sanitized. A contributor from a former relationship
   -- cannot be imported into an owner-private item or old shared archive.
   execute format(
    'select count(*) from public.%I c
      where c.activity_id=$1 and
       (case when $2=''private''
          then c.%I is distinct from $3
          else c.%I is not null and not exists (
            select 1 from public.space_members m
            where m.space_id=$4 and m.user_id=c.%I)
        end)',t,actor_col,actor_col,actor_col)
    into bad using root.id,root.visibility,root.created_by,root.space_id;
   if bad<>0 then
     raise exception 'Activity child contributor lineage mismatch: %',t;end if;
   execute format('select count(*) from public.%I c
       where c.activity_id=$1',t)
     into n using root.id;
   total_rows:=total_rows+n;
   if total_rows>500 then
      raise exception 'Activity structured package exceeds 500 children';end if;
   ordering:=case t
       when 'activity_component_reactions'
         then 'c.component_id,c.user_id'
       when 'activity_revisions' then 'c.changed_at,c.id'
       when 'activity_component_revisions' then 'c.changed_at,c.id'
       else 'c.created_at,c.id' end;
   if t='activity_component_reactions' then
     execute format(
       'select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(c))
         order by %s),''[]''::jsonb)
          from public.%I c where c.activity_id=$1',ordering,t)
       into child_rows using root.id;
   else
     execute format(
       'select coalesce(jsonb_agg(jsonb_build_object(
         ''source_id'',c.id,
         ''structured'',private.qa_structured_value(to_jsonb(c)))
         order by %s),''[]''::jsonb)
          from public.%I c where c.activity_id=$1',ordering,t)
       into child_rows using root.id;
   end if;
   children:=children||jsonb_build_object(t,child_rows);
 end loop;
 payload:=jsonb_build_object(
   'schema','onespace.activity-structured-preview.v1',
   'kind',case when root.visibility='private'
      then 'private_owner_only' else 'shared_reference_only' end,
   'recipient_id',caller,'owner_id',root.created_by,
   'source_space_id',root.space_id,
   'root',jsonb_build_object('table','activities','source_id',root.id,
       'structured',private.qa_structured_value(to_jsonb(root))),
   'children',children,'child_record_count',total_rows
 );
 if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
   raise exception 'Activity structured package exceeds 2 MiB';end if;
 return jsonb_build_object('payload',payload,
   'payload_sha256',encode(extensions.digest(
     convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Written activity preview only: attachment bytes, media and paths excluded. Shared history cannot be restored.');
end $fn$;
revoke all on function private.qa_activity_nested_structured_preview(uuid)
 from public,anon,authenticated;
grant execute on function private.qa_activity_nested_structured_preview(uuid)
 to authenticated;
;

-- >>>>> 0184_qa_love_letter_privacy_preview.sql
-- QA 0184: love-letter privacy is author/availability dependent.
-- Drafts and future-open sent letters belong exclusively to author.
-- Recipient's history includes SENT and OPEN-ELIGIBLE letters only.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
    where source_table in ('couple_letters','couple_letter_reads')
      and disposition='review_required' and not approved)<>2 then
   raise exception 'Love-letter privacy requires re-review';end if;
end $guard$;
update private.qa_archive_table_policy set
 disposition='private_shared',approved=true,reviewed_at=now(),
 policy_note=case source_table when 'couple_letters' then
  'Author-private drafts and future-open sent letters are owner-only. Sent/open-eligible letters visible to original pair, strictly by open_on date. Reply-to non-visible letters stripped. Not a restorable shared archive.'
 else
  'Read receipts only accompany sent and open-eligible letters. Reader must be other original space member; no draft/future read receipts may be copied. Non-restorable shared history.'
 end
where source_table in ('couple_letters','couple_letter_reads')
 and disposition='review_required' and not approved;

create or replace function private.qa_love_letter_history_preview(p_letter_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
  me uuid:=auth.uid();
  source_letter public.couple_letters%rowtype;
  open_to_pair boolean;
  source_json jsonb;
  result_json jsonb;
  receipt_rows jsonb;
  invalid_receipts int;
  receipt_count int;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'Letter not found';end if;
 select l.* into source_letter
 from public.couple_letters l
 join public.space_members sm on sm.space_id=l.space_id and sm.user_id=me
 where l.id=p_letter_id
   and (l.author_id=me or (l.status='sent' and
       (l.open_on is null or l.open_on<=current_date)));
 if not found then raise exception 'Letter not found';end if;
 if not exists(select 1 from public.space_members m
      where m.space_id=source_letter.space_id
        and m.user_id=source_letter.author_id) then
   raise exception 'Letter source author no longer belongs to original pair';end if;
 if (select count(*) from private.qa_archive_table_policy p
     where p.source_table in ('couple_letters','couple_letter_reads')
       and p.approved and p.disposition='private_shared')<>2 then
   raise exception 'Letter history scope unapproved';end if;
 open_to_pair:=source_letter.status='sent'
   and (source_letter.open_on is null or source_letter.open_on<=current_date);
 source_json:=private.qa_structured_value(to_jsonb(source_letter));
 -- Do not expose a private draft's identifier in reply_to when its author
 -- is the only member allowed to see the referenced letter.
 if source_letter.reply_to is not null and not exists(
   select 1 from public.couple_letters linked
   where linked.id=source_letter.reply_to
     and linked.space_id=source_letter.space_id
     and (linked.author_id=me or (linked.status='sent'
       and (linked.open_on is null or linked.open_on<=current_date))))
 then
   source_json:=source_json-'reply_to';
 end if;
 select count(*) into invalid_receipts from public.couple_letter_reads r
 where r.letter_id=source_letter.id and (
   not open_to_pair
   or r.reader_id=source_letter.author_id
   or not exists(select 1 from public.space_members m
       where m.space_id=source_letter.space_id and m.user_id=r.reader_id)
 );
 if invalid_receipts<>0 then raise exception 'Letter read receipt lineage mismatch';end if;
 select count(*) into receipt_count from public.couple_letter_reads
 where letter_id=source_letter.id;
 if receipt_count>50 then raise exception 'Letter receipt history too large';end if;
 select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(r))
    order by r.opened_at,r.reader_id),'[]'::jsonb)
 into receipt_rows from public.couple_letter_reads r
 where r.letter_id=source_letter.id and open_to_pair;
 result_json:=jsonb_build_object(
   'schema','onespace.love-letter-history-preview.v1',
   'kind',case when open_to_pair then 'shared_reference_only'
      else 'author_private_only' end,
   'author_id',source_letter.author_id,'recipient_id',me,
   'source_space_id',source_letter.space_id,
   'root',jsonb_build_object('table','couple_letters',
     'source_id',source_letter.id,'structured',source_json),
   'read_receipts',receipt_rows,'receipt_count',receipt_count
 );
 if octet_length(convert_to(result_json::text,'UTF8'))>2097152 then
   raise exception 'Letter history preview too large';end if;
 return jsonb_build_object(
   'payload',result_json,
   'payload_sha256',encode(extensions.digest(
     convert_to(result_json::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Author-only draft/future letters cannot be viewed by recipient until opened. Written preview is not an archive or restore.');
end $fn$;
revoke all on function private.qa_love_letter_history_preview(uuid)
 from public,anon,authenticated;
grant execute on function private.qa_love_letter_history_preview(uuid)
 to authenticated;
;

-- >>>>> 0185_qa_place_visit_parent_scope_preview.sql
-- QA 0185: protect location/visit written history from cross-partner
-- associations. Original place's visibility controls the preview scope.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
     where source_table='place_visits' and relation_kind='root'
      and disposition='review_required' and not approved)<>1 then
   raise exception 'Place visit policy needs manual re-review';end if;
end $guard$;
update private.qa_archive_table_policy
set disposition='private_shared',approved=true,reviewed_at=now(),
 policy_note='Place visit notes inherit parent places visibility. Private root requires all visit authors be owner. Shared root requires original pair membership. Require same space_id for place and visits; optional memory link must be in same space and is stripped as nonportable navigation pointer. planned_trip_id stripped from root; written captions remain.'
where source_table='place_visits' and relation_kind='root'
  and disposition='review_required' and not approved;

create or replace function private.qa_place_visit_history_preview(p_place_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 me uuid:=auth.uid();
 p public.places%rowtype;
 bad_count int; n int;
 data jsonb; payload jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Place not found';end if;
 select places.* into p from public.places places
  join public.space_members m on m.space_id=places.space_id
    and m.user_id=me
  where places.id=p_place_id and
        (places.visibility='shared' or places.created_by=me);
 if not found then raise exception 'Place not found';end if;
 if p.visibility not in ('private','shared') then
   raise exception 'Unsupported place visibility';end if;
 if (select count(*) from private.qa_archive_table_policy
     where source_table in ('places','place_visits')
       and disposition='private_shared' and approved)<>2
 then raise exception 'Place visit archive scope unapproved';end if;
 if not exists(select 1 from public.space_members sm
      where sm.space_id=p.space_id and sm.user_id=p.created_by)
 then raise exception 'Place owner lineage mismatch';end if;
 select count(*) into bad_count from public.place_visits v
 where v.place_id=p.id and (
   v.space_id is distinct from p.space_id
   or (p.visibility='private' and v.created_by is distinct from p.created_by)
   or (p.visibility='shared' and not exists(
     select 1 from public.space_members sm
     where sm.space_id=p.space_id and sm.user_id=v.created_by))
   or (v.memory_id is not null and not exists (
     select 1 from public.memories memory
     where memory.id=v.memory_id and memory.space_id=p.space_id))
 );
 if bad_count>0 then raise exception 'Place visit association or author mismatch';end if;
 select count(*) into n from public.place_visits where place_id=p.id;
 if n>500 then raise exception 'Place visits exceed 500 records';end if;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',v.id,
    'structured',private.qa_structured_value(to_jsonb(v))-'memory_id')
    order by v.visited_on,v.id),'[]'::jsonb)
 into data from public.place_visits v where v.place_id=p.id;
 payload:=jsonb_build_object(
  'schema','onespace.place-visit-history-preview.v1',
  'kind',case when p.visibility='private' then 'private_owner_only'
       else 'shared_reference_only' end,
  'owner_id',p.created_by,'recipient_id',me,'source_space_id',p.space_id,
  'root',jsonb_build_object('table','places','source_id',p.id,
    'structured',private.qa_structured_value(to_jsonb(p))-'planned_trip_id'),
  'visits',data,'visit_count',n
 );
 if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
   raise exception 'Place visit history exceeds 2 MiB';end if;
 return jsonb_build_object('payload',payload,
   'payload_sha256',encode(extensions.digest(
      convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Written place visits only. Previous relationship links are nonportable; no restore or file attachments.');
end $fn$;
revoke all on function private.qa_place_visit_history_preview(uuid)
 from public,anon,authenticated;
grant execute on function private.qa_place_visit_history_preview(uuid)
 to authenticated;
;

-- >>>>> 0186_qa_partner_checkin_ack_history_preview.sql
-- QA 0186: partner check-in acknowledgement is historical shared content
-- only after the referenced check-in was actually responded to.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
   where source_table='partner_checkin_acknowledgements'
     and relation_kind='dependent'
     and canonical_parent='partner_checkin_requests'
     and disposition='review_required' and not approved)<>1 then
   raise exception 'Check-in receipt scope needs review';end if;
end $guard$;
update private.qa_archive_table_policy set disposition='shared_only',
  approved=true,reviewed_at=now(),
  policy_note='Response acknowledgement belongs to original sender and recipient only, after responded_at. Acknowledging actor must be original sender, as enforced by insert RLS; outsider and incomplete replies fail closed. Old shared history reference-only, cannot be restored into new relationship.'
where source_table='partner_checkin_acknowledgements'
 and relation_kind='dependent'
 and canonical_parent='partner_checkin_requests'
 and disposition='review_required' and not approved;

create or replace function private.qa_checkin_ack_history_preview(p_request_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
  me uuid:=auth.uid();
  root public.partner_checkin_requests%rowtype;
  check_row jsonb;
  row_count int;
  payload jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Check-in history not found';end if;
 select r.* into root from public.partner_checkin_requests r
 join public.space_members m on m.space_id=r.space_id and m.user_id=me
 where r.id=p_request_id and me in (r.sender_id,r.recipient_id);
 if not found then raise exception 'Check-in history not found';end if;
 if (select count(*) from private.qa_archive_table_policy
   where source_table in ('partner_checkin_requests',
      'partner_checkin_acknowledgements')
      and disposition='shared_only' and approved)<>2 then
   raise exception 'Check-in written-history scope not approved';end if;
 if not exists(select 1 from public.space_members m
     where m.space_id=root.space_id and m.user_id=root.sender_id)
 or not exists(select 1 from public.space_members m
     where m.space_id=root.space_id and m.user_id=root.recipient_id)
 then raise exception 'Check-in original pair lineage mismatch';end if;
 select count(*) into row_count from public.partner_checkin_acknowledgements ack
 where ack.request_id=root.id;
 if row_count>1 then raise exception 'Invalid duplicate check-in receipt';end if;
 if row_count>0 and (root.responded_at is null or
      exists(select 1 from public.partner_checkin_acknowledgements a
         where a.request_id=root.id and a.user_id<>root.sender_id))
 then raise exception 'Check-in acknowledgement lineage or response mismatch';end if;
 select to_jsonb(a) into check_row
 from public.partner_checkin_acknowledgements a
 where a.request_id=root.id;
 payload:=jsonb_build_object(
   'schema','onespace.partner-checkin-ack-preview.v1',
   'kind','shared_reference_only',
   'sender_id',root.sender_id,'recipient_id',me,
   'source_space_id',root.space_id,
   'root',jsonb_build_object(
     'table','partner_checkin_requests','source_id',root.id,
     'structured',private.qa_structured_value(to_jsonb(root))),
   'acknowledgement',case when check_row is null then 'null'::jsonb
       else private.qa_structured_value(check_row) end
 );
 return jsonb_build_object(
   'payload',payload,
   'payload_sha256',encode(extensions.digest(
      convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,
   'encrypted',false,'is_verified_archive',false,
   'can_restore',false,'safe_to_separate',false,
   'warning','Old shared check-in history is reference-only and cannot be restored as active partner content.');
end $fn$;
revoke all on function private.qa_checkin_ack_history_preview(uuid)
 from public,anon,authenticated;
grant execute on function private.qa_checkin_ack_history_preview(uuid)
 to authenticated;
;

-- >>>>> 0187_qa_reminder_written_history_preview.sql
-- QA 0187: owner-checked reminder receipt/action written history.
-- No notifications are restored, scheduled or dispatched by previews.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
 where source_table in ('reminder_actions','reminder_recipients')
 and canonical_parent='reminders' and relation_kind='dependent'
 and disposition='review_required' and not approved) <> 2 then
 raise exception 'Reminder recipient/action scope must be re-reviewed';end if;
end $guard$;
update private.qa_archive_table_policy
set disposition='private_shared',approved=true,reviewed_at=now(),
policy_note=case source_table
 when 'reminder_actions' then
 'Historical action notes follow reminder owner/private or original pair shared scope; recipient belongs to parent pair, actor belongs to pair or NULL system action; private parent requires actor/recipient owner. Never reschedule actions on restore.'
 else 'Recipient state/outcome text follows parent privacy; private parent permits owner-only recipient. In shared original pair recipient and historical status are reference only; next alert/snooze state excluded from portable preview.'
end
where source_table in ('reminder_actions','reminder_recipients')
 and disposition='review_required' and not approved;

create or replace function private.qa_reminder_written_history_preview(p_reminder_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 me uuid:=auth.uid(); root public.reminders%rowtype; n int; bad int; children jsonb; actions jsonb; recipients jsonb; payload jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'Reminder not found';end if;
 select r.* into root from public.reminders r
 join public.space_members m on m.space_id=r.space_id and m.user_id=me
 where r.id=p_reminder_id and (r.visibility='shared' or r.created_by=me);
 if not found then raise exception 'Reminder not found';end if;
 if root.visibility not in ('shared','private') then
 raise exception 'Unsupported reminder visibility';end if;
 if (select count(*) from private.qa_archive_table_policy p
 where p.source_table in ('reminders','reminder_actions','reminder_recipients')
 and p.approved and p.disposition='private_shared')<>3
 then raise exception 'Reminder history catalog not approved';end if;
 if not exists(select 1 from public.space_members s
 where s.space_id=root.space_id and s.user_id=root.created_by)
 then raise exception 'Reminder owner lineage mismatch';end if;
 select count(*) into bad from public.reminder_recipients x
 where x.reminder_id=root.id and (
  (root.visibility='private' and x.recipient_id<>root.created_by)
  or (root.visibility='shared' and not exists(
    select 1 from public.space_members sm where sm.space_id=root.space_id and sm.user_id=x.recipient_id))
 );
 if bad>0 then raise exception 'Reminder recipient lineage mismatch';end if;
 select count(*) into bad from public.reminder_actions x
 where x.reminder_id=root.id and (
  (root.visibility='private' and
    (x.recipient_id<>root.created_by or x.actor_id is distinct from root.created_by))
  or (root.visibility='shared' and (
    not exists(select 1 from public.space_members sm where sm.space_id=root.space_id and sm.user_id=x.recipient_id)
    or (x.actor_id is not null and not exists(
      select 1 from public.space_members sm where sm.space_id=root.space_id and sm.user_id=x.actor_id))))
 );
 if bad>0 then raise exception 'Reminder action lineage mismatch';end if;
 select count(*) into n from (
  select id::text from public.reminder_recipients where reminder_id=root.id
  union all select id::text from public.reminder_actions where reminder_id=root.id
 ) records;
 if n>500 then raise exception 'Reminder history exceeds 500 records';end if;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',x.id,
   'structured',private.qa_structured_value(to_jsonb(x))
     - 'next_alert_at' - 'last_notified_at' - 'snoozed_until' - 'open_occurrence_at')
   order by x.updated_at,x.id),'[]'::jsonb)
 into recipients from public.reminder_recipients x where x.reminder_id=root.id;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',x.id,
   'structured',private.qa_structured_value(to_jsonb(x)) - 'next_alert_at')
   order by x.recorded_at,x.id),'[]'::jsonb)
 into actions from public.reminder_actions x where x.reminder_id=root.id;
 children:=jsonb_build_object('reminder_recipients',recipients,'reminder_actions',actions);
 payload:=jsonb_build_object(
   'schema','onespace.reminder-written-history-preview.v1',
   'kind',case when root.visibility='private' then 'private_owner_only' else 'shared_reference_only' end,
   'recipient_id',me,'owner_id',root.created_by,'source_space_id',root.space_id,
   'root',jsonb_build_object('table','reminders','source_id',root.id,
      'structured',private.qa_structured_value(to_jsonb(root))-'source_id'),
   'children',children,'child_record_count',n
 );
 if octet_length(convert_to(payload::text,'UTF8'))>2097152 then
 raise exception 'Reminder preview exceeds 2 MiB';end if;
 return jsonb_build_object('payload',payload,'payload_sha256',encode(
 extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex'),
 'media_included',false,'documents_included',false,'encrypted',false,
 'is_verified_archive',false,'can_restore',false,'safe_to_separate',false,
 'warning','Historic outcome notes only; reminder scheduling, alerts and former-partner recipients cannot be restored.');
end $fn$;
revoke all on function private.qa_reminder_written_history_preview(uuid) from public,anon,authenticated;
grant execute on function private.qa_reminder_written_history_preview(uuid) to authenticated;
;

-- >>>>> 0188_qa_occasion_budget_history_preview.sql
-- QA 0188: four occasion-budget descendants with strict cross-plan links.
-- Historical package only; no old order, purchase, shipping state replay.
do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy where
 source_table in ('occasion_budget_items','occasion_budget_log',
 'occasion_plan_revisions','occasion_proposal_items')
 and disposition='review_required' and relation_kind='dependent' and not approved)<>4
 then raise exception 'Occasion budget/proposal archive scope must be reviewed';end if;
end $guard$;
update private.qa_archive_table_policy set approved=true,
 disposition='private_shared',reviewed_at=now(),
 policy_note=case source_table
 when 'occasion_budget_items' then 'Owner/private or original pair shared budget items; verify optional activity/component links belong to same space, remove old navigation identifiers, sanitize media and preserve written budget/order text; never replay purchases.'
 when 'occasion_budget_log' then 'Budget revisions tied to same parent plan and budget item, actor identity verified; scrub recursive before/after media; reference-only history.'
 when 'occasion_plan_revisions' then 'Audit event must refer to plan or a step on same plan; actor owner for private, original pair for shared, null system only for shared. Sanitize before/after snapshots.'
 else 'Proposal to budget item joins must reference items on exactly same occasion plan; proposal creator owner when private, original pair when shared. No cross-plan private link can travel.'
 end
where source_table in ('occasion_budget_items','occasion_budget_log',
'occasion_plan_revisions','occasion_proposal_items')
 and disposition='review_required' and not approved;

create or replace function private.qa_occasion_budget_history_preview(p_plan_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare me uuid:=auth.uid(); root public.occasion_plans%rowtype;
 bad int; total_count int; i jsonb; l jsonb; r jsonb; associations jsonb;
 package jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Occasion plan not found';end if;
 select p.* into root from public.occasion_plans p
 join public.space_members sm on sm.space_id=p.space_id and sm.user_id=me
 where p.id=p_plan_id and (p.visibility='shared' or p.created_by=me);
 if not found then raise exception 'Occasion plan not found';end if;
 if root.visibility not in ('shared','private')
 then raise exception 'Unsupported occasion visibility';end if;
 if not exists(select 1 from public.space_members sm
 where sm.space_id=root.space_id and sm.user_id=root.created_by)
 then raise exception 'Occasion owner lineage mismatch';end if;
 if (select count(*) from private.qa_archive_table_policy where approved and
 disposition='private_shared' and source_table in
 ('occasion_plans','occasion_budget_items','occasion_budget_log',
 'occasion_plan_revisions','occasion_proposal_items','occasion_proposals'))<>6
 then raise exception 'Occasion budget coverage not approved';end if;

 select count(*) into bad from public.occasion_budget_items x
 where x.plan_id=root.id and (
 (root.visibility='private' and x.created_by<>root.created_by)
 or (root.visibility='shared' and not exists(select 1 from public.space_members sm
   where sm.space_id=root.space_id and sm.user_id=x.created_by))
 or (x.source_activity_id is not null and not exists(select 1 from public.activities a
   where a.id=x.source_activity_id and a.space_id=root.space_id
     and (a.visibility='shared' or a.created_by=me)))
 or (x.source_component_id is not null and not exists(
    select 1 from public.activity_components ac
      join public.activities a on a.id=ac.activity_id
    where ac.id=x.source_component_id and a.space_id=root.space_id
      and (a.visibility='shared' or a.created_by=me)
      and (x.source_activity_id is null or a.id=x.source_activity_id)))
 );
 if bad>0 then raise exception 'Occasion item contributor or cross-space link mismatch';end if;

 select count(*) into bad from public.occasion_budget_log x
 where x.plan_id=root.id and (
 (root.visibility='private' and x.actor_id is distinct from root.created_by)
 or (root.visibility='shared' and x.actor_id is not null
   and not exists(select 1 from public.space_members sm
   where sm.space_id=root.space_id and sm.user_id=x.actor_id))
 or (x.item_id is not null and not exists(select 1 from public.occasion_budget_items it
   where it.id=x.item_id and it.plan_id=root.id))
 );
 if bad>0 then raise exception 'Occasion log actor or item lineage mismatch';end if;

 select count(*) into bad from public.occasion_plan_revisions x
 where x.plan_id=root.id and (
 (root.visibility='private' and x.changed_by is distinct from root.created_by)
 or (root.visibility='shared' and x.changed_by is not null
   and not exists(select 1 from public.space_members sm
   where sm.space_id=root.space_id and sm.user_id=x.changed_by))
 or (x.record_kind='plan' and x.record_id<>root.id)
 or (x.record_kind='step' and not exists(select 1 from public.occasion_plan_steps st
   where st.id=x.record_id and st.plan_id=root.id))
 );
 if bad>0 then raise exception 'Occasion revision actor or step lineage mismatch';end if;

 select count(*) into bad from public.occasion_proposals p
 where p.plan_id=root.id and (
 (root.visibility='private' and p.created_by<>root.created_by)
 or (root.visibility='shared' and not exists(select 1 from public.space_members sm
   where sm.space_id=root.space_id and sm.user_id=p.created_by)));
 if bad>0 then raise exception 'Occasion proposal contributor lineage mismatch';end if;
 select count(*) into bad
 from public.occasion_proposal_items link
 join public.occasion_proposals prop on prop.id=link.proposal_id
 where prop.plan_id=root.id and not exists(select 1 from public.occasion_budget_items item
 where item.id=link.item_id and item.plan_id=root.id);
 if bad>0 then raise exception 'Occasion proposal item cross-plan association mismatch';end if;
 -- Inverse links are also denied: a proposal from some other plan may point
 -- into our budget even if the regular forward scan doesn't find it.
 select count(*) into bad from public.occasion_proposal_items link
 join public.occasion_budget_items item on item.id=link.item_id
 join public.occasion_proposals prop on prop.id=link.proposal_id
 where item.plan_id=root.id and prop.plan_id<>root.id;
 if bad>0 then raise exception 'Occasion budget item attached to foreign proposal';end if;

 select (select count(*) from public.occasion_budget_items where plan_id=root.id)
   +(select count(*) from public.occasion_budget_log where plan_id=root.id)
   +(select count(*) from public.occasion_plan_revisions where plan_id=root.id)
   +(select count(*) from public.occasion_proposal_items link
       join public.occasion_proposals p on p.id=link.proposal_id where p.plan_id=root.id)
 into total_count;
 if total_count>500 then raise exception 'Occasion budget history exceeds 500 records';end if;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',x.id,
 'structured',private.qa_structured_value(to_jsonb(x))
 -'source_activity_id'-'source_component_id') order by x.created_at,x.id),'[]'::jsonb)
 into i from public.occasion_budget_items x where x.plan_id=root.id;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',x.id,
 'structured',private.qa_structured_value(to_jsonb(x))) order by x.logged_at,x.id),'[]'::jsonb)
 into l from public.occasion_budget_log x where x.plan_id=root.id;
 select coalesce(jsonb_agg(jsonb_build_object('source_id',x.id,
 'structured',private.qa_structured_value(to_jsonb(x))) order by x.changed_at,x.id),'[]'::jsonb)
 into r from public.occasion_plan_revisions x where x.plan_id=root.id;
 select coalesce(jsonb_agg(jsonb_build_object('proposal_id',x.proposal_id,
 'item_id',x.item_id,'created_at',x.created_at)
 order by x.proposal_id,x.item_id),'[]'::jsonb)
 into associations from public.occasion_proposal_items x
 join public.occasion_proposals p on p.id=x.proposal_id
 where p.plan_id=root.id;
 package:=jsonb_build_object('schema','onespace.occasion-budget-history-preview.v1',
 'kind',case when root.visibility='private' then 'private_owner_only' else 'shared_reference_only' end,
 'owner_id',root.created_by,'recipient_id',me,'source_space_id',root.space_id,
 'root',jsonb_build_object('table','occasion_plans','source_id',root.id,
 'structured',private.qa_structured_value(to_jsonb(root))-'source_ref'),
 'children',jsonb_build_object('occasion_budget_items',i,
   'occasion_budget_log',l,'occasion_plan_revisions',r,
   'occasion_proposal_items',associations),
 'child_record_count',total_count);
 if octet_length(convert_to(package::text,'UTF8'))>2097152
 then raise exception 'Occasion budget preview exceeds 2 MiB';end if;
 return jsonb_build_object('payload',package,
 'payload_sha256',encode(extensions.digest(convert_to(package::text,'UTF8'),'sha256'),'hex'),
 'media_included',false,'documents_included',false,'encrypted',false,
 'is_verified_archive',false,'can_restore',false,'safe_to_separate',false,
 'warning','Financial/order details are written history only. No purchases, external links, or shared relationship associations are restored.');
end $fn$;
revoke all on function private.qa_occasion_budget_history_preview(uuid) from public,anon,authenticated;
grant execute on function private.qa_occasion_budget_history_preview(uuid) to authenticated;
;

