-- >>>>> 0190_qa_polymorphic_link_privacy_preview.sql
-- QA 0190: polymorphic item/note references must validate BOTH ends
-- against the same original space; no reference may leak partner-private IDs.
create or replace function private.qa_portable_target_scope(
 p_kind text,p_id uuid,p_space uuid,p_recipient uuid
) returns text language plpgsql stable security definer set search_path='' as $fn$
declare tab text; v record;
begin
 if auth.uid() is null or auth.uid()<>p_recipient then
 return 'blocked';end if;
 if not exists(select 1 from public.space_members sm
  where sm.space_id=p_space and sm.user_id=p_recipient) then
 return 'blocked';end if;
 if p_kind='experience' then
   if exists(select 1 from public.shared_experiences x
     where x.id=p_id and x.space_id=p_space) then return 'shared';end if;
   return 'blocked';
 end if;
 tab:=case p_kind
 when 'activity' then 'activities' when 'trip' then 'shared_trips'
 when 'occasion' then 'occasion_plans' when 'event' then 'space_events'
 when 'reminder' then 'reminders' when 'task' then 'tasks'
 when 'note' then 'notes' when 'memory' then 'memories'
 else null end;
 if tab is null then return 'blocked';end if;
 execute format('select t.visibility,t.created_by from public.%I t
 where t.id=$1 and t.space_id=$2',tab)
 into v using p_id,p_space;
 if not found then return 'blocked';end if;
 if v.visibility='shared' then return 'shared';end if;
 if v.visibility='private' and v.created_by=p_recipient
 then return 'private';end if;
 return 'blocked';
end $fn$;
revoke all on function private.qa_portable_target_scope(text,uuid,uuid,uuid)
 from public,anon,authenticated;

do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
 where source_table in ('note_references','item_links')
  and not approved and disposition='review_required')<>2 then
 raise exception 'Polymorphic association table requires fresh review';end if;
end $guard$;
update private.qa_archive_table_policy set
 disposition='private_shared',approved=true,reviewed_at=now(),
 policy_note=case source_table
 when 'note_references' then
 'Reference must remain in same original space and be visible to the recipient. A shared note never exports references to private targets; a private note exports owner-only links. All target pointers are navigation-only and cannot be reattached without trusted restore ID mapping.'
 else
 'Both polymorphic link endpoints must exist in same original space. An endpoint owner-private is visible only to its owner and cannot be exported as the other member; the link creator must own private endpoints. Old links never become live connections to a new relationship.'
 end
where source_table in ('note_references','item_links') and disposition='review_required' and not approved;

create or replace function private.qa_note_reference_history_preview(p_note_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare me uuid:=auth.uid(); root public.notes%rowtype; invalid int; n int;
 rows jsonb; package jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Note not found';end if;
 select x.* into root from public.notes x
 join public.space_members sm on sm.space_id=x.space_id and sm.user_id=me
 where x.id=p_note_id and (x.visibility='shared' or x.created_by=me);
 if not found then raise exception 'Note not found';end if;
 if root.visibility not in ('shared','private') then
 raise exception 'Invalid note visibility';end if;
 if (select count(*) from private.qa_archive_table_policy where approved and disposition='private_shared'
 and source_table in ('notes','note_references'))<>2
 then raise exception 'Note associations not approved';end if;
 select count(*) into invalid from public.note_references x
 where x.note_id=root.id and (
   (root.visibility='private' and x.created_by<>root.created_by)
   or (root.visibility='shared' and not exists(select 1 from public.space_members sm
      where sm.space_id=root.space_id and sm.user_id=x.created_by))
   or private.qa_portable_target_scope(x.target_kind,x.target_id,root.space_id,me)='blocked'
   or (root.visibility='shared' and
      private.qa_portable_target_scope(x.target_kind,x.target_id,root.space_id,me)<>'shared')
 );
 if invalid>0 then raise exception 'Note target visibility, author or space mismatch';end if;
 select count(*) into n from public.note_references x where x.note_id=root.id;
 if n>500 then raise exception 'Note references exceed 500 links';end if;
 select coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(x))
  order by x.created_at,x.id),'[]'::jsonb)
 into rows from public.note_references x where x.note_id=root.id;
 package:=jsonb_build_object('schema','onespace.note-reference-preview.v1',
 'kind',case when root.visibility='private' then 'private_owner_only' else 'shared_reference_only' end,
 'owner_id',root.created_by,'recipient_id',me,'source_space_id',root.space_id,
 'root',jsonb_build_object('table','notes','source_id',root.id,
 'structured',private.qa_structured_value(to_jsonb(root))),
 'links',rows,'link_count',n);
 if octet_length(convert_to(package::text,'UTF8'))>2097152
 then raise exception 'Note reference preview exceeds 2 MiB';end if;
 return jsonb_build_object('payload',package,
 'payload_sha256',encode(extensions.digest(convert_to(package::text,'UTF8'),'sha256'),'hex'),
 'media_included',false,'documents_included',false,'encrypted',false,
 'is_verified_archive',false,'can_restore',false,'safe_to_separate',false,
 'warning','Link IDs are historical references only and must be revalidated/remapped for any private restore.');
end $fn$;
revoke all on function private.qa_note_reference_history_preview(uuid) from public,anon,authenticated;
grant execute on function private.qa_note_reference_history_preview(uuid) to authenticated;

create or replace function private.qa_item_link_history_preview(p_link_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare me uuid:=auth.uid(); link_row public.item_links%rowtype;
 left_scope text;right_scope text;package jsonb;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'Link not found';end if;
 select x.* into link_row from public.item_links x
 join public.space_members sm on sm.space_id=x.space_id and sm.user_id=me
 where x.id=p_link_id;
 if not found then raise exception 'Link not found';end if;
 if (select count(*) from private.qa_archive_table_policy
 where source_table='item_links' and approved and disposition='private_shared')<>1
 then raise exception 'Link scope not approved';end if;
 if not exists(select 1 from public.space_members sm
 where sm.space_id=link_row.space_id and sm.user_id=link_row.created_by)
 then raise exception 'Link author lineage mismatch';end if;
 left_scope:=private.qa_portable_target_scope(
    link_row.from_kind,link_row.from_id,link_row.space_id,me);
 right_scope:=private.qa_portable_target_scope(
    link_row.to_kind,link_row.to_id,link_row.space_id,me);
 if left_scope='blocked' or right_scope='blocked' then
 raise exception 'Link not found';end if;
 -- A link involving private records is owner-private even if the other
 -- endpoint is shared. The link creator must be the recipient/owner.
 if (left_scope='private' or right_scope='private')
     and link_row.created_by<>me then
 raise exception 'Link private endpoint author mismatch';end if;
 package:=jsonb_build_object('schema','onespace.item-link-reference-preview.v1',
 'kind',case when left_scope='shared' and right_scope='shared'
      then 'shared_reference_only' else 'private_owner_only' end,
 'owner_id',link_row.created_by,'recipient_id',me,
 'source_space_id',link_row.space_id,
 'link',private.qa_structured_value(to_jsonb(link_row)));
 return jsonb_build_object('payload',package,
 'payload_sha256',encode(extensions.digest(convert_to(package::text,'UTF8'),'sha256'),'hex'),
 'media_included',false,'documents_included',false,'encrypted',false,
 'is_verified_archive',false,'can_restore',false,'safe_to_separate',false,
 'warning','Link is history only; old source IDs are not actionable in another relationship.');
end $fn$;
revoke all on function private.qa_item_link_history_preview(uuid) from public,anon,authenticated;
grant execute on function private.qa_item_link_history_preview(uuid) to authenticated;
;

-- >>>>> 0191_qa_polymorphic_dynamic_lookup_guard.sql
-- QA 0191: PL/pgSQL dynamic EXECUTE does not update FOUND.
-- Check the fetched record itself; otherwise every valid link is rejected.
create or replace function private.qa_portable_target_scope(
 p_kind text,p_id uuid,p_space uuid,p_recipient uuid
) returns text language plpgsql stable security definer set search_path='' as $fn$
declare tab text; v record;
begin
 if auth.uid() is null or auth.uid()<>p_recipient then
 return 'blocked';end if;
 if not exists(select 1 from public.space_members sm
  where sm.space_id=p_space and sm.user_id=p_recipient) then
 return 'blocked';end if;
 if p_kind='experience' then
   if exists(select 1 from public.shared_experiences x
     where x.id=p_id and x.space_id=p_space) then return 'shared';end if;
   return 'blocked';
 end if;
 tab:=case p_kind
 when 'activity' then 'activities' when 'trip' then 'shared_trips'
 when 'occasion' then 'occasion_plans' when 'event' then 'space_events'
 when 'reminder' then 'reminders' when 'task' then 'tasks'
 when 'note' then 'notes' when 'memory' then 'memories'
 else null end;
 if tab is null then return 'blocked';end if;
 execute format('select t.visibility,t.created_by from public.%I t
 where t.id=$1 and t.space_id=$2',tab)
 into v using p_id,p_space;
 if v is null then return 'blocked';end if;
 if v.visibility='shared' then return 'shared';end if;
 if v.visibility='private' and v.created_by=p_recipient
 then return 'private';end if;
 return 'blocked';
end $fn$;
revoke all on function private.qa_portable_target_scope(text,uuid,uuid,uuid) from public,anon,authenticated;
;

-- >>>>> 0192_qa_record_action_history_scope_preview.sql
-- QA 0192: last remaining space-linked table, action-history event audit.
-- Every one of 15 record kinds resolves to an original-space source and
-- caller visibility. Deleted/mismatched parents fail closed, never replay.
create or replace function private.qa_action_history_record_scope(
 p_kind text,p_id uuid,p_space uuid,p_recipient uuid
) returns text language plpgsql stable security definer set search_path='' as $fn$
declare tab text; v record; membership int;
begin
 if auth.uid() is null or auth.uid()<>p_recipient then return 'blocked';end if;
 if not exists(select 1 from public.space_members m
  where m.space_id=p_space and m.user_id=p_recipient) then return 'blocked';end if;
 if p_kind in ('note','task','memory','event','reminder','occasion','trip','activity','experience') then
 return private.qa_portable_target_scope(p_kind,p_id,p_space,p_recipient);
 end if;
 if p_kind='experience_comment' then
   select c.created_by,c.archived_at,x.space_id into v
     from public.shared_experience_comments c
     join public.shared_experiences x on x.id=c.experience_id
     where c.id=p_id and x.space_id=p_space;
   if v is null then return 'blocked';end if;
   if v.archived_at is not null then
     return case when v.created_by=p_recipient then 'private' else 'blocked' end;
   end if;
   return 'shared';
 end if;
 if p_kind='checkin_request' then
  if exists(select 1 from public.partner_checkin_requests r
      where r.id=p_id and r.space_id=p_space and p_recipient in (r.sender_id,r.recipient_id)
        and exists(select 1 from public.space_members m where m.space_id=p_space and m.user_id=r.sender_id)
        and exists(select 1 from public.space_members m where m.space_id=p_space and m.user_id=r.recipient_id))
  then return 'shared';end if;
  return 'blocked';
 end if;
 tab:=case p_kind
 when 'goal' then 'goals'
 when 'contact' then 'saved_contacts'
 when 'sort_item' then 'items_to_sort'
 when 'checkin' then 'daily_checkins'
 else null end;
 if tab is null then return 'blocked';end if;
 execute format('select t.created_by,t.visibility from public.%I t
 where t.id=$1 and t.space_id=$2',tab) into v using p_id,p_space;
 if v is null then return 'blocked';end if;
 if v.visibility='shared' then return 'shared';end if;
 if v.visibility='private' and v.created_by=p_recipient then return 'private';end if;
 return 'blocked';
end $fn$;
revoke all on function private.qa_action_history_record_scope(text,uuid,uuid,uuid)
 from public,anon,authenticated;

do $guard$
begin
 if (select count(*) from private.qa_archive_table_policy
     where source_table='record_action_history' and relation_kind='root'
       and disposition='review_required' and not approved)<>1 then
 raise exception 'Action-history root classification requires review';end if;
end $guard$;
update private.qa_archive_table_policy set approved=true,
 disposition='private_shared',reviewed_at=now(),
 policy_note='Every action must resolve through its 15 record kinds to an existing original-space source with recipient-scoped visibility; archived experience comments are author-only, partner check-in requests require original pair, and private source audit actors must be owner. Missing/foreign parent fails closed. Written audit event is reference-only and must not be replayed as new actions.'
where source_table='record_action_history'
 and relation_kind='root' and disposition='review_required' and not approved;

create or replace function private.qa_record_action_history_preview(p_history_id bigint)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare me uuid:=auth.uid(); hist public.record_action_history%rowtype;
 scope text; payload jsonb; bad int;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'History action not found';end if;
 select h.* into hist from public.record_action_history h
 join public.space_members sm on sm.space_id=h.space_id and sm.user_id=me
 where h.id=p_history_id;
 if not found then raise exception 'History action not found';end if;
 if (select count(*) from private.qa_archive_table_policy
 where source_table='record_action_history' and approved
 and disposition='private_shared')<>1 then raise exception 'Audit archive scope not approved';end if;
 scope:=private.qa_action_history_record_scope(hist.record_kind,hist.record_id,hist.space_id,me);
 if scope='blocked' then raise exception 'History action not found';end if;
 if scope='private' and hist.actor_id is not null and hist.actor_id<>me
 then raise exception 'Private record audit actor mismatch';end if;
 if scope='shared' and hist.actor_id is not null and not exists(
   select 1 from public.space_members sm
   where sm.space_id=hist.space_id and sm.user_id=hist.actor_id)
 then raise exception 'Shared record audit actor mismatch';end if;
 payload:=jsonb_build_object(
   'schema','onespace.record-action-history-preview.v1',
   'kind',case when scope='private' then 'private_owner_only' else 'shared_reference_only' end,
   'recipient_id',me,'source_space_id',hist.space_id,
   'event',private.qa_structured_value(to_jsonb(hist)));
 return jsonb_build_object('payload',payload,
   'payload_sha256',encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex'),
   'media_included',false,'documents_included',false,'encrypted',false,
   'is_verified_archive',false,'can_restore',false,'safe_to_separate',false,
   'warning','This is an auditable historical event, not an instruction to replay actions or restore private/shared records.');
end $fn$;
revoke all on function private.qa_record_action_history_preview(bigint)
 from public,anon,authenticated;
grant execute on function private.qa_record_action_history_preview(bigint)
 to authenticated;
;

-- >>>>> 0193_qa_catalog_truthful_archive_readiness.sql
-- QA 0193: milestone truthfulness. All 69 classifications are now
-- approved, but this MUST NOT enable archive, restore or destructive gates.
CREATE OR REPLACE FUNCTION private.qa_archive_catalog_coverage()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid:=auth.uid();
  sid uuid;
  n_unregistered_roots int;
  n_unregistered_dependents int;
  n_roots_pending int;
  n_children_pending int;
  n_approved int;
  n_excluded_media int;
  related jsonb;
begin
  if me is null then raise exception 'Sign in required'; end if;
  if (select count(*) from public.space_members where user_id=me)<>1 then
    return jsonb_build_object('has_space',false,
      'classification_complete',false,'safe_to_archive',false);
  end if;
  select space_id into sid from public.space_members where user_id=me;

  select count(*) into n_unregistered_roots
  from (select distinct c.table_name from information_schema.columns c
        where c.table_schema='public' and c.column_name='space_id'
        union select 'spaces') r
  where not exists(select 1 from private.qa_archive_table_policy p
    where p.source_table=r.table_name and p.relation_kind='root');

  related:=private.space_archive_dependency_inventory();
  select count(*) into n_unregistered_dependents
  from jsonb_array_elements(coalesce(related->'details','[]'::jsonb)) elem
  where not exists(select 1 from private.qa_archive_table_policy p
    where p.source_table=elem->>'table' and p.relation_kind='dependent');

  select count(*) into n_roots_pending from private.qa_archive_table_policy
    where relation_kind='root' and not approved;
  select count(*) into n_children_pending from private.qa_archive_table_policy
    where relation_kind='dependent' and not approved;
  select count(*) into n_approved from private.qa_archive_table_policy where approved;
  select count(*) into n_excluded_media from private.qa_archive_table_policy
    where disposition='media_excluded' and approved;

  return jsonb_build_object('has_space',true,
    'catalog_version',1,'total_tables',(select count(*) from private.qa_archive_table_policy),
    'approved_table_policies',n_approved,'root_types_pending',n_roots_pending,
    'dependent_types_pending',n_children_pending,
    'unregistered_root_types',n_unregistered_roots,
    'unregistered_dependent_types',n_unregistered_dependents,
    'media_types_excluded',n_excluded_media,
    'classification_complete',n_roots_pending=0 and n_children_pending=0
      and n_unregistered_roots=0 and n_unregistered_dependents=0,
    'safe_to_archive',false,'safe_to_separate',false,
    'encrypted_portable_archive_complete',false,
    'trusted_private_restore_complete',false,
    'source_of_truth_cutover_complete',false,
    'reason',case when n_roots_pending=0 and n_children_pending=0
      and n_unregistered_roots=0 and n_unregistered_dependents=0
    then 'Table classification is complete. Full encrypted archive generation, verified restoration, relationship-boundary migration and end-to-end acceptance remain incomplete. Leave/remove/delete remain disabled.'
    else 'Incomplete ownership classification or newly detected schema relationships block archival and relationship separation.' end);
end $function$
;
;

