     fault_where:=fault_where||' or c.recipient_id<>$2';
  elsif source_table='note_references' then
     fault_where:=fault_where||
       ' or private.qa_portable_target_scope(c.target_kind,c.target_id,p.space_id,$2)=''blocked''';
