 to authenticated;
;

-- >>>>> 0205_qa_archive_source_coverage_report.sql
-- QA 0205: unify all 69 classified *table family* categories into
-- a truthful per-recipient source coverage report. Not a portable archive.
create or replace function private.qa_archive_source_coverage_report()
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 me uuid:=auth.uid(); sid uuid;
 owner_private jsonb; shared_only jsonb;
 excluded_media int; excluded_operational int; classified int;
 digest_value text;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Exactly one active relationship required';end if;
 select space_id into sid from public.space_members where user_id=me;
 select count(*) into classified from private.qa_archive_table_policy where approved;
 select count(*) into excluded_media
 from private.qa_archive_table_policy where approved and disposition='media_excluded';
 select count(*) into excluded_operational
 from private.qa_archive_table_policy where approved and disposition='system_excluded';
 if classified<>69 or excluded_media<>4 or excluded_operational<>7
 or (private.qa_archive_catalog_coverage()->>'classification_complete')<>'true'
 then raise exception 'Archive classification schema is out of date';end if;

 owner_private:=private.qa_private_source_inventory();
 shared_only:=private.qa_shared_only_source_census();
 if owner_private->>'owner_id'<>me::text
 or shared_only->>'owner_id'<>me::text
 or owner_private->>'source_space_id'<>sid::text
 or shared_only->>'source_space_id'<>sid::text
 or (owner_private->>'private_eligible_table_types')::int<>46
 or (shared_only->>'shared_only_table_types_checked')::int<>12
 then raise exception 'Archive family source attribution mismatch';end if;
 if owner_private->>'all_private_eligible_types_censused'<>'true'
 or shared_only->>'archived_partner_comments_excluded'<>'true'
 then raise exception 'Private/shared source coverage incomplete';end if;
 digest_value:=encode(extensions.digest(convert_to(
   'onespace.qa.source-coverage-report.v1|'||me::text||'|'||sid::text||
    '|private='||(owner_private->>'source_inventory_sha256')||
    '|shared-only='||(shared_only->'per_table')::text||
    '|excluded-media=4|excluded-operational=7',
    'UTF8'),'sha256'),'hex');

 return jsonb_build_object(
  'schema','onespace.qa.source-coverage-report.v1',
  'recipient_id',me,'source_space_id',sid,
  'classified_table_types',69,
  'private_eligible_table_types_censused',46,
  'shared_only_table_types_censused',12,
  'media_excluded_table_types',4,
  'operational_excluded_table_types',7,
  'table_types_accounted_for',69,
  'private_source_rows_counted',owner_private->'private_source_rows_counted',
  'recipient_visible_shared_only_rows_counted',shared_only->'recipient_visible_shared_rows',
  'source_coverage_sha256',digest_value,
  'private_inventory_sha256',owner_private->'source_inventory_sha256',
  'shared_only_per_table',shared_only->'per_table',
  'mixed_visibility_shared_rows_censused',false,
  'full_per_row_source_manifest_complete',false,
  'all_written_records_durably_packaged',false,
  'trusted_server_signature_present',false,
  'independently_verified_encrypted_archive',false,
  'restoration_tested',false,
  'safe_to_archive',false,'safe_to_separate',false,'can_restore',false,
  'warning','69 known table policies accounted for, but not all source rows: shared records in mixed-visibility tables still need enumeration. No durable 69-type encrypted backup or trusted restoration exists.'
 );
end $fn$;
revoke all on function private.qa_archive_source_coverage_report()
 from public,anon,authenticated;
grant execute on function private.qa_archive_source_coverage_report()
 to authenticated;
create or replace function public.qa_archive_source_coverage_report()
returns jsonb language sql stable security invoker set search_path='' as $fn$
 select private.qa_archive_source_coverage_report()
$fn$;
revoke all on function public.qa_archive_source_coverage_report()
 from public,anon;
grant execute on function public.qa_archive_source_coverage_report()
 to authenticated;
;

-- >>>>> 0206_qa_archived_comment_audit_separation.sql
-- QA 0206: archived experience-comment audit remains old relationship
-- reference history, never private portable content for original actor.
CREATE OR REPLACE FUNCTION private.qa_unmirrored_private_source_census()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me uuid:=auth.uid();
 sid uuid;
 cfg record;
 source_table text;
 parent_table text;
 parent_fk text;
 author_col text;
 sql_where text;
 fault_where text;
 n bigint;
 bad bigint;
 records jsonb;
 fingerprint text;
 result_rows jsonb:='[]'::jsonb;
 total bigint:=0;
 faults bigint:=0;
 expected_types text[]:=array[
  'couple_letters','item_links','place_visits','record_action_history',
  'activity_comments','activity_component_reactions','activity_component_revisions',
  'activity_components','activity_decisions','activity_revisions',
  'couple_letter_reads','note_references','occasion_budget_log',
  'occasion_plan_revisions','occasion_proposal_items','reminder_actions',
  'saved_contact_revisions','scrapbook_pages','trip_revisions'];
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'Exactly one current space required';end if;
 select sm.space_id into sid from public.space_members sm where sm.user_id=me;
 if (select count(*) from private.qa_archive_table_policy p
     where p.source_table=any(expected_types)
     and p.disposition='private_shared' and p.approved)<>19
 then raise exception 'Private source census table classification changed';end if;
 if (private.qa_archive_catalog_coverage()->>'classification_complete')<>'true'
 then raise exception 'New schema types require archive review';end if;
 for cfg in
  select * from (values
   ('activity_comments','activities','activity_id','author_id'),
   ('activity_component_reactions','activities','activity_id','user_id'),
   ('activity_component_revisions','activities','activity_id','changed_by'),
   ('activity_components','activities','activity_id','created_by'),
   ('activity_decisions','activities','activity_id','created_by'),
   ('activity_revisions','activities','activity_id','changed_by'),
   ('note_references','notes','note_id','created_by'),
   ('occasion_budget_log','occasion_plans','plan_id','actor_id'),
   ('occasion_plan_revisions','occasion_plans','plan_id','changed_by'),
   ('reminder_actions','reminders','reminder_id','actor_id'),
   ('saved_contact_revisions','saved_contacts','contact_id','changed_by'),
   ('scrapbook_pages','memories','memory_id','created_by'),
   ('trip_revisions','shared_trips','trip_id','changed_by')
  ) as kinds(child_table,parent_table,parent_fk,author_col)
 loop
  source_table:=cfg.child_table;
  sql_where:=format('from public.%I c join public.%I p on p.id=c.%I
      where p.space_id=$1 and p.created_by=$2 and p.visibility=''private''',
      source_table,cfg.parent_table,cfg.parent_fk);
  fault_where:=format('c.%I is distinct from $2',cfg.author_col);
  if source_table in ('occasion_budget_log','occasion_plan_revisions') then
    -- Trigger-inserted audit rows without actor are legitimate.
    fault_where:=format('c.%I is not null and c.%I<>$2',
       cfg.author_col,cfg.author_col);
  end if;
  if source_table='scrapbook_pages' then
     fault_where:=fault_where||
       ' or (c.updated_by is not null and c.updated_by<>$2)';
  elsif source_table='reminder_actions' then
     fault_where:=fault_where||' or c.recipient_id<>$2';
  elsif source_table='note_references' then
     fault_where:=fault_where||
       ' or private.qa_portable_target_scope(c.target_kind,c.target_id,p.space_id,$2)=''blocked''';
  end if;
  execute 'select count(*), count(*) filter(where ('||fault_where||')),
       coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(c))
           order by to_jsonb(c)::text),''[]''::jsonb) '||sql_where
  into n,bad,records using sid,me;
  if n>500 then raise exception 'Private census exceeds 500 rows in %',source_table;end if;
  if bad>0 then
    raise exception 'Unmirrored private child scope mismatch: %',source_table;
  end if;
  if octet_length(convert_to(records::text,'UTF8'))>2097152 then
    raise exception 'Private census payload exceeds 2 MiB: %',source_table;end if;
  total:=total+n;
  fingerprint:=encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex');
  result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
     'source_table',source_table,'private_rows',n,
     'source_sha256',fingerprint));
 end loop;
 -- Archived/private Love Letters remain author-only; opened sent letters
 -- are shared and MUST NOT be counted as private copies for the recipient.
 select count(*),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(l))
     order by l.id),'[]'::jsonb)
 into n,records from public.couple_letters l
 where l.space_id=sid and l.author_id=me
   and (l.status<>'sent' or (l.open_on is not null and l.open_on>current_date));
 if n>500 then raise exception 'Private Love Letters exceed census limit';end if;
 total:=total+n;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','couple_letters','private_rows',n,
    'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- A draft/future-open letter MUST NOT have any read receipts. A leaked
 -- read row is a privacy breach, not an exportable historical completion.
 select count(*) into bad from public.couple_letter_reads read
 join public.couple_letters letter on letter.id=read.letter_id
 where letter.space_id=sid and letter.author_id=me
   and (letter.status<>'sent' or
      (letter.open_on is not null and letter.open_on>current_date));
 if bad>0 then raise exception 'Private Love Letter has unauthorized read receipts';end if;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','couple_letter_reads','private_rows',0,
    'source_sha256',encode(extensions.digest(
     convert_to('[]','UTF8'),'sha256'),'hex')));

 -- Place visits carry their own space_id, but must still point to the
 -- original owner's private place with the same exact space.
 select count(*),
   count(*) filter(where v.created_by<>me or v.space_id<>sid),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(v))-'memory_id'
     order by v.id),'[]'::jsonb)
 into n,bad,records from public.place_visits v
 join public.places p on p.id=v.place_id
 where p.space_id=sid and p.created_by=me and p.visibility='private';
 if bad>0 then raise exception 'Private place visit author or space mismatch';end if;
 if n>500 then raise exception 'Private place visits exceed census limit';end if;
 total:=total+n;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','place_visits','private_rows',n,
    'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- A polymorphic link with any private endpoint is a private reference.
 -- Every owner-authored link must validate both endpoints. Unknown links
 -- must block readiness rather than silently disappearing from totals.
 select count(*) into bad from public.item_links l where l.space_id=sid
  and l.created_by=me and (
     private.qa_portable_target_scope(l.from_kind,l.from_id,sid,me)='blocked'
     or private.qa_portable_target_scope(l.to_kind,l.to_id,sid,me)='blocked');
 if bad>0 then raise exception 'Polymorphic private link has missing/hidden target';end if;
 select count(*),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(l))
      order by l.id),'[]'::jsonb)
 into n,records from public.item_links l where l.space_id=sid
  and l.created_by=me and
  (private.qa_portable_target_scope(l.from_kind,l.from_id,sid,me)='private'
   or private.qa_portable_target_scope(l.to_kind,l.to_id,sid,me)='private');
 if n>500 then raise exception 'Private item links exceed census limit';end if;
 total:=total+n;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','item_links','private_rows',n,
    'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- Audit actions resolve against their current original records and are
 -- never replayable. Include private-owned history, fail if its actor is
 -- another person, and reject orphan history authored by this owner.
 select count(*) into bad from public.record_action_history h
 where h.space_id=sid and h.actor_id=me and
  private.qa_action_history_record_scope(
    h.record_kind,h.record_id,sid,me)='blocked'
  and not (
    h.record_kind='experience_comment'
    and exists(
      select 1 from public.shared_experience_comments cm
      join public.shared_experiences experience on experience.id=cm.experience_id
      where cm.id=h.record_id and experience.space_id=sid
        and exists(select 1 from public.space_members sm
          where sm.space_id=sid and sm.user_id=cm.created_by)
        and exists(select 1 from public.space_members sm
          where sm.space_id=sid and sm.user_id=experience.created_by)
    )
  );
 if bad>0 then raise exception 'Private action history has orphan source';end if;
 select count(*),
    count(*) filter(where h.actor_id is not null and h.actor_id<>me),
    coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(h))
       order by h.id),'[]'::jsonb)
 into n,bad,records from public.record_action_history h
 where h.space_id=sid and h.record_kind<>'experience_comment'
   and private.qa_action_history_record_scope(
   h.record_kind,h.record_id,sid,me)='private';
 if bad>0 then raise exception 'Private action history actor mismatch';end if;
 if n>500 then raise exception 'Private action history exceeds census limit';end if;
 total:=total+n;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','record_action_history','private_rows',n,
    'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- Occasion proposal item links must resolve via the *same* original
 -- plan, not just through both existing parent rows.
 select count(*),
   count(*) filter(where proposal.created_by<>me
     or item.plan_id<>plan.id or item.created_by<>me),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(link))
     order by link.proposal_id,link.item_id),'[]'::jsonb)
 into n,bad,records
 from public.occasion_proposal_items link
 join public.occasion_proposals proposal on proposal.id=link.proposal_id
 join public.occasion_plans plan on plan.id=proposal.plan_id
 join public.occasion_budget_items item on item.id=link.item_id
 where plan.space_id=sid and plan.created_by=me and plan.visibility='private';
 if bad>0 then raise exception 'Private proposal link points outside owner plan';end if;
 if n>500 then raise exception 'Private proposal links exceed census limit';end if;
 total:=total+n;
 result_rows:=result_rows||jsonb_build_array(jsonb_build_object(
    'source_table','occasion_proposal_items','private_rows',n,
    'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));

 if jsonb_array_length(result_rows)<>19 then
   raise exception 'Unmirrored private table enumeration incomplete';end if;
 if total>5000 then raise exception 'Private source census exceeds 5000 records';end if;
 return jsonb_build_object(
   'schema','onespace.qa.unmirrored-private-source-census.v1',
   'owner_id',me,'source_space_id',sid,
   'unmirrored_root_types',4,'unmirrored_child_types',15,
   'table_families_checked',jsonb_array_length(result_rows),
   'private_source_rows_checked',total,
   'per_table',result_rows,
   'source_of_truth_counted',true,
   'snapshots_persisted',false,'full_source_manifest_complete',false,
   'source_data_encrypted',false,'archive_issued',false,
   'can_restore',false,'safe_to_archive',false,'safe_to_separate',false,
   'warning','Current owner-private source hashes for 19 previously unmirrored types only. No original source content or portable archive is issued.');
end $function$
;
;

-- >>>>> 0207_qa_mixed_visibility_shared_source_census.sql
-- QA 0207: recipient-scoped source census of SHARED rows in the 42
-- private/shared table families. Counts/hashes only, no archival bytes.
create or replace function private.qa_mixed_shared_source_census()
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
 me uuid:=auth.uid(); sid uuid;
 cfg record;
 tab text; join_sql text; guard_sql text; sanitized_sql text;
 n bigint; bad bigint; total bigint:=0;
 records jsonb;
 results jsonb:='[]'::jsonb;
 standard_roots text[]:=array[
 'activities','daily_checkins','goals','items_to_sort','memories',
 'notes','occasion_plans','places','reminders','saved_contacts',
 'shared_trips','space_counters','space_events','tasks'];
 pending_tables text[]:=array[
 'couple_letters','item_links','place_visits','record_action_history'];
 processed int:=0;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Exactly one active relationship required';end if;
 select space_id into sid from public.space_members where user_id=me;
 if (private.qa_archive_catalog_coverage()->>'classification_complete')<>'true'
 or (select count(*) from private.qa_archive_table_policy
    where approved and disposition='private_shared')<>42
 then raise exception 'Mixed-visibility shared source scope needs review';end if;

 foreach tab in array standard_roots loop
  execute format(
    'select count(*),count(*) filter(where not exists(
      select 1 from public.space_members sm where sm.space_id=$1
        and sm.user_id=r.created_by)),
      coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(r))
        order by r.id),''[]''::jsonb)
       from public.%I r where r.space_id=$1 and r.visibility=''shared''',
    tab)
  into n,bad,records using sid;
  if bad>0 then raise exception 'Shared root original-owner mismatch: %',tab;end if;
  if n>500 or octet_length(convert_to(records::text,'UTF8'))>2097152
  then raise exception 'Shared root census exceeds limit: %',tab;end if;
  total:=total+n; processed:=processed+1;
  results:=results||jsonb_build_array(jsonb_build_object(
   'source_table',tab,'visible_shared_rows',n,
   'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));
 end loop;

 -- Letters become shared only once genuinely sent and eligible for opening.
 select count(*),count(*) filter(where not exists(select 1 from public.space_members sm
     where sm.space_id=sid and sm.user_id=l.author_id)),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(l))-'reply_to'
     order by l.id),'[]'::jsonb)
 into n,bad,records from public.couple_letters l
 where l.space_id=sid and l.status='sent'
   and (l.open_on is null or l.open_on<=current_date);
 if bad>0 then raise exception 'Shared sent letter original author mismatch';end if;
 if n>500 then raise exception 'Opened letters exceed census limit';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
   'source_table','couple_letters','visible_shared_rows',n,
   'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- Place visits have their own space_id but inherit visibility from place.
 select count(*),count(*) filter(where
    v.space_id<>sid
    or not exists(select 1 from public.space_members sm
      where sm.space_id=sid and sm.user_id=p.created_by)
    or not exists(select 1 from public.space_members sm
      where sm.space_id=sid and sm.user_id=v.created_by)),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(v))-'memory_id'
     order by v.id),'[]'::jsonb)
 into n,bad,records from public.place_visits v
 join public.places p on p.id=v.place_id
 where p.space_id=sid and p.visibility='shared';
 if bad>0 then raise exception 'Shared place visits have foreign creator or space';end if;
 if n>500 then raise exception 'Shared place visits exceed census limit';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
  'source_table','place_visits','visible_shared_rows',n,
  'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- A polymorphic link is shared ONLY when both endpoints are independently
 -- pair-shared, no matter which partner authored it. Private-linked records
 -- are counted in their owner's separate private source census.
 select count(*),count(*) filter(where
     not exists(select 1 from public.space_members sm
       where sm.space_id=sid and sm.user_id=l.created_by)),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(l))
      order by l.id),'[]'::jsonb)
 into n,bad,records from public.item_links l where l.space_id=sid
 and private.qa_portable_target_scope(l.from_kind,l.from_id,sid,me)='shared'
 and private.qa_portable_target_scope(l.to_kind,l.to_id,sid,me)='shared';
 if bad>0 then raise exception 'Shared item link author not original partner';end if;
 if n>500 then raise exception 'Shared item links exceed census limit';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
  'source_table','item_links','visible_shared_rows',n,
  'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- Old shared audit events are reference history. A private archived
 -- experience comment is author-readable only, NOT portable private data.
 select count(*),count(*) filter(where h.actor_id is not null
     and not exists(select 1 from public.space_members sm
       where sm.space_id=sid and sm.user_id=h.actor_id)),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(h))
       order by h.id),'[]'::jsonb)
 into n,bad,records from public.record_action_history h
 where h.space_id=sid and (
  private.qa_action_history_record_scope(
    h.record_kind,h.record_id,sid,me)='shared'
  or (h.record_kind='experience_comment' and
    private.qa_action_history_record_scope(
       h.record_kind,h.record_id,sid,me)='private'));
 if bad>0 then raise exception 'Shared action audit actor outside original pair';end if;
 if n>500 then raise exception 'Shared action history exceeds census limit';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
  'source_table','record_action_history','visible_shared_rows',n,
  'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- 22 dependent families with direct private/shared parent roots.
 for cfg in select * from (values
  ('activity_comments','activities','activity_id','author_id'),
  ('activity_component_reactions','activities','activity_id','user_id'),
  ('activity_component_revisions','activities','activity_id','changed_by'),
  ('activity_components','activities','activity_id','created_by'),
  ('activity_decisions','activities','activity_id','created_by'),
  ('activity_revisions','activities','activity_id','changed_by'),
  ('note_references','notes','note_id','created_by'),
  ('occasion_budget_items','occasion_plans','plan_id','created_by'),
  ('occasion_budget_log','occasion_plans','plan_id','actor_id'),
  ('occasion_plan_revisions','occasion_plans','plan_id','changed_by'),
  ('occasion_plan_steps','occasion_plans','plan_id','created_by'),
  ('occasion_proposals','occasion_plans','plan_id','created_by'),
  ('reminder_actions','reminders','reminder_id','actor_id'),
  ('reminder_recipients','reminders','reminder_id','recipient_id'),
  ('saved_contact_revisions','saved_contacts','contact_id','changed_by'),
  ('scrapbook_pages','memories','memory_id','created_by'),
  ('task_checklist_checks','tasks','task_id','user_id'),
  ('task_checklist_items','tasks','task_id','created_by'),
  ('trip_flight_options','shared_trips','trip_id','created_by'),
  ('trip_items','shared_trips','trip_id','created_by'),
  ('trip_messages','shared_trips','trip_id','created_by'),
  ('trip_revisions','shared_trips','trip_id','changed_by')
 ) as parts(table_name,parent_table,parent_fk,author_col)
 loop
  tab:=cfg.table_name;
  join_sql:=format(' from public.%I c join public.%I p on p.id=c.%I
    where p.space_id=$1 and p.visibility=''shared''',
    tab,cfg.parent_table,cfg.parent_fk);
  guard_sql:=format('not exists(select 1 from public.space_members sm
      where sm.space_id=$1 and sm.user_id=p.created_by)
      or (c.%I is not null and not exists(
       select 1 from public.space_members sm
        where sm.space_id=$1 and sm.user_id=c.%I))',
      cfg.author_col,cfg.author_col);
  if tab='scrapbook_pages' then
    guard_sql:=guard_sql||' or (c.updated_by is not null and not exists(
     select 1 from public.space_members sm
     where sm.space_id=$1 and sm.user_id=c.updated_by))';
  elsif tab='reminder_actions' then
    guard_sql:=guard_sql||' or not exists(select 1 from public.space_members sm
       where sm.space_id=$1 and sm.user_id=c.recipient_id)';
  elsif tab='note_references' then
    guard_sql:=guard_sql||'
      or private.qa_portable_target_scope(c.target_kind,c.target_id,p.space_id,$2)<>''shared''';
  elsif tab='task_checklist_checks' then
    guard_sql:=guard_sql||' or not exists(
       select 1 from public.task_checklist_items i
       where i.id=c.item_id and i.task_id=p.id)';
  elsif tab='occasion_budget_log' then
    guard_sql:=guard_sql||' or (c.item_id is not null and not exists(
      select 1 from public.occasion_budget_items i
      where i.id=c.item_id and i.plan_id=p.id))';
  elsif tab='occasion_plan_revisions' then
    guard_sql:=guard_sql||' or (c.record_kind=''plan'' and c.record_id<>p.id)
      or (c.record_kind=''step'' and not exists(
       select 1 from public.occasion_plan_steps st
       where st.id=c.record_id and st.plan_id=p.id))';
  elsif tab='occasion_budget_items' then
    guard_sql:=guard_sql||' or (c.source_activity_id is not null
      and not exists(select 1 from public.activities a
       where a.id=c.source_activity_id and a.space_id=p.space_id
         and a.visibility=''shared''))';
  end if;
  sanitized_sql:='private.qa_structured_value(to_jsonb(c))';
  if tab='occasion_budget_items' then
    sanitized_sql:=sanitized_sql||'-''source_activity_id''-''source_component_id''';
  elsif tab='reminder_recipients' then
    sanitized_sql:=sanitized_sql||'-''next_alert_at''-''snoozed_until''-''last_notified_at''';
  elsif tab='reminder_actions' then
    sanitized_sql:=sanitized_sql||'-''next_alert_at''';
  elsif tab='note_references' then
    sanitized_sql:=sanitized_sql||'-''target_id''';
  elsif tab='scrapbook_pages' then
    sanitized_sql:=sanitized_sql||'-''photo_1_id''-''photo_2_id''-''photo_3_id''-''photo_4_id''';
  end if;
  execute 'select count(*),count(*) filter(where ('||guard_sql||')),
    coalesce(jsonb_agg('||sanitized_sql||'
      order by to_jsonb(c)::text),''[]''::jsonb)'||join_sql
    into n,bad,records using sid,me;
  if bad>0 then
    raise exception 'Mixed shared child ownership or link mismatch: %',tab;
  end if;
  if n>500 or octet_length(convert_to(records::text,'UTF8'))>2097152 then
    raise exception 'Mixed shared child source exceeds cap: %',tab;
  end if;
  total:=total+n;processed:=processed+1;
  results:=results||jsonb_build_array(jsonb_build_object(
    'source_table',tab,'visible_shared_rows',n,
    'source_sha256',encode(extensions.digest(
       convert_to(records::text,'UTF8'),'sha256'),'hex')));
 end loop;

 -- Open-eligible letters' read receipts only, not draft/future events.
 select count(*) into bad from public.couple_letter_reads read
 join public.couple_letters letter on letter.id=read.letter_id
 where letter.space_id=sid and (
   letter.status<>'sent' or
   (letter.open_on is not null and letter.open_on>current_date)
   or read.reader_id=letter.author_id
   or not exists(select 1 from public.space_members sm
     where sm.space_id=sid and sm.user_id=read.reader_id));
 if bad>0 then raise exception 'Mixed shared Love Letter read receipts inconsistent';end if;
 select count(*),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(read))
     order by read.letter_id,read.reader_id),'[]'::jsonb)
 into n,records from public.couple_letter_reads read
 join public.couple_letters letter on letter.id=read.letter_id
 where letter.space_id=sid and letter.status='sent'
   and (letter.open_on is null or letter.open_on<=current_date)
   and exists(select 1 from public.space_members sm
     where sm.space_id=sid and sm.user_id=letter.author_id);
 if n>500 then raise exception 'Letter read receipts over cap';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
  'source_table','couple_letter_reads','visible_shared_rows',n,
  'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));

 -- Proposal-item joins require the same shared plan and budget item.
 select count(*),
   count(*) filter(where item.plan_id<>p.id
     or not exists(select 1 from public.space_members sm
       where sm.space_id=sid and sm.user_id=proposal.created_by)
     or not exists(select 1 from public.space_members sm
       where sm.space_id=sid and sm.user_id=item.created_by)),
   coalesce(jsonb_agg(private.qa_structured_value(to_jsonb(link))
     order by link.proposal_id,link.item_id),'[]'::jsonb)
 into n,bad,records from public.occasion_proposal_items link
 join public.occasion_proposals proposal on proposal.id=link.proposal_id
 join public.occasion_plans p on p.id=proposal.plan_id
 join public.occasion_budget_items item on item.id=link.item_id
 where p.space_id=sid and p.visibility='shared';
 if bad>0 then raise exception 'Mixed shared occasion proposal item crosses plan or owner';end if;
 if n>500 then raise exception 'Shared proposal links over census cap';end if;
 total:=total+n;processed:=processed+1;
 results:=results||jsonb_build_array(jsonb_build_object(
   'source_table','occasion_proposal_items','visible_shared_rows',n,
   'source_sha256',encode(extensions.digest(
     convert_to(records::text,'UTF8'),'sha256'),'hex')));
 if processed<>42 or jsonb_array_length(results)<>42 then
    raise exception 'Mixed shared source coverage incomplete: %',processed;end if;
 if total>15000 then raise exception 'Mixed shared source record count over cap';end if;
 return jsonb_build_object(
   'schema','onespace.qa.mixed-visibility-shared-source-census.v1',
   'recipient_id',me,'source_space_id',sid,
   'mixed_visibility_table_types_checked',42,
   'visible_shared_rows_counted',total,
   'per_table',results,
   'source_of_truth_counted',true,
   'source_snapshots_persisted',false,
   'complete_encrypted_archive_issued',false,
   'can_restore',false,'safe_to_archive',false,'safe_to_separate',false,
   'warning','Counts/hashes cover shared records in 42 mixed-visibility families for current original pair. No archived bytes, signed source manifest or trusted restoration exist.'
 );
end $fn$;
revoke all on function private.qa_mixed_shared_source_census()
 from public,anon,authenticated;
grant execute on function private.qa_mixed_shared_source_census()
 to authenticated;
create or replace function public.qa_mixed_shared_source_census()
returns jsonb language sql stable security invoker set search_path='' as $fn$
 select private.qa_mixed_shared_source_census()
$fn$;
revoke all on function public.qa_mixed_shared_source_census()
 from public,anon;
grant execute on function public.qa_mixed_shared_source_census()
 to authenticated;
;

-- >>>>> 0208_qa_full_visibility_source_coverage_report.sql
-- QA 0208: add 42 mixed shared source families to the 69-type
-- per-recipient census; still not a restorable encrypted archive.
CREATE OR REPLACE FUNCTION private.qa_archive_source_coverage_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me uuid:=auth.uid(); sid uuid;
 owner_private jsonb; shared_only jsonb; mixed_shared jsonb;
 excluded_media int; excluded_operational int; classified int;
 digest_value text;
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members where user_id=me)<>1
 then raise exception 'Exactly one active relationship required';end if;
 select space_id into sid from public.space_members where user_id=me;
 select count(*) into classified from private.qa_archive_table_policy where approved;
 select count(*) into excluded_media
 from private.qa_archive_table_policy where approved and disposition='media_excluded';
 select count(*) into excluded_operational
 from private.qa_archive_table_policy where approved and disposition='system_excluded';
 if classified<>69 or excluded_media<>4 or excluded_operational<>7
 or (private.qa_archive_catalog_coverage()->>'classification_complete')<>'true'
 then raise exception 'Archive classification schema is out of date';end if;

 owner_private:=private.qa_private_source_inventory();
 shared_only:=private.qa_shared_only_source_census();
 mixed_shared:=private.qa_mixed_shared_source_census();
 if owner_private->>'owner_id'<>me::text
 or shared_only->>'owner_id'<>me::text
 or mixed_shared->>'recipient_id'<>me::text
 or owner_private->>'source_space_id'<>sid::text
 or shared_only->>'source_space_id'<>sid::text
 or mixed_shared->>'source_space_id'<>sid::text
 or (owner_private->>'private_eligible_table_types')::int<>46
 or (shared_only->>'shared_only_table_types_checked')::int<>12
 or (mixed_shared->>'mixed_visibility_table_types_checked')::int<>42
 then raise exception 'Archive family source attribution mismatch';end if;
 if owner_private->>'all_private_eligible_types_censused'<>'true'
 or shared_only->>'archived_partner_comments_excluded'<>'true'
 or mixed_shared->>'source_of_truth_counted'<>'true'
 then raise exception 'Private/shared source coverage incomplete';end if;
 digest_value:=encode(extensions.digest(convert_to(
   'onespace.qa.source-coverage-report.v1|'||me::text||'|'||sid::text||
    '|private='||(owner_private->>'source_inventory_sha256')||
    '|shared-only='||(shared_only->'per_table')::text||
    '|mixed-shared='||(mixed_shared->'per_table')::text||
    '|excluded-media=4|excluded-operational=7',
    'UTF8'),'sha256'),'hex');

 return jsonb_build_object(
  'schema','onespace.qa.source-coverage-report.v1',
  'recipient_id',me,'source_space_id',sid,
  'classified_table_types',69,
  'private_eligible_table_types_censused',46,
  'shared_only_table_types_censused',12,
  'media_excluded_table_types',4,
  'operational_excluded_table_types',7,
  'table_types_accounted_for',69,
  'private_source_rows_counted',owner_private->'private_source_rows_counted',
  'recipient_visible_shared_only_rows_counted',shared_only->'recipient_visible_shared_rows',
  'recipient_visible_mixed_shared_rows_counted',mixed_shared->'visible_shared_rows_counted',
  'source_coverage_sha256',digest_value,
  'private_inventory_sha256',owner_private->'source_inventory_sha256',
  'shared_only_per_table',shared_only->'per_table',
  'mixed_shared_per_table',mixed_shared->'per_table',
  'mixed_visibility_shared_rows_censused',true,
  'eligible_source_family_visibility_categories_counted',true,
  'full_per_row_source_manifest_complete',false,
  'all_written_records_durably_packaged',false,
  'trusted_server_signature_present',false,
  'independently_verified_encrypted_archive',false,
  'restoration_tested',false,
  'safe_to_archive',false,'safe_to_separate',false,'can_restore',false,
  'warning','All 69 policy families are classified; source counts and sanitized hashes cover private and shared visibility categories. This is NOT a per-row portable manifest: records outside the existing 14+9 vault mirror are not durably snapshotted or encrypted, and trusted restoration does not exist.'
 );
end $function$
;
;

-- >>>>> 0209_qa_private_vault_subset_manifest.sql
-- QA 0209: real, bounded per-record SNAPSHOT manifest for the 14-root
-- + 9-dependent private owner-vault families, with exact PostgreSQL JSONB
-- byte hashes. Not a 69-family archive or a restorable package.
create or replace function private.qa_private_vault_subset_manifest()
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare
  me uuid:=auth.uid();
  sid uuid;
  expected jsonb;
  items jsonb;
  manifest_hash text;
  record_count bigint;
  byte_count bigint;
  root_count bigint;
  child_count bigint;
  max_item_bytes bigint;
  roots text[]:=array[
   'activities','daily_checkins','goals','items_to_sort','memories',
   'notes','occasion_plans','places','reminders','saved_contacts',
   'shared_trips','space_counters','space_events','tasks'];
  children text[]:=array[
   'occasion_budget_items','occasion_plan_steps','occasion_proposals',
   'reminder_recipients','task_checklist_items','task_checklist_checks',
   'trip_flight_options','trip_items','trip_messages'];
begin
 if me is null then raise exception 'Sign in required';end if;
 if (select count(*) from public.space_members sm where sm.user_id=me)<>1
 then raise exception 'Single original relationship required';end if;
 select space_id into sid from public.space_members where user_id=me;
 expected:=private.qa_private_vault_subset_fingerprint();
 if expected->>'owner_id'<>me::text
 or expected->>'source_space_id'<>sid::text
 or expected->>'root_mirror_verified'<>'true'
 or expected->>'supported_child_mirrors_verified'<>'true'
 or (expected->>'mirrored_root_types')::int<>14
 or (expected->>'mirrored_child_types')::int<>9 then
 raise exception 'Private source manifest lineage or coverage mismatch';end if;

 with selected as (
  select 'root'::text kind,v.source_table,v.source_id,
   null::text parent_table,null::uuid parent_id,v.snapshot
  from public.personal_vault_records v
  where v.owner_id=me and v.source_space_id=sid
    and v.restorable and v.current_visibility='private'
    and v.source_table=any(roots)
  union all
  select 'child'::text,d.source_table,d.source_id,
     d.parent_table,d.parent_id,d.snapshot
  from public.personal_vault_dependents d
  join public.personal_vault_records v on v.owner_id=d.owner_id
    and v.source_table=d.parent_table and v.source_id=d.parent_id
    and v.source_space_id=d.source_space_id and v.restorable
    and v.current_visibility='private'
  where d.owner_id=me and d.source_space_id=sid
    and d.restorable and d.source_table=any(children)
 ), digested as (
  select kind,source_table,source_id,parent_table,parent_id,
   snapshot::text as snapshot_json,
   octet_length(convert_to(snapshot::text,'UTF8')) bytes,
   encode(extensions.digest(convert_to(snapshot::text,'UTF8'),'sha256'),'hex') as sha
  from selected
 )
 select count(*),coalesce(sum(bytes),0),
   count(*) filter(where kind='root'),
   count(*) filter(where kind='child'),
   coalesce(max(bytes),0),
   coalesce(jsonb_agg(jsonb_build_object(
      'kind',kind,'source_table',source_table,'source_id',source_id,
      'parent_table',parent_table,'parent_id',parent_id,
      'snapshot_json',snapshot_json,
      'snapshot_sha256',sha,'snapshot_bytes',bytes)
     order by kind,source_table,source_id::text),'[]'::jsonb),
   encode(extensions.digest(convert_to(
     'onespace.qa.private.vault-subset.v1|'||me::text||'|'||sid::text||'|'||
     coalesce(string_agg(
       kind||'|'||source_table||'|'||source_id::text||'|'||sha,
       E'\n' order by kind,source_table,source_id::text),''),
      'UTF8'),'sha256'),'hex')
 into record_count,byte_count,root_count,child_count,max_item_bytes,
      items,manifest_hash
 from digested;
 if record_count>5000 or byte_count>8388608 or max_item_bytes>524288
 then raise exception 'Source snapshot manifest exceeds bounded read limits';end if;
 if root_count<>(expected->>'root_records')::int
   or child_count<>(expected->>'child_records')::int
   or record_count<>(expected->>'snapshot_record_count')::int
   or byte_count<>(expected->>'snapshot_plaintext_bytes')::int
   or manifest_hash<>expected->>'subset_sha256'
 then raise exception 'Source snapshots changed during manifest construction';end if;

 return jsonb_build_object(
  'schema','onespace.qa.private-vault-subset-manifest.v1',
  'owner_id',me,'source_space_id',sid,
  'root_types_in_scope',14,'dependent_types_in_scope',9,
  'record_count',record_count,'root_record_count',root_count,
  'child_record_count',child_count,
  'snapshot_plaintext_bytes',byte_count,
  'subset_sha256',manifest_hash,
  'records',items,
  'media_included',false,'documents_included',false,
  'all_69_types_packaged',false,'source_manifest_scope_complete',true,
  'archive_issued',false,'server_signed',false,'is_verified_archive',false,
  'can_restore',false,'safe_to_archive',false,'safe_to_separate',false,
  'warning','These are owner-only plaintext snapshots of 23 already-mirrored families. Encrypt locally before storing/exporting; NOT a complete relationship archive or permission for deletion.'
 );
end $fn$;
revoke all on function private.qa_private_vault_subset_manifest()
 from public,anon,authenticated;
grant execute on function private.qa_private_vault_subset_manifest()
 to authenticated;

create or replace function public.qa_private_vault_subset_manifest()
returns jsonb language sql stable security invoker set search_path='' as $fn$
 select private.qa_private_vault_subset_manifest()
$fn$;
revoke all on function public.qa_private_vault_subset_manifest()
 from public,anon;
grant execute on function public.qa_private_vault_subset_manifest()
 to authenticated;
;

-- >>>>> 0210_qa_subset_private_storage_staging.sql
-- QA 0210: quarantined 24h storage staging of client-side encrypted
-- per-record vault-subset files. NO lifecycle 'ready' archive rows.
-- In private (not API-exposed) schema so the 69-table public source
-- completeness catalog stays strict and unchanged.
create table if not exists private.qa_vault_subset_staging (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references auth.users(id) on delete cascade,
 source_space_id uuid not null references public.spaces(id) on delete cascade,
 object_path text not null unique,
 state text not null default 'pending'
   check (state in ('pending','available','failed')),
 ciphertext_sha256 text
   check (ciphertext_sha256 is null or ciphertext_sha256 ~ '^[0-9a-f]{64}$'),
 byte_length integer
   check (byte_length is null or (byte_length>0 and byte_length<=20971520)),
 verified_storage_bytes boolean not null default false,
 is_verified_archive boolean not null default false
   check (is_verified_archive=false),
 can_restore boolean not null default false check (can_restore=false),
 created_at timestamptz not null default now(),
 expires_at timestamptz not null default (now()+interval '24 hours'),
 constraint qa_subset_available_requires_ciphertext check (
   state<>'available' or
   (verified_storage_bytes and ciphertext_sha256 is not null and byte_length is not null)
 ),
 constraint qa_subset_owner_storage_prefix check (
   object_path=owner_id::text||'/qa-subsets/'||id::text||'.osa'
 )
);
alter table private.qa_vault_subset_staging enable row level security;
revoke all on private.qa_vault_subset_staging from public,anon,authenticated;
create index if not exists qa_subset_staging_expiry_idx
 on private.qa_vault_subset_staging(expires_at,state);
create index if not exists qa_subset_staging_owner_idx
 on private.qa_vault_subset_staging(owner_id,expires_at);

create or replace function public.qa_subset_reserve_service(
 p_owner uuid,p_space uuid)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare assigned_id uuid:=gen_random_uuid(); object_key text; n int;
begin
 if p_owner is null or p_space is null or not exists(
   select 1 from public.space_members sm
   where sm.user_id=p_owner and sm.space_id=p_space)
   or (select count(*) from public.space_members sm
       where sm.user_id=p_owner)<>1
 then raise exception 'QA subset owner/space mismatch';end if;
 select count(*) into n from private.qa_vault_subset_staging
 where owner_id=p_owner and state in ('pending','available')
   and expires_at>now();
 if n>=3 then raise exception 'QA subset staging quota exceeded';end if;
 object_key:=p_owner::text||'/qa-subsets/'||assigned_id::text||'.osa';
 insert into private.qa_vault_subset_staging(
 id,owner_id,source_space_id,object_path)
 values(assigned_id,p_owner,p_space,object_key);
 return jsonb_build_object('staging_id',assigned_id,
    'object_path',object_key,'is_verified_archive',false,
    'can_restore',false);
end $fn$;
revoke all on function public.qa_subset_reserve_service(uuid,uuid)
 from public,anon,authenticated;
grant execute on function public.qa_subset_reserve_service(uuid,uuid)
 to service_role;

create or replace function public.qa_subset_mark_available_service(
 p_id uuid,p_sha256 text,p_byte_length integer)
returns boolean language plpgsql security definer set search_path='' as $fn$
declare affected int;
begin
 if p_id is null or p_sha256 is null
   or p_sha256 !~ '^[0-9a-f]{64}$'
   or p_byte_length is null or p_byte_length<1 or p_byte_length>20971520
 then raise exception 'QA subset invalid integrity proof';end if;
 update private.qa_vault_subset_staging
 set state='available',ciphertext_sha256=p_sha256,
     byte_length=p_byte_length,verified_storage_bytes=true
 where id=p_id and state='pending' and expires_at>now();
 get diagnostics affected=row_count;
 return affected=1;
end $fn$;
revoke all on function public.qa_subset_mark_available_service(uuid,text,integer)
 from public,anon,authenticated;
grant execute on function public.qa_subset_mark_available_service(uuid,text,integer)
 to service_role;

create or replace function public.qa_subset_lookup_service(
 p_owner uuid,p_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $fn$
declare r private.qa_vault_subset_staging%rowtype;
begin
 if p_owner is null or p_id is null then return 'null'::jsonb;end if;
 select * into r from private.qa_vault_subset_staging
 where id=p_id and owner_id=p_owner and state='available'
 and verified_storage_bytes and not is_verified_archive and not can_restore
 and expires_at>now();
 if not found then return 'null'::jsonb;end if;
 if not exists(select 1 from public.space_members sm
   where sm.user_id=p_owner and sm.space_id=r.source_space_id)
 then return 'null'::jsonb;end if;
 return jsonb_build_object('staging_id',r.id,'owner_id',r.owner_id,
    'source_space_id',r.source_space_id,'object_path',r.object_path,
    'ciphertext_sha256',r.ciphertext_sha256,'byte_length',r.byte_length,
    'is_verified_archive',false,'can_restore',false);
end $fn$;
revoke all on function public.qa_subset_lookup_service(uuid,uuid)
 from public,anon,authenticated;
grant execute on function public.qa_subset_lookup_service(uuid,uuid)
 to service_role;

create or replace function public.qa_subset_mark_failed_service(p_id uuid)
returns boolean language plpgsql security definer set search_path='' as $fn$
declare affected int;
begin
 update private.qa_vault_subset_staging set state='failed'
 where id=p_id and state='pending';
 get diagnostics affected=row_count;
 return affected=1;
end $fn$;
revoke all on function public.qa_subset_mark_failed_service(uuid)
 from public,anon,authenticated;
grant execute on function public.qa_subset_mark_failed_service(uuid)
 to service_role;

create or replace function public.qa_subset_due_purge_service()
returns jsonb language sql stable security definer set search_path='' as $fn$
 select coalesce(jsonb_agg(jsonb_build_object(
    'staging_id',d.id,'object_path',d.object_path)
    order by d.created_at),'[]'::jsonb)
 from (
   select id,object_path,created_at
   from private.qa_vault_subset_staging
   where state='failed' or expires_at<=now()
      or (state='pending' and created_at<now()-interval '10 minutes')
   order by created_at limit 200
 ) d
$fn$;
revoke all on function public.qa_subset_due_purge_service()
 from public,anon,authenticated;
grant execute on function public.qa_subset_due_purge_service()
 to service_role;

create or replace function public.qa_subset_finish_purge_service(p_id uuid)
returns boolean language plpgsql security definer set search_path='' as $fn$
declare affected int;
begin
 delete from private.qa_vault_subset_staging
 where id=p_id and (state='failed' or expires_at<=now()
    or (state='pending' and created_at<now()-interval '10 minutes'));
 get diagnostics affected=row_count;
 return affected=1;
end $fn$;
revoke all on function public.qa_subset_finish_purge_service(uuid)
 from public,anon,authenticated;
grant execute on function public.qa_subset_finish_purge_service(uuid)
 to service_role;
;

-- >>>>> 0212_qa_subset_reservation_serialization.sql
-- QA 0212: use per-owner transaction advisory lock before quota scan.
CREATE OR REPLACE FUNCTION public.qa_subset_reserve_service(p_owner uuid, p_space uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare assigned_id uuid:=gen_random_uuid(); object_key text; n int;
begin
 if p_owner is null or p_space is null or not exists(
   select 1 from public.space_members sm
   where sm.user_id=p_owner and sm.space_id=p_space)
   or (select count(*) from public.space_members sm
       where sm.user_id=p_owner)<>1
 then raise exception 'QA subset owner/space mismatch';end if;
 -- Serialize active reservations by original user; two parallel uploads
 -- must not both observe a slot and exceed the three-file quota.
 perform pg_catalog.pg_advisory_xact_lock(
   pg_catalog.hashtextextended('qa-vault-subset:'||p_owner::text,0));
 select count(*) into n from private.qa_vault_subset_staging
 where owner_id=p_owner and state in ('pending','available')
   and expires_at>now();
 if n>=3 then raise exception 'QA subset staging quota exceeded';end if;
 object_key:=p_owner::text||'/qa-subsets/'||assigned_id::text||'.osa';
 insert into private.qa_vault_subset_staging(
 id,owner_id,source_space_id,object_path)
