REVOKE ALL ON FUNCTION public.qa_ack_due_account_private_media(uuid,text,text,uuid,boolean)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_claim_due_account_private_media(integer)
 TO service_role;
GRANT EXECUTE ON FUNCTION public.qa_ack_due_account_private_media(uuid,text,text,uuid,boolean)
 TO service_role;
;

-- >>>>> 0284_qa_account_delete_final_readiness_guard.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0277_qa_account_delete_final_readiness_guard.sql (original number 0277). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY. Last read-only check before ANY eventual Auth admin.deleteUser.
-- Critically, Supabase Auth cannot delete a user who still owns Storage
-- objects. This routine removes nothing and NEVER enables finalization.
CREATE OR REPLACE FUNCTION public.qa_account_final_deletion_readiness(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE gate_on boolean; preflight jsonb;remaining_objects bigint;
 path_references bigint;unfinished_private_jobs bigint;unfinished_shared_jobs bigint;
 due boolean; fk_count bigint;member_count bigint;created_count bigint;
 legacy_count bigint;personal_exists boolean;ready boolean;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only account final readiness' USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN
  RAISE EXCEPTION 'Account user required' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 SELECT enabled INTO gate_on FROM private.qa_account_v2_gate WHERE id=1;
 -- This gate must be explicitly opened only in isolated QA rollback tests
 -- until finalization and independent device verification are complete.
 IF NOT coalesce(gate_on,false) THEN
  RAISE EXCEPTION 'Account finalization gate closed' USING ERRCODE='42501';
 END IF;
 preflight:=public.qa_account_finalizer_preflight(p_user);
 due:=coalesce((preflight->>'due')::boolean,false);
 member_count:=coalesce((preflight->>'member_spaces')::bigint,0);
 created_count:=coalesce((preflight->>'spaces_created')::bigint,0);
 legacy_count:=coalesce((preflight->>'legacy_couple_private_rows')::bigint,0);
 fk_count:=coalesce((preflight->>'unresolved_no_action_user_references')::bigint,0);
 personal_exists:=coalesce((preflight->>'private_namespace_exists')::boolean,false);

 SELECT count(*) INTO remaining_objects FROM storage.objects o
 WHERE o.owner_id=p_user::text;
 -- A service-created object with NULL/different Storage ownership must
 -- not be silently orphaned when its path still contains the deleted owner.
 SELECT count(*) INTO path_references FROM storage.objects o
 WHERE p_user::text=ANY(storage.foldername(o.name));
 SELECT count(*) INTO unfinished_private_jobs
 FROM public.qa_account_private_media_purge_queue q
 WHERE q.owner_id=p_user AND q.deleted_at IS NULL;
 SELECT count(*) INTO unfinished_shared_jobs
 FROM public.qa_shared_media_purge_queue q
 WHERE q.expected_uploader_id=p_user AND q.deleted_at IS NULL;
 ready:=due AND personal_exists AND member_count=0 AND created_count=0
  AND legacy_count=0 AND fk_count=0
  AND remaining_objects=0 AND path_references=0
  AND unfinished_private_jobs=0 AND unfinished_shared_jobs=0;
 RETURN jsonb_build_object(
  'ready_for_auth_delete',ready,'due',due,
  'private_namespace_exists',personal_exists,
  'remaining_relationship_memberships',member_count,
  'remaining_created_spaces',created_count,
  'legacy_couple_private_rows',legacy_count,
  'unresolved_auth_user_fk_references',fk_count,
  'remaining_storage_objects_owned',remaining_objects,
  'remaining_storage_folder_references',path_references,
  'unfinished_private_file_purges',unfinished_private_jobs,
  'unfinished_shared_file_purges',unfinished_shared_jobs,
  'actual_auth_deletion_not_implemented',true);
END $q$;
REVOKE ALL ON FUNCTION public.qa_account_final_deletion_readiness(uuid)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_account_final_deletion_readiness(uuid)
 TO service_role;
;

-- >>>>> 0285_qa_due_account_legacy_solo_cleanup.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0278_qa_due_account_legacy_solo_cleanup.sql (original number 0278). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY. Account DELETE *after* the 7-day grace may retire the user's
-- historical solo space, distinct from account-owned user_private_spaces.
-- Never use this function for Leave/Remove/Delete Couple. Gate remains OFF.
CREATE OR REPLACE FUNCTION public.qa_retire_due_account_legacy_solo(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE due timestamptz;retired integer;other_member_count integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only old solo space retirement' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.qa_account_v2_gate
   WHERE id=1 AND enabled) THEN
  RAISE EXCEPTION 'Account deletion gate closed' USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 SELECT r.purge_after INTO due FROM public.account_deletion_requests r
 WHERE r.user_id=p_user AND r.cancelled_at IS NULL
  AND r.completed_at IS NULL AND r.processing_at IS NULL
  AND r.purge_after<=now()
 FOR UPDATE;
 IF due IS NULL THEN
  RAISE EXCEPTION 'The full seven-day account deletion grace has not expired'
   USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_private_spaces p
    WHERE p.owner_id=p_user) THEN
  RAISE EXCEPTION 'Account-owned private namespace missing' USING ERRCODE='42501';
 END IF;
 -- Any live relationship must be completed through the separate couple
 -- erasure transaction, protecting the surviving person's private namespace.
 IF EXISTS(SELECT 1 FROM public.space_members m JOIN public.spaces s
     ON s.id=m.space_id
     WHERE m.user_id=p_user AND
       (s.personal_owner IS DISTINCT FROM p_user OR s.created_by<>p_user)) THEN
  RAISE EXCEPTION 'Close the current shared relationship first' USING ERRCODE='42501';
 END IF;
 IF EXISTS(SELECT 1 FROM public.spaces s WHERE s.created_by=p_user
     AND s.personal_owner IS DISTINCT FROM p_user) THEN
  RAISE EXCEPTION 'Creator-owned shared space requires separate couple closure'
    USING ERRCODE='42501';
 END IF;
 SELECT count(*) INTO other_member_count
 FROM public.space_members m JOIN public.spaces s ON s.id=m.space_id
 WHERE s.personal_owner=p_user AND s.created_by=p_user
   AND m.user_id<>p_user;
 IF other_member_count<>0 THEN
  RAISE EXCEPTION 'A historical solo space has another member: refuse deletion'
   USING ERRCODE='42501';
 END IF;
 -- Only account-owned legacy solo spaces, NEVER a couple.
 DELETE FROM public.spaces s
 WHERE s.personal_owner=p_user AND s.created_by=p_user
 AND NOT EXISTS(SELECT 1 FROM public.space_members m
   WHERE m.space_id=s.id AND m.user_id<>p_user);
 GET DIAGNOSTICS retired=ROW_COUNT;
 IF NOT EXISTS(SELECT 1 FROM public.user_private_spaces p WHERE p.owner_id=p_user)
 THEN RAISE EXCEPTION 'Private account namespace was unexpectedly affected'
   USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('retired_legacy_solo_spaces',retired,
  'private_namespace_preserved',true,'auth_user_deleted',false);
END $q$;
REVOKE ALL ON FUNCTION public.qa_retire_due_account_legacy_solo(uuid)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_retire_due_account_legacy_solo(uuid)
 TO service_role;
;

-- >>>>> 0286_qa_auth_account_owned_root_cascades.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0279_qa_auth_account_owned_root_cascades.sql (original number 0279). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY: account-owned roots already cascade from user_private_spaces,
-- but their second auth.users author FK was NO ACTION. PostgreSQL blocks the
-- Auth deletion before it can cascade the private namespace (verified with a
-- synthetic QA Auth user). Make ONLY these account-owned root author/actor FKs
-- cascade as well. Other shared FK dependencies remain guarded by preflight.
-- Schema-only, no Auth users or content deleted.
DO $m$
DECLARE r record;count_changed integer:=0;
BEGIN
 FOR r IN
  SELECT c.conrelid::regclass::text tab,c.conname,
    a.attname col,pg_get_constraintdef(c.oid) definition
  FROM pg_constraint c JOIN pg_class cl ON cl.oid=c.conrelid
   JOIN pg_namespace ns ON ns.oid=cl.relnamespace
   JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=c.conkey[1]
  WHERE c.contype='f' AND c.confrelid='auth.users'::regclass
   AND c.confdeltype IN('a','r') AND cardinality(c.conkey)=1
   AND ns.nspname='public'
   AND EXISTS(SELECT 1 FROM pg_constraint private_fk
     WHERE private_fk.conrelid=c.conrelid
       AND private_fk.confrelid='public.user_private_spaces'::regclass
       AND private_fk.confdeltype='c')
  ORDER BY c.conrelid::regclass::text,a.attname
 LOOP
  IF r.definition NOT LIKE
    format('FOREIGN KEY (%I) REFERENCES auth.users(id)%%',r.col) THEN
   RAISE EXCEPTION 'Unexpected auth FK shape % on %',r.definition,r.tab;
  END IF;
  EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',r.tab,r.conname);
  EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES auth.users(id) ON DELETE CASCADE NOT VALID',
    r.tab,r.conname,r.col);
  count_changed:=count_changed+1;
 END LOOP;
 IF count_changed<>18 THEN
  RAISE EXCEPTION 'Private root auth FK inventory drift: expected 18 changed %',
   count_changed;
 END IF;
END $m$;
;

-- >>>>> 0287_qa_account_audit_history_actor_cascade.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0280_qa_account_audit_history_actor_cascade.sql (original number 0280). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA: account deletion must remove personally identifying action history.
-- SET NULL actor_id conflicts with the concurrent private-space CASCADE
-- during Auth deletion; delete that user's audit rows instead. Relationship
-- termination still removes shared-scope audit via space_id CASCADE.
ALTER TABLE public.record_action_history
 DROP CONSTRAINT IF EXISTS record_action_history_actor_id_fkey;
ALTER TABLE public.record_action_history
 ADD CONSTRAINT record_action_history_actor_id_fkey
 FOREIGN KEY(actor_id) REFERENCES auth.users(id)
 ON DELETE CASCADE NOT VALID;
;

-- >>>>> 0288_qa_pending_account_cannot_start_new_pair.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0281_qa_pending_account_cannot_start_new_pair.sql (original number 0281). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY. Once an account has requested deletion, do not let it create
-- a new relationship or accept an invitation while pending. Cancellation
-- restores pairing eligibility. Protects finalizer against late re-pair.
-- Backend deletion remains gate-OFF and request_account_deletion is revoked.
CREATE OR REPLACE FUNCTION private.qa_account_pending_delete(p_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $q$
 SELECT p_id IS NOT NULL AND EXISTS(
  SELECT 1 FROM public.account_deletion_requests r
  WHERE r.user_id=p_id AND r.cancelled_at IS NULL AND r.completed_at IS NULL
 );
$q$;
REVOKE ALL ON FUNCTION private.qa_account_pending_delete(uuid)
 FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION private.qa_pending_account_pairing_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE owner_id uuid;pair_id uuid;candidate uuid;
BEGIN
 IF tg_table_name='spaces' THEN
  IF private.qa_account_pending_delete(new.created_by) THEN
   RAISE EXCEPTION 'Account pending deletion cannot create a new space'
    USING ERRCODE='42501';END IF;
  RETURN new;
 END IF;
 pair_id:=new.space_id;
 IF tg_table_name='space_members' THEN
  candidate:=new.user_id;
 ELSIF tg_table_name='space_invitations' THEN
  candidate:=new.invited_by;
  IF new.accepted_by IS NOT NULL
   AND private.qa_account_pending_delete(new.accepted_by) THEN
   RAISE EXCEPTION 'Account pending deletion cannot accept a partnership'
    USING ERRCODE='42501';END IF;
 END IF;
 IF private.qa_account_pending_delete(candidate) THEN
  RAISE EXCEPTION 'Account pending deletion cannot start or join a partnership'
   USING ERRCODE='42501';END IF;
 SELECT created_by INTO owner_id FROM public.spaces WHERE id=pair_id;
 IF private.qa_account_pending_delete(owner_id)
  OR EXISTS(SELECT 1 FROM public.space_members m
    WHERE m.space_id=pair_id AND private.qa_account_pending_delete(m.user_id))
 THEN
  RAISE EXCEPTION 'The space has a member pending account deletion'
   USING ERRCODE='42501';
 END IF;
 RETURN new;
END $q$;
REVOKE ALL ON FUNCTION private.qa_pending_account_pairing_guard()
 FROM PUBLIC,anon,authenticated;

DROP TRIGGER IF EXISTS qa_pending_account_blocks_new_space ON public.spaces;
CREATE TRIGGER qa_pending_account_blocks_new_space
 BEFORE INSERT OR UPDATE OF created_by ON public.spaces
 FOR EACH ROW EXECUTE FUNCTION private.qa_pending_account_pairing_guard();

DROP TRIGGER IF EXISTS qa_pending_account_blocks_new_members ON public.space_members;
CREATE TRIGGER qa_pending_account_blocks_new_members
 BEFORE INSERT OR UPDATE OF user_id,space_id ON public.space_members
 FOR EACH ROW EXECUTE FUNCTION private.qa_pending_account_pairing_guard();

DROP TRIGGER IF EXISTS qa_pending_account_blocks_new_invites ON public.space_invitations;
CREATE TRIGGER qa_pending_account_blocks_new_invites
 BEFORE INSERT OR UPDATE OF space_id,invited_by,accepted_by ON public.space_invitations
 FOR EACH ROW EXECUTE FUNCTION private.qa_pending_account_pairing_guard();
;

-- >>>>> 0289_qa_pending_pair_and_delete_request_serialization.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0282_qa_pending_pair_and_delete_request_serialization.sql (original number 0282). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY: serialize pair creation, invitation acceptance and a user's
-- account-delete request on the same advisory lock (per user, namespace 5).
-- Prevents a newly accepted pairing racing a just-submitted delete request.
CREATE OR REPLACE FUNCTION private.qa_pending_account_pairing_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE ids uuid[]:='{}'::uuid[];uid uuid;creator uuid; old_user uuid;
BEGIN
 IF tg_table_name='spaces' THEN
  ids:=array_append(ids,new.created_by);
  IF tg_op='UPDATE' THEN ids:=array_append(ids,old.created_by);END IF;
 ELSE
  SELECT s.created_by INTO creator FROM public.spaces s WHERE s.id=new.space_id;
  ids:=array_append(ids,creator);
  IF tg_table_name='space_members' THEN
   ids:=array_append(ids,new.user_id);
   IF tg_op='UPDATE' THEN ids:=array_append(ids,old.user_id);END IF;
  ELSE
   ids:=array_append(ids,new.invited_by);
   ids:=array_append(ids,new.accepted_by);
   IF tg_op='UPDATE' THEN
    ids:=array_append(ids,old.invited_by);
    ids:=array_append(ids,old.accepted_by);
   END IF;
  END IF;
  SELECT array_cat(ids,coalesce(array_agg(m.user_id),'{}'::uuid[]))
    INTO ids FROM public.space_members m WHERE m.space_id=new.space_id;
 END IF;
 -- Deterministic ordering prevents two accounts simultaneously pairing each
 -- other from deadlocking. Delete/cancel RPCs lock their own user ID.
 FOR uid IN SELECT DISTINCT x FROM unnest(ids) x
  WHERE x IS NOT NULL ORDER BY x LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,5));
 END LOOP;
 FOR uid IN SELECT DISTINCT x FROM unnest(ids) x
  WHERE x IS NOT NULL LOOP
  IF private.qa_account_pending_delete(uid) THEN
   RAISE EXCEPTION 'Cannot pair or invite while account deletion is pending'
     USING ERRCODE='42501';
  END IF;
 END LOOP;
 RETURN new;
END $q$;
REVOKE ALL ON FUNCTION private.qa_pending_account_pairing_guard()
 FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public.request_account_deletion()
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE me uuid:=auth.uid();due timestamptz;
BEGIN
 IF me IS NULL THEN
  RAISE EXCEPTION 'Sign in to request deletion' USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(me::text,5));
 INSERT INTO public.account_deletion_requests(
  user_id,requested_at,purge_after,cancelled_at,completed_at,last_error,processing_at)
 VALUES(me,now(),now()+interval '7 days',NULL,NULL,NULL,NULL)
 ON CONFLICT(user_id) DO UPDATE SET
  requested_at=CASE WHEN account_deletion_requests.cancelled_at IS NULL
     AND account_deletion_requests.completed_at IS NULL
   THEN account_deletion_requests.requested_at ELSE now() END,
  purge_after=CASE WHEN account_deletion_requests.cancelled_at IS NULL
     AND account_deletion_requests.completed_at IS NULL
   THEN account_deletion_requests.purge_after ELSE now()+interval '7 days' END,
  cancelled_at=NULL,last_error=NULL
 WHERE account_deletion_requests.processing_at IS NULL
   AND account_deletion_requests.completed_at IS NULL
 RETURNING purge_after INTO due;
 IF due IS NULL THEN
  RAISE EXCEPTION 'Account deletion cannot be re-requested once finalization begins'
   USING ERRCODE='42501';
 END IF;
 RETURN due;
END $q$;

CREATE OR REPLACE FUNCTION public.cancel_account_deletion()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE me uuid:=auth.uid();stopped integer;
BEGIN
 IF me IS NULL THEN
  RAISE EXCEPTION 'Sign in to cancel deletion' USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(me::text,5));
 UPDATE public.account_deletion_requests
  SET cancelled_at=now(),last_error=NULL
 WHERE user_id=me AND cancelled_at IS NULL AND completed_at IS NULL
   AND processing_at IS NULL AND purge_after>now();
 GET DIAGNOSTICS stopped=ROW_COUNT;
 IF stopped=0 AND EXISTS(SELECT 1 FROM public.account_deletion_requests
  WHERE user_id=me AND cancelled_at IS NULL AND completed_at IS NULL) THEN
  RAISE EXCEPTION 'The seven-day cancellation window has ended or processing started'
   USING ERRCODE='42501';
 END IF;
END $q$;
-- No new client rights are granted. The account-delete request stays revoked.
;

-- >>>>> 0290_qa_completed_account_media_audit_scrub.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0283_qa_completed_account_media_audit_scrub.sql (original number 0283). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY. Do not retain account identifiers in completed file-purge
-- queues after physically erasing every owned file and verifying eligibility.
-- Never clear an uncompleted job or allow ordinary app users to invoke.
GRANT DELETE ON public.qa_account_private_media_purge_queue TO service_role;
GRANT DELETE ON public.qa_shared_media_purge_queue TO service_role;
CREATE OR REPLACE FUNCTION public.qa_scrub_completed_account_media_jobs(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE verified jsonb;own_count integer;shared_count integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only completed account media audit cleanup'
   USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 verified:=public.qa_account_final_deletion_readiness(p_user);
 IF verified->>'ready_for_auth_delete'<>'true' THEN
  RAISE EXCEPTION 'Cannot clear any audit while account deletion prerequisites remain'
   USING ERRCODE='42501';
 END IF;
 DELETE FROM public.qa_account_private_media_purge_queue q
 WHERE q.owner_id=p_user AND q.deleted_at IS NOT NULL;
 GET DIAGNOSTICS own_count=ROW_COUNT;
 DELETE FROM public.qa_shared_media_purge_queue q
 WHERE q.expected_uploader_id=p_user AND q.deleted_at IS NOT NULL;
 GET DIAGNOSTICS shared_count=ROW_COUNT;
 RETURN jsonb_build_object('completed_private_jobs_scrubbed',own_count,
  'completed_shared_jobs_scrubbed',shared_count,
  'account_user_deleted',false);
END $q$;
REVOKE ALL ON FUNCTION public.qa_scrub_completed_account_media_jobs(uuid)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_scrub_completed_account_media_jobs(uuid)
 TO service_role;
;

-- >>>>> 0291_qa_relationship_end_rejects_personal_solo_spaces.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0284_qa_relationship_end_rejects_personal_solo_spaces.sql (original number 0284). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA: never allow Remove/Leave/Delete Couple to delete legacy personal solo space.
-- This guards old account-created space rows while account deletion separately
-- cleans only truly due owned solo spaces. Does NOT activate lifecycle controls.
CREATE OR REPLACE FUNCTION private.qa_close_relationship_v2(
 p_space uuid,p_action text,p_confirmation text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE me uuid:=auth.uid();
 owner_id uuid;legacy_personal_owner uuid;participants uuid[];member_count int;
 rec record;before_count bigint;after_count bigint;
 before_counts jsonb:='{}'::jsonb;file_count int;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM private.qa_relationship_v2_gate g
   WHERE g.id=1 AND g.enabled) THEN
  RAISE EXCEPTION 'OneSpace relationship deletion is not enabled'
   USING ERRCODE='42501';
 END IF;
 IF me IS NULL OR p_space IS NULL OR
  p_confirmation IS DISTINCT FROM 'DELETE SHARED CONTENT' OR
  p_action NOT IN('remove_partner','leave_space','delete_space') THEN
  RAISE EXCEPTION 'Signed-in account, existing space and explicit irreversible confirmation are required'
    USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_space::text,0));
 SELECT s.created_by,s.personal_owner INTO owner_id,legacy_personal_owner FROM public.spaces s
   WHERE s.id=p_space FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Shared relationship no longer exists'
    USING ERRCODE='42501';END IF;
 IF legacy_personal_owner IS NOT NULL THEN
  RAISE EXCEPTION 'Personal solo spaces cannot be removed by couple lifecycle operations'
   USING ERRCODE='42501';
 END IF;
 SELECT count(*),array_agg(user_id ORDER BY user_id) INTO member_count,participants
 FROM public.space_members WHERE space_id=p_space;
 IF member_count NOT BETWEEN 1 AND 2 OR me<>ALL(participants) THEN
   RAISE EXCEPTION 'Account does not belong to this current space'
    USING ERRCODE='42501';
 END IF;
 IF p_action='remove_partner' AND (me<>owner_id OR member_count<>2) THEN
   RAISE EXCEPTION 'Only the paired owner can remove their current partner'
     USING ERRCODE='42501';END IF;
 IF p_action='leave_space' AND (me=owner_id OR member_count<>2) THEN
   RAISE EXCEPTION 'Only the invited partner can leave this paired space'
     USING ERRCODE='42501';END IF;
 IF p_action='delete_space' AND me<>owner_id THEN
   RAISE EXCEPTION 'Only the owner can delete their shared space'
     USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM public.user_private_spaces ps
   WHERE ps.owner_id=ANY(participants))<>member_count THEN
   RAISE EXCEPTION 'Cannot separate: an account-owned personal namespace is missing'
    USING ERRCODE='42501';END IF;
 -- Preserve all private families, including those without an active UI.
 FOR rec IN
  SELECT c.table_name FROM information_schema.columns c
  WHERE c.table_schema='public'
  GROUP BY c.table_name HAVING bool_or(c.column_name='private_space_id')
 LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE private_space_id=ANY($1)',
    rec.table_name) INTO before_count USING participants;
  before_counts:=before_counts||jsonb_build_object(rec.table_name,before_count);
 END LOOP;

 -- Capture authorized couple media pointers before parent cascading deletes.
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-note-images',n.object_path FROM public.note_images n
 JOIN public.notes parent ON parent.id=n.note_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND n.storage_bucket_id='onespace-note-images'
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-memory-photos',f.object_path FROM public.memory_photos f
 JOIN public.memories parent ON parent.id=f.memory_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND f.storage_bucket_id='onespace-memory-photos'
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-trip-documents',d.object_path FROM public.trip_attachments d
 JOIN public.shared_trips parent ON parent.id=d.trip_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND d.storage_bucket_id='onespace-trip-documents'
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,o.bucket_id,o.name FROM storage.objects o
 WHERE o.bucket_id IN('onespace-activity-media','onespace-activity-voice')
  AND EXISTS(SELECT 1 FROM public.activities a
   WHERE a.id::text=split_part(o.name,'/',1)
    AND a.space_id=p_space AND a.private_space_id IS NULL)
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-share-in',i.file_path FROM public.items_to_sort i
 WHERE i.space_id=p_space AND i.private_space_id IS NULL
   AND i.file_path IS NOT NULL
 ON CONFLICT DO NOTHING;
 SELECT count(*) INTO file_count
  FROM public.qa_shared_media_purge_queue
  WHERE space_id=p_space AND deleted_at IS NULL;
 DELETE FROM public.spaces s WHERE s.id=p_space;
 IF NOT FOUND THEN RAISE EXCEPTION 'Relationship deletion failed; rolled back'
  USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.space_members WHERE space_id=p_space) THEN
  RAISE EXCEPTION 'Former pair membership remains; rolled back'
   USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM public.user_private_spaces ps
   WHERE ps.owner_id=ANY(participants))<>member_count THEN
  RAISE EXCEPTION 'Personal namespace was lost; entire deletion rolled back'
   USING ERRCODE='42501';END IF;
 FOR rec IN
  SELECT c.table_name FROM information_schema.columns c
  WHERE c.table_schema='public'
  GROUP BY c.table_name HAVING bool_or(c.column_name='private_space_id')
 LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE private_space_id=ANY($1)',
   rec.table_name) INTO after_count USING participants;
  IF after_count IS DISTINCT FROM (before_counts->>rec.table_name)::bigint THEN
   RAISE EXCEPTION 'Personal content count changed in %, entire deletion rolled back',
    rec.table_name USING ERRCODE='42501';
  END IF;
 END LOOP;
 RETURN jsonb_build_object('status','shared_db_removed_storage_purge_pending',
  'space_id',p_space,'members_unpaired',member_count,
  'media_files_queued',file_count,'action',p_action);
END $q$;
REVOKE ALL ON FUNCTION private.qa_close_relationship_v2(uuid,text,text)
 FROM PUBLIC,anon,authenticated,service_role;
-- No public RPC wrapper, no app button, no migration enabling the gate.
;

-- >>>>> 0292_qa_due_account_storage_upload_fence.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0285_qa_due_account_storage_upload_fence.sql (original number 0285). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA: once a 7-day account-deletion request becomes irrevocably due,
-- block ALL new authenticated Storage uploads/replacements by that account.
-- This closes the race between worker file-inventory, final readiness and
-- Supabase Auth Admin deleteUser. Does not block legitimate app usage while
-- the seven-day grace is still open; cancellation restores access.
CREATE OR REPLACE FUNCTION private.qa_account_storage_upload_allowed(p_uid uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $q$
 SELECT p_uid IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM public.account_deletion_requests r
  WHERE r.user_id=p_uid AND r.cancelled_at IS NULL AND r.completed_at IS NULL
   AND r.purge_after<=now()
 );
$q$;
REVOKE ALL ON FUNCTION private.qa_account_storage_upload_allowed(uuid)
 FROM PUBLIC,anon,authenticated;

DROP POLICY IF EXISTS "QA due account cannot upload any Storage files" ON storage.objects;
CREATE POLICY "QA due account cannot upload any Storage files"
 ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated
 WITH CHECK(private.qa_account_storage_upload_allowed((SELECT auth.uid())));

DROP POLICY IF EXISTS "QA due account cannot replace Storage files" ON storage.objects;
CREATE POLICY "QA due account cannot replace Storage files"
 ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated
 USING(private.qa_account_storage_upload_allowed((SELECT auth.uid())))
 WITH CHECK(private.qa_account_storage_upload_allowed((SELECT auth.uid())));
;

-- >>>>> 0293_qa_storage_fence_authenticated_policy_helper.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0286_qa_storage_fence_authenticated_policy_helper.sql (original number 0286). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA: Storage RLS evaluates this helper as an authenticated session.
-- It must have EXECUTE privileges, but cannot be used to probe or change
-- another account's deletion status. The private schema is not exposed to
-- the public PostgREST API.
CREATE OR REPLACE FUNCTION private.qa_account_storage_upload_allowed(p_uid uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $q$
 SELECT p_uid IS NOT NULL
  AND p_uid=auth.uid()
  AND NOT EXISTS(
   SELECT 1 FROM public.account_deletion_requests r
   WHERE r.user_id=p_uid AND r.cancelled_at IS NULL AND r.completed_at IS NULL
    AND r.purge_after<=now()
  );
$q$;
REVOKE ALL ON FUNCTION private.qa_account_storage_upload_allowed(uuid)
 FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.qa_account_storage_upload_allowed(uuid)
 TO authenticated;
;

-- >>>>> 0294_qa_orphaned_shared_media_upload_cleanup.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0287_qa_orphaned_shared_media_upload_cleanup.sql (original number 0287). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA: queued physical media must include orphan Storage objects from
-- uploads interrupted before metadata save. Not enabled for app users.
CREATE OR REPLACE FUNCTION private.qa_purge_queue_source_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE uploader uuid;storage_owner text;filename_owner text;
BEGIN
 IF tg_op='UPDATE' THEN
  IF new.space_id IS DISTINCT FROM old.space_id
    OR new.bucket_id IS DISTINCT FROM old.bucket_id
    OR new.object_path IS DISTINCT FROM old.object_path
    OR new.expected_uploader_id IS DISTINCT FROM old.expected_uploader_id THEN
   RAISE EXCEPTION 'Cannot change queued media identity or provenance'
    USING ERRCODE='42501';
  END IF;
  RETURN new;
 END IF;
 IF new.bucket_id IN('onespace-note-images','onespace-memory-photos',
   'onespace-trip-documents','onespace-activity-media','onespace-activity-voice')
  AND new.object_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|m4a|pdf)$' THEN
   RAISE EXCEPTION 'Unsupported relationship media path' USING ERRCODE='42501';
 END IF;
 IF new.bucket_id='onespace-share-in' AND
   new.object_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|heic|pdf)$' THEN
   RAISE EXCEPTION 'Unsupported shared inbox media path' USING ERRCODE='42501';
 END IF;
 IF new.bucket_id='onespace-note-images' THEN
  SELECT i.created_by INTO uploader FROM public.note_images i
   JOIN public.notes parent ON parent.id=i.note_id
   WHERE i.object_path=new.object_path AND i.storage_bucket_id=new.bucket_id
    AND parent.space_id=new.space_id AND parent.private_space_id IS NULL;
 ELSIF new.bucket_id='onespace-memory-photos' THEN
  SELECT i.created_by INTO uploader FROM public.memory_photos i
   JOIN public.memories parent ON parent.id=i.memory_id
   WHERE i.object_path=new.object_path AND i.storage_bucket_id=new.bucket_id
    AND parent.space_id=new.space_id AND parent.private_space_id IS NULL;
 ELSIF new.bucket_id='onespace-trip-documents' THEN
  SELECT i.created_by INTO uploader FROM public.trip_attachments i
   JOIN public.shared_trips parent ON parent.id=i.trip_id
   WHERE i.object_path=new.object_path AND i.storage_bucket_id=new.bucket_id
    AND parent.space_id=new.space_id AND parent.private_space_id IS NULL;
 ELSIF new.bucket_id IN('onespace-activity-media','onespace-activity-voice') THEN
  SELECT nullif(o.owner_id,'')::uuid INTO uploader FROM storage.objects o
   JOIN public.activities a ON a.id::text=split_part(o.name,'/',1)
   WHERE o.bucket_id=new.bucket_id AND o.name=new.object_path
    AND a.space_id=new.space_id AND a.private_space_id IS NULL
    AND o.owner_id ~ '^[0-9a-f-]{36}$';
 ELSIF new.bucket_id='onespace-share-in' THEN
  SELECT i.created_by INTO uploader FROM public.items_to_sort i
   WHERE i.space_id=new.space_id AND i.private_space_id IS NULL
    AND i.file_path=new.object_path AND i.created_by::text=split_part(i.file_path,'/',1);
 ELSE
  RAISE EXCEPTION 'Unknown relationship media bucket' USING ERRCODE='42501';
 END IF;
 -- Resolve interrupted Storage uploads without attachment metadata.
 -- Only a real Storage object whose owner UUID matches the original path,
 -- currently in the same pair and parent namespace, may be queued.
 IF uploader IS NULL AND new.bucket_id IN(
  'onespace-note-images','onespace-memory-photos','onespace-trip-documents') THEN
  SELECT o.owner_id::uuid INTO uploader FROM storage.objects o
  WHERE o.bucket_id=new.bucket_id AND o.name=new.object_path
    AND o.owner_id ~ '^[0-9a-f-]{36}$'
    AND o.owner_id=split_part(o.name,'/',2)
    AND (
      (o.bucket_id='onespace-note-images'
       AND EXISTS(SELECT 1 FROM public.notes parent
        WHERE parent.id::text=split_part(o.name,'/',1)
         AND parent.space_id=new.space_id AND parent.private_space_id IS NULL)
       AND NOT EXISTS(SELECT 1 FROM public.note_images i
        WHERE i.storage_bucket_id=o.bucket_id AND i.object_path=o.name))
      OR
      (o.bucket_id='onespace-memory-photos'
       AND EXISTS(SELECT 1 FROM public.memories parent
        WHERE parent.id::text=split_part(o.name,'/',1)
         AND parent.space_id=new.space_id AND parent.private_space_id IS NULL)
       AND NOT EXISTS(SELECT 1 FROM public.memory_photos i
        WHERE i.storage_bucket_id=o.bucket_id AND i.object_path=o.name))
      OR
      (o.bucket_id='onespace-trip-documents'
       AND EXISTS(SELECT 1 FROM public.shared_trips parent
        WHERE parent.id::text=split_part(o.name,'/',1)
         AND parent.space_id=new.space_id AND parent.private_space_id IS NULL)
       AND NOT EXISTS(SELECT 1 FROM public.trip_attachments i
        WHERE i.storage_bucket_id=o.bucket_id AND i.object_path=o.name))
    )
  LIMIT 1;
 END IF;
 IF uploader IS NULL OR NOT EXISTS(SELECT 1 FROM public.space_members m
   WHERE m.space_id=new.space_id AND m.user_id=uploader) THEN
  RAISE EXCEPTION 'Queued shared file author is not a current member'
   USING ERRCODE='42501';
 END IF;
 filename_owner:=CASE WHEN new.bucket_id='onespace-share-in'
  THEN split_part(new.object_path,'/',1) ELSE split_part(new.object_path,'/',2) END;
 IF filename_owner<>uploader::text THEN
  RAISE EXCEPTION 'File prefix does not belong to its recorded author'
   USING ERRCODE='42501';
 END IF;
 SELECT o.owner_id INTO storage_owner FROM storage.objects o
  WHERE o.bucket_id=new.bucket_id AND o.name=new.object_path;
 IF storage_owner IS NOT NULL AND storage_owner<>uploader::text THEN
  RAISE EXCEPTION 'File object was uploaded by another account'
   USING ERRCODE='42501';
 END IF;
 new.expected_uploader_id:=uploader;
 RETURN new;
END $q$;
CREATE OR REPLACE FUNCTION private.qa_close_relationship_v2(
 p_space uuid,p_action text,p_confirmation text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE me uuid:=auth.uid();
 owner_id uuid;legacy_personal_owner uuid;participants uuid[];member_count int;
 rec record;before_count bigint;after_count bigint;
 before_counts jsonb:='{}'::jsonb;file_count int;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM private.qa_relationship_v2_gate g
   WHERE g.id=1 AND g.enabled) THEN
  RAISE EXCEPTION 'OneSpace relationship deletion is not enabled'
   USING ERRCODE='42501';
 END IF;
 IF me IS NULL OR p_space IS NULL OR
  p_confirmation IS DISTINCT FROM 'DELETE SHARED CONTENT' OR
  p_action NOT IN('remove_partner','leave_space','delete_space') THEN
  RAISE EXCEPTION 'Signed-in account, existing space and explicit irreversible confirmation are required'
    USING ERRCODE='42501';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_space::text,0));
 SELECT s.created_by,s.personal_owner INTO owner_id,legacy_personal_owner FROM public.spaces s
   WHERE s.id=p_space FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Shared relationship no longer exists'
    USING ERRCODE='42501';END IF;
 IF legacy_personal_owner IS NOT NULL THEN
  RAISE EXCEPTION 'Personal solo spaces cannot be removed by couple lifecycle operations'
   USING ERRCODE='42501';
 END IF;
 SELECT count(*),array_agg(user_id ORDER BY user_id) INTO member_count,participants
 FROM public.space_members WHERE space_id=p_space;
 IF member_count NOT BETWEEN 1 AND 2 OR me<>ALL(participants) THEN
   RAISE EXCEPTION 'Account does not belong to this current space'
    USING ERRCODE='42501';
 END IF;
 IF p_action='remove_partner' AND (me<>owner_id OR member_count<>2) THEN
   RAISE EXCEPTION 'Only the paired owner can remove their current partner'
     USING ERRCODE='42501';END IF;
 IF p_action='leave_space' AND (me=owner_id OR member_count<>2) THEN
   RAISE EXCEPTION 'Only the invited partner can leave this paired space'
     USING ERRCODE='42501';END IF;
 IF p_action='delete_space' AND me<>owner_id THEN
   RAISE EXCEPTION 'Only the owner can delete their shared space'
     USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM public.user_private_spaces ps
   WHERE ps.owner_id=ANY(participants))<>member_count THEN
   RAISE EXCEPTION 'Cannot separate: an account-owned personal namespace is missing'
    USING ERRCODE='42501';END IF;
 -- Preserve all private families, including those without an active UI.
 FOR rec IN
  SELECT c.table_name FROM information_schema.columns c
  WHERE c.table_schema='public'
  GROUP BY c.table_name HAVING bool_or(c.column_name='private_space_id')
 LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE private_space_id=ANY($1)',
    rec.table_name) INTO before_count USING participants;
  before_counts:=before_counts||jsonb_build_object(rec.table_name,before_count);
 END LOOP;

 -- Capture authorized couple media pointers before parent cascading deletes.
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-note-images',n.object_path FROM public.note_images n
 JOIN public.notes parent ON parent.id=n.note_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND n.storage_bucket_id='onespace-note-images'
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-memory-photos',f.object_path FROM public.memory_photos f
 JOIN public.memories parent ON parent.id=f.memory_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND f.storage_bucket_id='onespace-memory-photos'
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-trip-documents',d.object_path FROM public.trip_attachments d
 JOIN public.shared_trips parent ON parent.id=d.trip_id
 WHERE parent.space_id=p_space AND parent.private_space_id IS NULL
   AND d.storage_bucket_id='onespace-trip-documents'
 ON CONFLICT DO NOTHING;
 -- Include interrupted note, memory and trip uploads that lack a
 -- committed metadata row. Guard checks ownership, provenance and pair.
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,o.bucket_id,o.name FROM storage.objects o
 WHERE o.bucket_id IN(
  'onespace-note-images','onespace-memory-photos','onespace-trip-documents')
  AND (
   (o.bucket_id='onespace-note-images' AND EXISTS(
      SELECT 1 FROM public.notes parent
      WHERE parent.id::text=split_part(o.name,'/',1)
      AND parent.space_id=p_space AND parent.private_space_id IS NULL))
   OR (o.bucket_id='onespace-memory-photos' AND EXISTS(
      SELECT 1 FROM public.memories parent
      WHERE parent.id::text=split_part(o.name,'/',1)
      AND parent.space_id=p_space AND parent.private_space_id IS NULL))
   OR (o.bucket_id='onespace-trip-documents' AND EXISTS(
      SELECT 1 FROM public.shared_trips parent
      WHERE parent.id::text=split_part(o.name,'/',1)
      AND parent.space_id=p_space AND parent.private_space_id IS NULL))
  )
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,o.bucket_id,o.name FROM storage.objects o
 WHERE o.bucket_id IN('onespace-activity-media','onespace-activity-voice')
  AND EXISTS(SELECT 1 FROM public.activities a
   WHERE a.id::text=split_part(o.name,'/',1)
    AND a.space_id=p_space AND a.private_space_id IS NULL)
 ON CONFLICT DO NOTHING;
 INSERT INTO public.qa_shared_media_purge_queue(space_id,bucket_id,object_path)
 SELECT p_space,'onespace-share-in',i.file_path FROM public.items_to_sort i
 WHERE i.space_id=p_space AND i.private_space_id IS NULL
   AND i.file_path IS NOT NULL
 ON CONFLICT DO NOTHING;
 SELECT count(*) INTO file_count
  FROM public.qa_shared_media_purge_queue
  WHERE space_id=p_space AND deleted_at IS NULL;
 DELETE FROM public.spaces s WHERE s.id=p_space;
 IF NOT FOUND THEN RAISE EXCEPTION 'Relationship deletion failed; rolled back'
  USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.space_members WHERE space_id=p_space) THEN
  RAISE EXCEPTION 'Former pair membership remains; rolled back'
   USING ERRCODE='42501';END IF;
 IF (SELECT count(*) FROM public.user_private_spaces ps
   WHERE ps.owner_id=ANY(participants))<>member_count THEN
  RAISE EXCEPTION 'Personal namespace was lost; entire deletion rolled back'
   USING ERRCODE='42501';END IF;
 FOR rec IN
  SELECT c.table_name FROM information_schema.columns c
  WHERE c.table_schema='public'
  GROUP BY c.table_name HAVING bool_or(c.column_name='private_space_id')
 LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE private_space_id=ANY($1)',
   rec.table_name) INTO after_count USING participants;
  IF after_count IS DISTINCT FROM (before_counts->>rec.table_name)::bigint THEN
   RAISE EXCEPTION 'Personal content count changed in %, entire deletion rolled back',
    rec.table_name USING ERRCODE='42501';
  END IF;
 END LOOP;
 RETURN jsonb_build_object('status','shared_db_removed_storage_purge_pending',
  'space_id',p_space,'members_unpaired',member_count,
  'media_files_queued',file_count,'action',p_action);
END $q$;
;

-- >>>>> 0295_qa_due_account_support_screenshot_cleanup.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0288_qa_due_account_support_screenshot_cleanup.sql (original number 0288). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA account deletion: include owner-only technical-support screenshot
-- files (ownerUUID/timestamp.jpg or .png). Supabase Auth cannot delete users
-- while these owned objects remain. No Storage API worker is deployed.
ALTER TABLE public.qa_account_private_media_purge_queue
 DROP CONSTRAINT IF EXISTS qa_account_private_media_purge_queue_bucket_id_check;
ALTER TABLE public.qa_account_private_media_purge_queue
 ADD CONSTRAINT qa_account_private_media_purge_queue_bucket_id_check
 CHECK(bucket_id IN('onespace-private-note-images',
 'onespace-private-memory-photos','onespace-private-trip-documents',
 'onespace-private-share-in','onespace-private-activity-media',
 'onespace-private-activity-voice','onespace-support')) NOT VALID;
CREATE OR REPLACE FUNCTION private.qa_inventory_due_private_media(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE deadline timestamptz;found_rows integer;queued integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only due account inventory' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.qa_account_v2_gate
   WHERE id=1 AND enabled) THEN
  RAISE EXCEPTION 'Account purge inventory is not enabled'
    USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN
  RAISE EXCEPTION 'Target user required' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 SELECT r.purge_after INTO deadline
 FROM public.account_deletion_requests r
 WHERE r.user_id=p_user AND r.cancelled_at IS NULL
   AND r.completed_at IS NULL AND r.purge_after<=now()
   AND r.processing_at IS NULL
 FOR UPDATE;
 IF deadline IS NULL THEN
  RAISE EXCEPTION 'Account is not eligible after its full seven-day grace'
   USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_private_spaces p
   WHERE p.owner_id=p_user) THEN
  RAISE EXCEPTION 'Personal scope missing: halt purge'
   USING ERRCODE='42501';
 END IF;
 INSERT INTO public.qa_account_private_media_purge_queue(
   owner_id,bucket_id,object_path)
 SELECT p_user,o.bucket_id,o.name FROM storage.objects o
 WHERE o.bucket_id IN('onespace-private-note-images',
  'onespace-private-memory-photos','onespace-private-trip-documents',
  'onespace-private-share-in',
  'onespace-private-activity-media','onespace-private-activity-voice','onespace-support')
 AND o.owner_id=p_user::text
 AND ((
    o.bucket_id='onespace-private-share-in'
    AND split_part(o.name,'/',1)=p_user::text
    AND o.name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|heic|pdf)$'
   ) OR (
    o.bucket_id='onespace-support'
    AND split_part(o.name,'/',1)=p_user::text
    AND o.name ~ '^[0-9a-f-]{36}/[0-9]{13}[.](png|jpg)$'
   ) OR (
    o.bucket_id NOT IN('onespace-private-share-in','onespace-support')
    AND split_part(o.name,'/',2)=p_user::text
    AND o.name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|m4a|pdf)$'
   ))
 ON CONFLICT DO NOTHING;
 SELECT count(*) INTO queued
 FROM public.qa_account_private_media_purge_queue q
 WHERE q.owner_id=p_user AND q.deleted_at IS NULL;
 SELECT count(*) INTO found_rows
 FROM storage.objects o
 WHERE o.owner_id=p_user::text AND o.bucket_id IN(
 'onespace-private-note-images','onespace-private-memory-photos',
 'onespace-private-trip-documents','onespace-private-share-in',
 'onespace-private-activity-media','onespace-private-activity-voice','onespace-support');
 IF queued<>found_rows THEN
  RAISE EXCEPTION 'Account private Storage inventory incomplete: no deletion permitted'
   USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('eligible',true,'owner_id',p_user,
   'files_queued',queued,'due_at',deadline,
   'next_step','not_activated; verify Auth foreign keys and physical removal');
END $q$;
REVOKE ALL ON FUNCTION private.qa_inventory_due_private_media(uuid)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION private.qa_inventory_due_private_media(uuid)
 TO service_role;

-- QA ONLY. Claim/acknowledge a due account's OWN media after disconnection.
-- SAFE BY DEFAULT: account purge gate remains OFF, app EXECUTE revoked.
-- The file worker must use Storage API remove, never DELETE storage.objects.
CREATE OR REPLACE FUNCTION public.qa_claim_due_account_private_media(p_limit integer DEFAULT 20)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE result jsonb;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only account media purge' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.qa_account_v2_gate
     WHERE id=1 AND enabled) THEN
  RAISE EXCEPTION 'Account media purge gate closed' USING ERRCODE='42501';
 END IF;
 IF p_limit IS NULL OR p_limit<1 OR p_limit>50 THEN
  RAISE EXCEPTION 'Invalid account media purge batch size' USING ERRCODE='22023';
 END IF;
 WITH eligible AS (
  SELECT q.owner_id,q.bucket_id,q.object_path
  FROM public.qa_account_private_media_purge_queue q
  JOIN public.account_deletion_requests r ON r.user_id=q.owner_id
  WHERE q.deleted_at IS NULL
    AND (q.leased_at IS NULL OR q.leased_at<now()-interval '5 minutes')
    AND r.cancelled_at IS NULL AND r.completed_at IS NULL
    AND r.purge_after<=now() AND r.processing_at IS NULL
    -- Never purge files while a pair or a creator-owned space still exists.
    AND NOT EXISTS(SELECT 1 FROM public.space_members m WHERE m.user_id=q.owner_id)
    AND NOT EXISTS(SELECT 1 FROM public.spaces s WHERE s.created_by=q.owner_id)
    AND EXISTS(SELECT 1 FROM public.user_private_spaces p WHERE p.owner_id=q.owner_id)
    -- A valid queue must never delete a file whose Storage owner has changed.
    AND NOT EXISTS(SELECT 1 FROM storage.objects o
      WHERE o.bucket_id=q.bucket_id AND o.name=q.object_path
        AND o.owner_id IS DISTINCT FROM q.owner_id::text)
    -- Keep the account's original folder attribution in every lease.
    AND ((
      q.bucket_id='onespace-private-share-in'
      AND split_part(q.object_path,'/',1)=q.owner_id::text
      AND q.object_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|heic|pdf)$'
    ) OR (
      q.bucket_id='onespace-support'
      AND split_part(q.object_path,'/',1)=q.owner_id::text
      AND q.object_path ~ '^[0-9a-f-]{36}/[0-9]{13}[.](png|jpg)$'
    ) OR (
      q.bucket_id NOT IN('onespace-private-share-in','onespace-support')
      AND split_part(q.object_path,'/',2)=q.owner_id::text
      AND q.object_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}[.](jpg|jpeg|png|webp|m4a|pdf)$'
    ))
  ORDER BY q.queued_at,q.owner_id,q.bucket_id,q.object_path
  FOR UPDATE OF q SKIP LOCKED LIMIT p_limit
 ), leased AS (
  UPDATE public.qa_account_private_media_purge_queue q
    SET lease_id=gen_random_uuid(),leased_at=now(),attempts=q.attempts+1,
        last_error=NULL
  FROM eligible e
  WHERE q.owner_id=e.owner_id AND q.bucket_id=e.bucket_id
    AND q.object_path=e.object_path
  RETURNING q.owner_id,q.bucket_id,q.object_path,q.lease_id,q.attempts
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'owner_id',x.owner_id,'bucket_id',x.bucket_id,'object_path',x.object_path,
  'lease_id',x.lease_id,'attempts',x.attempts)),'[]'::jsonb)
 INTO result FROM leased x;
 RETURN result;
END $q$;

CREATE OR REPLACE FUNCTION public.qa_ack_due_account_private_media(
 p_owner_id uuid,p_bucket_id text,p_object_path text,
 p_lease_id uuid,p_succeeded boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE affected integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only account media purge' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.qa_account_v2_gate
     WHERE id=1 AND enabled) THEN
  RAISE EXCEPTION 'Account media purge gate closed' USING ERRCODE='42501';
 END IF;
 IF p_owner_id IS NULL OR p_bucket_id IS NULL OR p_object_path IS NULL
    OR p_lease_id IS NULL OR p_succeeded IS NULL THEN
  RAISE EXCEPTION 'Complete owner media lease acknowledgement is required'
   USING ERRCODE='22023';
 END IF;
 UPDATE public.qa_account_private_media_purge_queue q SET
  deleted_at=CASE WHEN p_succeeded THEN now() ELSE NULL END,
  last_error=CASE WHEN p_succeeded THEN NULL ELSE 'storage_api_remove_failed' END,
  lease_id=NULL,leased_at=NULL
 WHERE q.owner_id=p_owner_id AND q.bucket_id=p_bucket_id
  AND q.object_path=p_object_path AND q.lease_id=p_lease_id
  AND q.deleted_at IS NULL
  AND EXISTS(SELECT 1 FROM public.account_deletion_requests r
   WHERE r.user_id=q.owner_id AND r.cancelled_at IS NULL
      AND r.completed_at IS NULL AND r.purge_after<=now()
      AND r.processing_at IS NULL)
  AND NOT EXISTS(SELECT 1 FROM public.space_members m WHERE m.user_id=q.owner_id)
  AND NOT EXISTS(SELECT 1 FROM public.spaces s WHERE s.created_by=q.owner_id);
 GET DIAGNOSTICS affected=ROW_COUNT;
 RETURN affected=1;
END $q$;
REVOKE ALL ON FUNCTION public.qa_claim_due_account_private_media(integer)
 FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.qa_ack_due_account_private_media(uuid,text,text,uuid,boolean)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_claim_due_account_private_media(integer)
 TO service_role;
GRANT EXECUTE ON FUNCTION public.qa_ack_due_account_private_media(uuid,text,text,uuid,boolean)
 TO service_role;
;

