 UPDATE public.account_deletion_requests r SET closing_space_id=sp
 WHERE r.user_id=p_user AND r.cancelled_at IS NULL AND r.completed_at IS NULL
  AND r.purge_after<=now() AND r.processing_at IS NULL;
 PERFORM set_config('request.jwt.claim.sub',coalesce(prev_claim,''),true);
 IF EXISTS(SELECT 1 FROM public.space_members m WHERE m.user_id=p_user
     AND m.space_id=sp) OR
  NOT EXISTS(SELECT 1 FROM public.user_private_spaces p
     WHERE p.owner_id=p_user) THEN
  RAISE EXCEPTION 'Relationship close failed to unpair or preserve private data'
    USING ERRCODE='42501';
 END IF;
 RETURN result||jsonb_build_object('due_user_id',p_user,
  'closed_on_behalf_of_due_account',true);
END $q$;
CREATE OR REPLACE FUNCTION public.qa_account_final_deletion_readiness(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE gate_on boolean; preflight jsonb;remaining_objects bigint;
 path_references bigint;unfinished_private_jobs bigint;unfinished_shared_jobs bigint;
 due boolean; fk_count bigint;member_count bigint;created_count bigint;
 legacy_count bigint;personal_exists boolean;ready boolean;closed_space uuid;
 remaining_shared_storage_objects bigint;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only account final readiness' USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN
  RAISE EXCEPTION 'Account user required' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 SELECT enabled INTO gate_on FROM private.qa_account_v2_gate WHERE id=1;
 -- This gate must be explicitly opened only in isolated QA rollback tests
 -- until finalization and independent device verification are complete.
 IF NOT coalesce(gate_on,false) THEN
  RAISE EXCEPTION 'Account finalization gate closed' USING ERRCODE='42501';
 END IF;
 preflight:=public.qa_account_finalizer_preflight(p_user);
 due:=coalesce((preflight->>'due')::boolean,false);
 member_count:=coalesce((preflight->>'member_spaces')::bigint,0);
 created_count:=coalesce((preflight->>'spaces_created')::bigint,0);
 legacy_count:=coalesce((preflight->>'legacy_couple_private_rows')::bigint,0);
 fk_count:=coalesce((preflight->>'unresolved_no_action_user_references')::bigint,0);
 personal_exists:=coalesce((preflight->>'private_namespace_exists')::boolean,false);

 SELECT count(*) INTO remaining_objects FROM storage.objects o
 WHERE o.owner_id=p_user::text;
 -- A service-created object with NULL/different Storage ownership must
 -- not be silently orphaned when its path still contains the deleted owner.
 SELECT count(*) INTO path_references FROM storage.objects o
 WHERE p_user::text=ANY(storage.foldername(o.name));
 SELECT count(*) INTO unfinished_private_jobs
 FROM public.qa_account_private_media_purge_queue q
 WHERE q.owner_id=p_user AND q.deleted_at IS NULL;
 SELECT r.closing_space_id INTO closed_space
 FROM public.account_deletion_requests r
 WHERE r.user_id=p_user AND r.cancelled_at IS NULL AND r.completed_at IS NULL;
 SELECT count(*) INTO unfinished_shared_jobs
 FROM public.qa_shared_media_purge_queue q
 WHERE (q.expected_uploader_id=p_user OR
   (closed_space IS NOT NULL AND q.space_id=closed_space))
  AND q.deleted_at IS NULL;
 -- Even an acknowledged job cannot count as deleted if physical bytes remain,
 -- including objects uploaded by the surviving partner.
 SELECT count(*) INTO remaining_shared_storage_objects
 FROM public.qa_shared_media_purge_queue q
 JOIN storage.objects o ON o.bucket_id=q.bucket_id AND o.name=q.object_path
 WHERE closed_space IS NOT NULL AND q.space_id=closed_space;
 ready:=due AND personal_exists AND member_count=0 AND created_count=0
  AND legacy_count=0 AND fk_count=0
  AND remaining_objects=0 AND path_references=0
  AND unfinished_private_jobs=0 AND unfinished_shared_jobs=0
  AND remaining_shared_storage_objects=0;
 RETURN jsonb_build_object(
  'ready_for_auth_delete',ready,'due',due,
  'private_namespace_exists',personal_exists,
  'remaining_relationship_memberships',member_count,
  'remaining_created_spaces',created_count,
  'legacy_couple_private_rows',legacy_count,
  'unresolved_auth_user_fk_references',fk_count,
  'remaining_storage_objects_owned',remaining_objects,
  'remaining_storage_folder_references',path_references,
  'unfinished_private_file_purges',unfinished_private_jobs,
  'unfinished_shared_file_purges',unfinished_shared_jobs,
  'remaining_shared_storage_objects',remaining_shared_storage_objects,
  'closed_relationship_space_id',closed_space,
  'actual_auth_deletion_not_implemented',true);
END $q$;
CREATE OR REPLACE FUNCTION public.qa_scrub_completed_account_media_jobs(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE verified jsonb;own_count integer;shared_count integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Service-only completed account media audit cleanup'
   USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN RAISE EXCEPTION 'Owner required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,1));
 verified:=public.qa_account_final_deletion_readiness(p_user);
 IF verified->>'ready_for_auth_delete'<>'true' THEN
  RAISE EXCEPTION 'Cannot clear any audit while account deletion prerequisites remain'
   USING ERRCODE='42501';
 END IF;
 DELETE FROM public.qa_account_private_media_purge_queue q
 WHERE q.owner_id=p_user AND q.deleted_at IS NOT NULL;
 GET DIAGNOSTICS own_count=ROW_COUNT;
 DELETE FROM public.qa_shared_media_purge_queue q
 WHERE q.deleted_at IS NOT NULL AND (
  q.expected_uploader_id=p_user OR EXISTS(
   SELECT 1 FROM public.account_deletion_requests r
   WHERE r.user_id=p_user AND r.closing_space_id=q.space_id
    AND r.cancelled_at IS NULL AND r.completed_at IS NULL
  )
 );
 GET DIAGNOSTICS shared_count=ROW_COUNT;
 RETURN jsonb_build_object('completed_private_jobs_scrubbed',own_count,
  'completed_shared_jobs_scrubbed',shared_count,
  'account_user_deleted',false);
END $q$;
;

-- >>>>> 0301_qa_atomic_finalization_claim_and_client_write_fence.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0294_qa_atomic_finalization_claim_and_client_write_fence.sql (original number 0294). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA ONLY: close the multi-request race between read-only readiness,
-- media audit scrub, cancellation/pairing and the external Auth Admin API.
-- Once claimed, processing is sticky and cannot be automatically retried.
-- Admin must manually reconcile a failed Auth deletion. No QA gate is opened.
ALTER TABLE public.account_deletion_requests
 ADD COLUMN IF NOT EXISTS finalization_claim_id uuid;

CREATE OR REPLACE FUNCTION public.qa_claim_account_for_auth_finalization(p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE record_request record; before_readiness jsonb;after_readiness jsonb;
      scrubbed jsonb;claimed uuid:=gen_random_uuid();changed integer;
BEGIN
 IF current_user<>'service_role' THEN
  RAISE EXCEPTION 'Only trusted service may claim account finalization'
   USING ERRCODE='42501';
 END IF;
 IF p_user IS NULL THEN RAISE EXCEPTION 'Account id required' USING ERRCODE='22023';END IF;
 -- Pair/invite/cancel use precisely this lock namespace.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,5));
 SELECT r.purge_after,r.cancelled_at,r.completed_at,r.processing_at,
        r.finalization_claim_id INTO record_request
 FROM public.account_deletion_requests r WHERE r.user_id=p_user FOR UPDATE;
 IF NOT FOUND OR record_request.cancelled_at IS NOT NULL
  OR record_request.completed_at IS NOT NULL
  OR record_request.processing_at IS NOT NULL
  OR record_request.finalization_claim_id IS NOT NULL
  OR record_request.purge_after>now() THEN
  RAISE EXCEPTION 'Account is not eligible for first and only finalization claim'
   USING ERRCODE='42501';
 END IF;
 before_readiness:=public.qa_account_final_deletion_readiness(p_user);
 IF before_readiness->>'ready_for_auth_delete'<>'true' THEN
  RAISE EXCEPTION 'Cannot claim account: shared/private data or Storage objects remain'
   USING ERRCODE='42501';
 END IF;
 -- Atomic with readiness + claim; rollback restores completed metadata on fail.
 scrubbed:=public.qa_scrub_completed_account_media_jobs(p_user);
 after_readiness:=public.qa_account_final_deletion_readiness(p_user);
 IF after_readiness->>'ready_for_auth_delete'<>'true' THEN
  RAISE EXCEPTION 'Post-scrub final deletion readiness changed'
   USING ERRCODE='42501';
 END IF;
 UPDATE public.account_deletion_requests r
  SET processing_at=now(),finalization_claim_id=claimed,last_error=NULL
 WHERE r.user_id=p_user AND r.processing_at IS NULL AND r.cancelled_at IS NULL
   AND r.completed_at IS NULL AND r.finalization_claim_id IS NULL
   AND r.purge_after<=now();
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'Concurrent finalization or cancellation'
    USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('claimed',true,'user_id',p_user,
  'claim_id',claimed,'readiness',after_readiness,'scrub',scrubbed);
END $q$;
REVOKE ALL ON FUNCTION public.qa_claim_account_for_auth_finalization(uuid)
 FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.qa_claim_account_for_auth_finalization(uuid)
 TO service_role;

-- A claim is not an advisory lock spanning HTTP requests. Instead the
-- processed request becomes an immutable DB fence; all normal client DML
-- on supported public user-writable tables is denied through a trigger.
CREATE OR REPLACE FUNCTION private.qa_is_account_in_finalization(p_user uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $q$
 SELECT p_user IS NOT NULL AND auth.uid()=p_user AND EXISTS(
 SELECT 1 FROM public.account_deletion_requests r
 WHERE r.user_id=p_user AND r.processing_at IS NOT NULL
 AND r.finalization_claim_id IS NOT NULL
 AND r.cancelled_at IS NULL AND r.completed_at IS NULL);
$q$;
REVOKE ALL ON FUNCTION private.qa_is_account_in_finalization(uuid)
 FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.qa_is_account_in_finalization(uuid)
 TO authenticated;

CREATE OR REPLACE FUNCTION private.qa_reject_finalizing_user_writes()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
BEGIN
 -- Authenticated client DML only; backend cascade, service cleanup and
 -- the privileged Auth Admin path remain unaffected.
 IF current_user='authenticated' AND auth.uid() IS NOT NULL
   AND private.qa_is_account_in_finalization(auth.uid()) THEN
  RAISE EXCEPTION 'Account finalization has started; content changes are disabled'
   USING ERRCODE='42501';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 RETURN NEW;
END $q$;
REVOKE ALL ON FUNCTION private.qa_reject_finalizing_user_writes()
 FROM PUBLIC,anon,authenticated;
-- Guard all public tables that the authenticated role can directly mutate,
-- not just the 24 private roots. Do not touch Auth/Storage internal tables.
DO $installer$
DECLARE t record;
BEGIN
 FOR t IN
  SELECT c.relname
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind IN('r','p')
   AND (has_table_privilege('authenticated',c.oid,'INSERT')
    OR has_table_privilege('authenticated',c.oid,'UPDATE')
    OR has_table_privilege('authenticated',c.oid,'DELETE'))
  ORDER BY c.relname
 LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS qa_finalization_write_fence ON public.%I',
   t.relname);
  EXECUTE format('CREATE TRIGGER qa_finalization_write_fence
    BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW
    EXECUTE FUNCTION private.qa_reject_finalizing_user_writes()',t.relname);
 END LOOP;
END $installer$;
;

-- >>>>> 0302_qa_authenticated_relationship_end_entrypoint_gate_off.sql
-- Reconciled 2026-11-20: applied to QA (ugwrpeduzyzrujkizqfo) on 2026-11-20 from
-- qa/activities-memories-two-scope-cutover-20261120:supabase/schema/0295_qa_authenticated_relationship_end_entrypoint_gate_off.sql (original number 0295). Kept verbatim so the
-- repository replays to the live QA schema. QA only; never apply to Production.
-- QA-only authenticated entrypoint for irreversible couple separation.
-- The substantive SECURITY DEFINER private transaction validates actor,
-- ownership, exact current pair, permanent private spaces and typed warning.
-- This public facade grants no bypass while the DB gate remains OFF.
CREATE OR REPLACE FUNCTION public.qa_end_current_relationship(
 p_space uuid,p_action text,p_confirmation text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $q$
DECLARE me uuid:=auth.uid();
BEGIN
 IF me IS NULL OR p_space IS NULL THEN
  RAISE EXCEPTION 'Authenticated existing relationship required' USING ERRCODE='42501';
 END IF;
 IF p_action NOT IN('remove_partner','leave_space','delete_space')
  OR p_confirmation IS DISTINCT FROM 'DELETE SHARED CONTENT' THEN
  RAISE EXCEPTION 'Explicit irreversible confirmation required' USING ERRCODE='42501';
 END IF;
 -- Refuse absent-or-synthetic actor. RLS in private transaction also
 -- checks membership and exact owner/guest rules.
 IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=me) THEN
  RAISE EXCEPTION 'Account no longer exists' USING ERRCODE='42501';
 END IF;
 RETURN private.qa_close_relationship_v2(p_space,p_action,p_confirmation);
END $q$;
REVOKE ALL ON FUNCTION public.qa_end_current_relationship(uuid,text,text)
 FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.qa_end_current_relationship(uuid,text,text)
 TO authenticated;
;

