-- >>>>> 0304_qa_reconcile_live_lifecycle_functions_and_gates.sql
-- QA 0304: reconcile the repository with the live QA database (2026-11-20).
--
-- 0243–0303 replay migrations that were applied to QA from unmerged branches.
-- A whitespace-normalised comparison of all 73 functions those files define
-- against live QA found 71 identical. The two below were changed in QA after
-- their source file was written, so the live definitions are recorded here.
-- Neither function is reachable by clients (EXECUTE revoked; gates are off).
--
-- The tail re-asserts the destructive-lifecycle safety state that is live in
-- QA, because 0244 (originally 0239) grants EXECUTE on end_shared_space and
-- would otherwise re-open it on a fresh replay.
-- QA only; never apply to Production.

CREATE OR REPLACE FUNCTION private.end_couple_space(p_space uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  t text; n bigint; v_private bigint:=0; v_members int;
begin
  perform 1 from public.spaces
   where id=p_space and personal_owner is null for update;
  if not found then return jsonb_build_object('status','already_ended'); end if;
  select count(*) into v_members from public.space_members where space_id=p_space;
  foreach t in array array['activities','daily_checkins','goals','items_to_sort',
    'memories','occasion_plans','places','saved_contacts','shared_trips',
    'space_counters','notes','tasks','reminders','space_events'] loop
    execute format('select count(*) from public.%I where space_id=$1 and visibility=''private''',t)
      into n using p_space;
    v_private:=v_private+n;
  end loop;
  if v_private>0 then
    raise exception 'Nothing was deleted: % private item(s) are still stored in the shared space. Please contact support.',
      v_private using errcode='P0001';
  end if;
  delete from public.occasion_proposal_items i
   using public.occasion_proposals p, public.occasion_plans o
   where i.proposal_id=p.id and p.plan_id=o.id and o.space_id=p_space;
  if to_regclass('public.qa_archive_job_progress') is not null then
    execute 'delete from public.qa_archive_job_progress where original_space_id=$1' using p_space;
  end if;
  if to_regclass('public.space_lifecycle_jobs') is not null then
    execute 'update public.space_lifecycle_jobs set status=''cancelled'', last_transition_at=now()
               where original_space_id=$1 and status not in (''cancelled'',''completed'')' using p_space;
  end if;
  delete from public.spaces where id=p_space;
  return jsonb_build_object('status','ended','members_unpaired',v_members);
end
$function$;

CREATE OR REPLACE FUNCTION public.purge_account_content(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_due boolean; v_couple uuid; v_personal uuid; v_couple_result jsonb:='{}'::jsonb;
begin
  select true into v_due from public.account_deletion_requests
   where user_id=p_user and cancelled_at is null and completed_at is null
     and purge_after<=now()
   for update;
  if not coalesce(v_due,false) then
    return jsonb_build_object('status','not_due');
  end if;
  v_couple:=private.couple_space_id(p_user);
  if v_couple is not null then
    v_couple_result:=private.end_couple_space(v_couple);
  end if;
  delete from public.space_members where user_id=p_user;
  select id into v_personal from public.spaces where personal_owner=p_user;
  if v_personal is not null then
    delete from public.occasion_proposal_items i
     using public.occasion_proposals p, public.occasion_plans o
     where i.proposal_id=p.id and p.plan_id=o.id and o.space_id=v_personal;
    delete from public.spaces where id=v_personal;
  end if;
  delete from public.notes where private_space_id=p_user;
  delete from public.tasks where private_space_id=p_user;
  delete from public.reminders where private_space_id=p_user;
  delete from public.space_events where private_space_id=p_user;
  delete from public.record_action_history where private_space_id=p_user;
  delete from public.space_notifications where private_space_id=p_user or recipient_id=p_user;
  delete from public.user_private_spaces where owner_id=p_user;
  delete from public.push_devices where user_id=p_user;
  delete from public.personal_days_off where user_id=p_user;
  delete from public.user_attention_snoozes where user_id=p_user;
  delete from public.gesture_message_overrides where owner_id=p_user;
  return jsonb_build_object('status','content_deleted','couple',v_couple_result);
end
$function$;

revoke all on function private.end_couple_space(uuid) from public,anon,authenticated;
revoke all on function public.purge_account_content(uuid) from public,anon,authenticated;

-- Destructive lifecycle stays closed (matches live QA on 2026-11-20).
revoke all on function public.end_shared_space(text,text) from public,anon,authenticated;
revoke all on function public.request_account_deletion() from public,anon,authenticated;
insert into private.qa_relationship_v2_gate(id,enabled) values(1,false)
  on conflict(id) do update set enabled=false;
insert into private.qa_account_v2_gate(id,enabled) values(1,false)
  on conflict(id) do update set enabled=false;
;

-- >>>>> 0305_qa_personal_scrapbooks_and_memory_photo_scope.sql
-- QA 0305: personal (account-owned) scrapbooks, and keep Memory photo bytes
-- in the bucket that matches their Memory's scope.
--
-- Before this file, in QA:
--  * create_scrapbook(p_visibility=>'private') inserted a couple-scoped private
--    Memory, which route_record_scope refuses ("Update your app ..."), so no
--    private scrapbook could be created, and a solo account could not create one.
--  * scrapbook_pages for account-owned Memories were blocked outright.
--  * the legacy shared-bucket and memory_photos policies still let an owner
--    attach a personal Memory's photo to the SHARED bucket (e.g. older app).
--  * validate_scrapbook_page_photos ignored photo_4_id.
-- QA only; never apply to Production.

-- 0. 0246 allowed only 'story' Memories in the personal scope. Personal
--    scrapbooks are now supported too (daily selfies and collages stay couple-only).
alter table public.memories drop constraint if exists qa_private_memories_story_only;
alter table public.memories add constraint qa_private_memories_story_only
 check(private_space_id is null or memory_type in ('story','scrapbook')) not valid;

-- 1. Scrapbook creation follows the ADR scopes.
create or replace function public.create_scrapbook(
  p_space_id uuid, p_title text, p_template_key text,
  p_visibility text default 'shared', p_memory_date date default current_date)
returns uuid language plpgsql security definer set search_path to ''
as $function$
declare result uuid; who uuid:=auth.uid();
begin
 if who is null
    or char_length(btrim(coalesce(p_title,''))) not between 1 and 120
    or p_template_key not in (
     'polaroid_letters','our_adventures','little_moments','milestone_story',
     'first_date','date_night','anniversary_gold','birthday_bash','eid_joy','ramadan_nights',
     'family_day','our_home','miles_apart','little_one','cooked_together','love_note',
     'film_strip','postcard','year_in_review','four_seasons','graduation','wedding_day')
    or p_visibility not in ('shared','private')
    or p_memory_date not between date '1900-01-01' and date '2100-12-31' then
   raise exception 'Invalid scrapbook request';
 end if;
 if p_visibility='private' then
   -- Private scrapbooks always belong to the account, never to a couple.
   if not exists(select 1 from public.user_private_spaces s where s.owner_id=who) then
     raise exception 'Personal space unavailable' using errcode='42501';
   end if;
   insert into public.memories(private_space_id,space_id,created_by,title,body,
     memory_date,visibility,memory_type,photo_layout)
   values(who,null,who,btrim(p_title),'',p_memory_date,'private','scrapbook','grid')
   returning id into result;
 else
   if p_space_id is null or not private.is_space_member(p_space_id)
      or (select count(*) from public.space_members m where m.space_id=p_space_id)<>2 then
     raise exception 'Join a partner before creating a shared scrapbook'
       using errcode='42501';
   end if;
   insert into public.memories(space_id,created_by,title,body,memory_date,
     visibility,memory_type,photo_layout)
   values(p_space_id,who,btrim(p_title),'',p_memory_date,'shared','scrapbook','grid')
   returning id into result;
 end if;
 insert into public.scrapbook_pages(memory_id,page_order,template_key,created_by,title)
 values(result,0,p_template_key,who,btrim(p_title));
 return result;
end $function$;
revoke all on function public.create_scrapbook(uuid,text,text,text,date) from public,anon;
grant execute on function public.create_scrapbook(uuid,text,text,text,date) to authenticated;

-- 2. Who may edit pages: the owner of a personal scrapbook, or (shared) the
--    creator / an accepted invitee who is still in that couple.
create or replace function private.may_edit_scrapbook(p_memory uuid, p_user uuid)
returns boolean language sql stable security definer set search_path to ''
as $function$
 select exists(select 1 from public.memories m
  where m.id=p_memory and m.memory_type='scrapbook' and m.archived_at is null
   and (
    (m.private_space_id is not null and m.private_space_id=p_user
       and m.created_by=p_user and m.space_id is null and m.visibility='private')
    or
    (m.private_space_id is null and m.space_id is not null
       and exists(select 1 from public.space_members sm
                  where sm.space_id=m.space_id and sm.user_id=p_user)
       and (m.created_by=p_user or (
         m.visibility='shared' and exists(
           select 1 from public.scrapbook_invites i
           where i.memory_id=m.id and i.invited_user_id=p_user
             and i.status='accepted'))))
   ))
$function$;
revoke all on function private.may_edit_scrapbook(uuid,uuid) from public,anon;
grant execute on function private.may_edit_scrapbook(uuid,uuid) to authenticated;

-- 3. Personal scrapbook pages are now supported (owner only, via may_edit).
drop policy if exists "QA personal memories no scrapbook page writes" on public.scrapbook_pages;
drop policy if exists "QA personal memories no scrapbook page updates" on public.scrapbook_pages;
drop trigger if exists qa_block_private_scrapbook_page on public.scrapbook_pages;

-- 4. Every photo slot (including the fourth) must be a live photo of this Memory.
create or replace function private.validate_scrapbook_page_photos()
returns trigger language plpgsql set search_path to ''
as $function$
declare requested uuid; ok boolean;
begin
 if tg_op='UPDATE' and new.memory_id<>old.memory_id then
   raise exception 'Cannot transfer a scrapbook page to another memory';
 end if;
 for requested in select distinct unnest(array[
   new.photo_1_id,new.photo_2_id,new.photo_3_id,new.photo_4_id
 ]) loop
  if requested is not null then
    select exists(select 1 from public.memory_photos p
      where p.id=requested and p.memory_id=new.memory_id and p.archived_at is null)
    into ok;
    if not ok then raise exception 'Scrapbook photo is not part of this memory';end if;
  end if;
 end loop;
 new.updated_at=now();
 new.updated_by=auth.uid();
 return new;
end $function$;

-- 5. Legacy photo policies cover couple-scoped Memories only, in the shared bucket.
drop policy if exists "Owner can add photo to editable memory" on public.memory_photos;
create policy "Owner can add photo to editable memory" on public.memory_photos
 for insert to authenticated
 with check (created_by=(select auth.uid())
   and storage_bucket_id='onespace-memory-photos'
   and exists(select 1 from public.memories m
     where m.id=memory_photos.memory_id and m.private_space_id is null
       and (m.visibility='shared' or m.created_by=(select auth.uid()))));
drop policy if exists "Member can edit photo of collaborative memory" on public.memory_photos;
create policy "Member can edit photo of collaborative memory" on public.memory_photos
 for update to authenticated
 using (exists(select 1 from public.memories m
     where m.id=memory_photos.memory_id and m.private_space_id is null
       and (m.visibility='shared' or m.created_by=(select auth.uid()))))
 with check (storage_bucket_id='onespace-memory-photos'
   and exists(select 1 from public.memories m
     where m.id=memory_photos.memory_id and m.private_space_id is null
       and (m.visibility='shared' or m.created_by=(select auth.uid()))));

drop policy if exists "Upload own photo under editable memory" on storage.objects;
create policy "Upload own photo under editable memory" on storage.objects
 for insert to authenticated
 with check (bucket_id='onespace-memory-photos'
   and split_part(name,'/',2)=(select auth.uid())::text
   and exists(select 1 from public.memories m
     where m.id=private.memory_id_from_object_path(objects.name)
       and m.private_space_id is null
       and (m.visibility='shared' or m.created_by=(select auth.uid()))));
drop policy if exists "Remove only own unreferenced memory upload" on storage.objects;
create policy "Remove only own unreferenced memory upload" on storage.objects
 for delete to authenticated
 using (bucket_id='onespace-memory-photos'
   and split_part(name,'/',2)=(select auth.uid())::text
   and not exists(select 1 from public.memory_photos p where p.object_path=objects.name)
   and exists(select 1 from public.memories m
     where m.id=private.memory_id_from_object_path(objects.name)
       and m.private_space_id is null
       and (m.visibility='shared' or m.created_by=(select auth.uid()))));
;

-- >>>>> 0306_qa_personal_reminder_sources_own_items_only.sql
-- QA 0306: an account-owned reminder may point at one of the SAME account's
-- personal items (e.g. "Remind me" on a personal Activity), never at a couple's
-- shared item and never at someone else's item.
--
-- Before: every personal reminder with a source was refused, so "Remind me"
-- from a personal Activity, To-do, Calendar event, Occasion, Trip or Note failed.
-- Why only own personal items: a personal reminder survives a breakup, while a
-- shared source is erased with the couple; it would strand or leak the link.
-- Couple-scoped reminders keep their existing rules unchanged.
-- QA only; never apply to Production.

create or replace function private.reminder_validate_source()
returns trigger language plpgsql security definer set search_path to ''
as $function$
declare allowed boolean:=false;
begin
 if new.source_kind is null then return new; end if;
 if new.private_space_id is not null then
   if new.private_space_id is distinct from new.created_by then
     raise exception 'Personal reminder owner mismatch' using errcode='42501';
   end if;
   if new.source_kind='task' then
    select exists(select 1 from public.tasks t where t.id=new.source_id
      and t.private_space_id=new.private_space_id and t.created_by=new.created_by
      and t.space_id is null and t.migrated_to_list is null) into allowed;
   elsif new.source_kind='calendar' then
    select exists(select 1 from public.space_events e where e.id=new.source_id
      and e.private_space_id=new.private_space_id and e.created_by=new.created_by
      and e.space_id is null and e.archived_at is null) into allowed;
   elsif new.source_kind='occasion' then
    select exists(select 1 from public.occasion_plans o where o.id=new.source_id
      and o.private_space_id=new.private_space_id and o.created_by=new.created_by
      and o.space_id is null and o.archived_at is null) into allowed;
   elsif new.source_kind='activity' then
    select exists(select 1 from public.activities a where a.id=new.source_id
      and a.private_space_id=new.private_space_id and a.created_by=new.created_by
      and a.space_id is null and a.archived_at is null) into allowed;
   elsif new.source_kind='trip' then
    select exists(select 1 from public.shared_trips t where t.id=new.source_id
      and t.private_space_id=new.private_space_id and t.created_by=new.created_by
      and t.space_id is null and t.archived_at is null) into allowed;
   elsif new.source_kind='note' then
    select exists(select 1 from public.notes n where n.id=new.source_id
      and n.private_space_id=new.private_space_id and n.created_by=new.created_by
      and n.space_id is null and n.archived_at is null) into allowed;
   end if;
   if not allowed then
     raise exception 'A personal reminder can only link to your own personal items'
       using errcode='42501';
   end if;
   return new;
 end if;
 if new.source_kind='task' then
  select exists(select 1 from public.tasks t
   where t.id=new.source_id and t.space_id=new.space_id and t.migrated_to_list is null
    and (t.visibility='shared' or (new.visibility='private' and t.created_by=new.created_by))) into allowed;
 elsif new.source_kind='calendar' then
  select exists(select 1 from public.space_events e
   where e.id=new.source_id and e.space_id=new.space_id and e.archived_at is null
    and (e.visibility='shared' or (new.visibility='private' and e.created_by=new.created_by))) into allowed;
 elsif new.source_kind='occasion' then
  select exists(select 1 from public.occasion_plans o
   where o.id=new.source_id and o.space_id=new.space_id and o.archived_at is null
    and (o.visibility='shared' or (new.visibility='private' and o.created_by=new.created_by))) into allowed;
 elsif new.source_kind='activity' then
  select exists(select 1 from public.activities a
   where a.id=new.source_id and a.space_id=new.space_id and a.archived_at is null
    and (a.visibility='shared' or (new.visibility='private' and a.created_by=new.created_by))) into allowed;
 elsif new.source_kind='trip' then
  select exists(select 1 from public.shared_trips t
   where t.id=new.source_id and t.space_id=new.space_id and t.archived_at is null
    and (t.visibility='shared' or (new.visibility='private' and t.created_by=new.created_by))) into allowed;
 elsif new.source_kind='note' then
  select exists(select 1 from public.notes n
   where n.id=new.source_id and n.space_id=new.space_id and n.archived_at is null
    and (n.visibility='shared' or (new.visibility='private' and n.created_by=new.created_by))) into allowed;
 end if;
 if not allowed then
  raise exception 'Linked item unavailable or not visible to reminder recipients';
 end if;
 return new;
end $function$;

-- The insert policy no longer forbids a source; the trigger above decides.
drop policy if exists "QA account owner creates private reminders" on public.reminders;
create policy "QA account owner creates private reminders" on public.reminders
 for insert to authenticated
 with check (private_space_id=(select auth.uid()) and created_by=(select auth.uid())
   and visibility='private' and audience='me' and space_id is null
   and ((source_kind is null and source_id is null)
        or (source_kind is not null and source_id is not null)));

-- 0234 also required no source in the table check and the edit policy, which
-- would block saving such a reminder or later editing / completing it.
-- Scope, ownership and the source stay immutable (qa_lock_personal_root_scope).
alter table public.reminders drop constraint if exists qa_private_reminder_audience;
alter table public.reminders add constraint qa_private_reminder_audience
 check(private_space_id is null or
  (audience='me' and visibility='private' and urgent=false
   and ((source_kind is null and source_id is null)
        or (source_kind is not null and source_id is not null)))) not valid;

drop policy if exists "QA account owner edits private reminders" on public.reminders;
create policy "QA account owner edits private reminders" on public.reminders
 for update to authenticated
 using(private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and audience='me' and space_id is null)
 with check(private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and audience='me' and space_id is null
  and ((source_kind is null and source_id is null)
       or (source_kind is not null and source_id is not null)));
;

-- >>>>> 0307_qa_personal_activity_contact_and_link_cards.sql
-- QA 0307: personal Activities may hold Contact information and Link cards.
--
-- Before: the personal-child guard (0280) refused 'contact' and 'link', but the
-- app offers both on every Activity, so adding a contact or a website to a
-- personal Activity failed with "This personal Activity component is
-- unsupported". Both are plain text in the component payload: no Storage
-- object and no reference to another record, so they follow the parent
-- Activity's owner-only access like a note does. Everything else is unchanged.
-- QA only; never apply to Production.

CREATE OR REPLACE FUNCTION private.qa_personal_activity_child_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE p record; a_id uuid:=(to_jsonb(new)->>'activity_id')::uuid;
 me uuid:=auth.uid();component uuid;
BEGIN
 SELECT a.space_id,a.private_space_id,a.created_by,a.visibility
 INTO p FROM public.activities a WHERE a.id=a_id;
 IF NOT FOUND OR p.private_space_id IS NULL THEN RETURN new;END IF;
 IF me IS NULL OR p.private_space_id IS DISTINCT FROM me
   OR p.created_by IS DISTINCT FROM me
   OR p.space_id IS NOT NULL OR p.visibility<>'private' THEN
   RAISE EXCEPTION 'Only the account owner may edit personal Activity children'
     USING ERRCODE='42501';
 END IF;
 IF tg_table_name='activity_components' THEN
  IF new.created_by IS DISTINCT FROM me OR new.kind NOT IN
   ('note','option','step','date','price','spec','reminder','tag',
    'location','countdown','image','voice','contact','link') THEN
   RAISE EXCEPTION 'This personal Activity component is unsupported'
    USING ERRCODE='42501';
  END IF;
  component:=new.parent_component_id;
 ELSIF tg_table_name='activity_comments' THEN
  IF new.author_id IS DISTINCT FROM me OR
    (new.voice_path IS NOT NULL AND
     (new.voice_bucket_id<>'onespace-private-activity-voice'
      OR new.voice_seconds IS NULL)) THEN
   RAISE EXCEPTION 'Personal Activity voice must be account-owned'
    USING ERRCODE='42501';
  END IF;
  component:=new.component_id;
  IF new.reply_to IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.activity_comments c
    WHERE c.id=new.reply_to AND c.activity_id=a_id) THEN
    RAISE EXCEPTION 'Reply must belong to this Activity' USING ERRCODE='42501';
  END IF;
 END IF;
 IF component IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.activity_components c
   WHERE c.id=component AND c.activity_id=a_id) THEN
   RAISE EXCEPTION 'Component parent belongs to another Activity'
    USING ERRCODE='42501';
 END IF;
 RETURN new;
END $q$;
REVOKE ALL ON FUNCTION private.qa_personal_activity_child_guard()
 FROM public,anon,authenticated;
;

-- >>>>> 0308_qa_fix_attachment_immutability_trigger.sql
-- QA 0308: fix the attachment immutability trigger from 0265.
--
-- Before: the function read old.note_id inside "tg_table_name='note_images' AND
-- old.note_id ...". PL/pgSQL resolves record fields even when the first test is
-- false, so EVERY client update of a memory_photos or trip_attachments row
-- failed with 'record "old" has no field "note_id"'. Removing a Memory photo,
-- editing its caption or reordering photos, and editing travel documents, all
-- broke in QA. Found by qa_personal_media_storage_access.sql.
-- Rules are unchanged: bucket, path, author, id and parent stay immutable.
-- QA only; never apply to Production.

CREATE OR REPLACE FUNCTION private.qa_attachment_scope_immutable()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $q$
DECLARE parent_column text;
BEGIN
 IF current_user NOT IN ('authenticated','anon') THEN RETURN new;END IF;
 IF tg_op<>'UPDATE' THEN RETURN new;END IF;
 IF old.storage_bucket_id IS DISTINCT FROM new.storage_bucket_id OR
    old.object_path IS DISTINCT FROM new.object_path OR
    old.created_by IS DISTINCT FROM new.created_by OR
    old.id IS DISTINCT FROM new.id THEN
   RAISE EXCEPTION 'Attachment ownership and storage path are immutable' USING ERRCODE='42501';
 END IF;
 parent_column:=CASE tg_table_name
   WHEN 'note_images' THEN 'note_id'
   WHEN 'memory_photos' THEN 'memory_id'
   WHEN 'trip_attachments' THEN 'trip_id' END;
 IF parent_column IS NOT NULL AND
    (to_jsonb(old)->>parent_column) IS DISTINCT FROM (to_jsonb(new)->>parent_column) THEN
   RAISE EXCEPTION 'Attachment parent cannot change' USING ERRCODE='42501';
 END IF;
 RETURN new;
END $q$;
REVOKE ALL ON FUNCTION private.qa_attachment_scope_immutable() FROM PUBLIC,anon,authenticated;
;

-- >>>>> 0309_qa_partner_joined_notification.sql
-- QA 0309: tell the space owner when their partner joins.
--
-- Before: joining a space created no notification, so the inviter only found
-- out by reopening the app. Adds a 'joined' notification (push text in English
-- and Arabic) sent to the existing member when a second person joins.
-- compose_notification_text is the 0109 version plus the 'joined' branch.
-- QA only; never apply to Production.

alter table public.space_notifications drop constraint if exists space_notifications_kind_check;
alter table public.space_notifications add constraint space_notifications_kind_check check (kind = any (array[
    'mention','reply','letter','event','gesture','reminder','checkin_request',
    'checkin_response','checkin_shared','experience_suggestion','experience_comment',
    'trip_suggestion','trip_message','trip_document','occasion_shared','scrapbook_invite',
    'message','created','change','joined'])) not valid;

create or replace function private.compose_notification_text()
returns trigger language plpgsql security definer set search_path to '' as $$
declare
 ar boolean; who text; t text; b text; title text:=private.notice_bare_title(new.headline);
 g text; thing text; verb text;
begin
 -- Keep the push schedule in step for writers that only touch created_at.
 if tg_op='INSERT' then
   new.push_due_at:=coalesce(new.push_due_at,new.created_at,now());
 elsif new.created_at is distinct from old.created_at
   and new.push_due_at is not distinct from old.push_due_at then
   new.push_due_at:=new.created_at; new.batch_count:=1;
 end if;

 select coalesce(p.locale,'en')='ar' into ar from public.profiles p where p.id=new.recipient_id;
 ar:=coalesce(ar,false);
 who:=private.notice_partner_name(new.recipient_id,new.actor_id);

 if new.kind='gesture' then
   select pg.kind into g from public.partner_gestures pg where pg.id=new.object_id;
   t:=who||' '||case when ar then case g
       when 'hug' then 'أرسل لك حضنًا' when 'thinking' then 'يفكر فيك'
       when 'smile' then 'أرسل لك ابتسامة' when 'morning' then 'يقول صباح الخير'
       when 'goodnight' then 'يقول تصبح على خير' when 'proud' then 'فخور بك'
       when 'support' then 'معك' when 'thanks' then 'يشكرك'
       when 'lucky' then 'محظوظ بك' when 'miss_you' then 'يشتاق إليك'
       else 'أرسل لك لمسة حب' end
     else case g
       when 'hug' then 'sent you a hug' when 'thinking' then 'is thinking of you'
       when 'smile' then 'sent you a smile' when 'morning' then 'says good morning'
       when 'goodnight' then 'says good night' when 'proud' then 'is proud of you'
       when 'support' then 'is right here with you' when 'thanks' then 'says thank you'
       when 'lucky' then 'feels lucky to have you' when 'miss_you' then 'misses you'
       when 'miss_together' then 'misses being together' when 'miss_home' then 'misses home'
       when 'miss_kids' then 'misses the kids' when 'miss_pets' then 'misses the pets'
       else 'sent you a little love' end end;
   b:=new.headline;
 elsif new.kind='letter' then
   t:=who||case when ar then ' أرسل لك رسالة' else ' sent you a letter' end; b:=title;
 elsif new.kind='mention' then
   t:=who||case when ar then ' أشار إليك في ' else ' mentioned you in ' end||title;
   b:=coalesce(new.detail,title);
 elsif new.kind='reply' then
   t:=who||case when ar then ' ردّ عليك · ' else ' replied to you · ' end||title;
   b:=coalesce(new.detail,title);
 elsif new.kind in ('message','trip_message','experience_comment') then
   t:=who||' · '||title;
   b:=coalesce(new.detail,case when ar then 'رسالة جديدة' else 'New message' end);
 elsif new.kind='event' then
   t:=who||case when ar then ' أضاف موعدًا' else ' added an event' end;
   b:=title||coalesce(' · '||new.detail,'');
 elsif new.kind='trip_suggestion' then
   t:=who||case when ar then ' أضاف رحلة' else ' added a trip' end; b:=title;
 elsif new.kind='trip_document' then
   t:=who||case when ar then ' شارك مستند سفر' else ' shared a travel document' end; b:=title;
 elsif new.kind='occasion_shared' then
   t:=who||case when ar then ' خطط لمناسبة' else ' planned an occasion' end; b:=title;
 elsif new.kind='experience_suggestion' then
   t:=who||case when ar then ' اقترح تجربة' else ' suggested an experience' end; b:=title;
 elsif new.kind='checkin_request' then
   t:=who||case when ar then ' يطمئن عليك' else ' is checking in on you' end;
   b:=case when ar then 'اضغط للرد' else 'Tap to reply' end;
 elsif new.kind='checkin_response' then
   t:=who||case when ar then ' ردّ على اطمئنانك' else ' replied to your check-in' end;
   b:=case when ar then 'اضغط للقراءة' else 'Tap to read' end;
 elsif new.kind='checkin_shared' then
   t:=who||case when ar then ' شارك شعوره اليوم' else ' shared how they feel today' end;
   b:=case when ar then 'اضغط للقراءة' else 'Tap to read' end;
 elsif new.kind='scrapbook_invite' then
   t:=who||case when ar then ' دعاك إلى ألبوم' else ' invited you to a scrapbook' end;
   b:=case when ar then 'اضغط للفتح' else 'Tap to open' end;
 elsif new.kind='reminder' and new.object_kind='calendar' then
   t:=who||case when ar then ' يذكّرك بموعد' else ' reminds you about an event' end; b:=title;
 elsif new.kind='reminder' then
   if new.actor_id=new.recipient_id then
     t:=case when new.headline like 'Urgent: %' then case when ar then 'تذكير عاجل' else 'Urgent reminder' end
       else case when ar then 'تذكير' else 'Reminder' end end;
   else
     t:=case when new.headline like 'Urgent: %' then case when ar then 'تذكير عاجل من ' else 'Urgent reminder from ' end
       else case when ar then 'تذكير من ' else 'Reminder from ' end end||who;
   end if;
   b:=title;
 elsif new.kind='joined' then
   t:=who||case when ar then ' انضم إلى مساحتكما' else ' joined your space' end;
   b:=case when ar then 'يمكنكما الآن مشاركة الأشياء معًا' else 'You can now share things together' end;
 elsif new.kind='created' then
   thing:=case new.object_kind
     when 'task' then case when ar then 'مهمة' else 'a to-do' end
     when 'activity' then case when ar then 'نشاطًا' else 'an Activity' end
     when 'memory' then case when ar then 'ذكرى' else 'a memory' end
     when 'scrapbook' then case when ar then 'ذكرى' else 'a memory' end
     when 'reminder' then case when ar then 'تذكيرًا لك' else 'a reminder for you' end
     when 'calendar' then case when ar then 'موعدًا' else 'an event' end
     when 'trip' then case when ar then 'رحلة' else 'a trip' end
     when 'occasion' then case when ar then 'مناسبة' else 'an occasion' end
     else case when ar then 'عنصرًا' else 'an item' end end;
   t:=who||' '||case when coalesce(new.action,'added')='shared'
       then case when ar then 'شارك' else 'shared' end
       else case when ar then 'أضاف' else 'added' end end||' '||thing;
   b:=title||coalesce(' · '||new.detail,'');
 elsif new.kind='change' then
   verb:=case coalesce(new.action,'')
     when 'moved' then case when ar then 'غيّر موعد' else 'moved' end
     when 'completed' then case when ar then 'أكمل' else 'completed' end
     when 'cancelled' then case when ar then 'ألغى' else 'cancelled' end
     when 'reopened' then case when ar then 'أعاد فتح' else 'reopened' end
     when 'decided' then case when ar then 'حسم' else 'decided on' end
     when 'purchased' then case when ar then 'اشترى' else 'bought' end
     when 'booked' then case when ar then 'حجز' else 'booked' end
     when 'on_hold' then case when ar then 'أوقف مؤقتًا' else 'put on hold' end
     when 'removed' then case when ar then 'حذف' else 'removed' end
     when 'restored' then case when ar then 'استعاد' else 'restored' end
     when 'assigned' then case when ar then 'كلّفك بـ' else 'assigned you' end
     when 'celebrated' then case when ar then 'احتفل بـ' else 'celebrated' end
     when 'ready' then case when ar then 'جهّز' else 'is ready for' end
     when 'planned' then case when ar then 'خطط لـ' else 'planned' end
     when 'enjoyed' then case when ar then 'استمتع بـ' else 'enjoyed' end
     when 'started' then case when ar then 'بدأ' else 'started' end
     else case when ar then 'حدّث' else 'updated' end end;
   t:=who||' '||verb||' '||title;
   b:=coalesce(new.detail,case new.action
     when 'removed' then case when ar then 'يمكنك استعادته من المحذوفات' else 'You can still see it under Removed and restore it' end
     else case new.object_kind
       when 'task' then case when ar then 'مهمة' else 'To-do' end
       when 'activity' then case when ar then 'نشاط' else 'Activity' end
       when 'calendar' then case when ar then 'موعد' else 'Event' end
       when 'trip' then case when ar then 'رحلة' else 'Trip' end
       when 'occasion' then case when ar then 'مناسبة' else 'Occasion' end
       when 'experience' then case when ar then 'تجربة' else 'Shared experience' end
       when 'reminder' then case when ar then 'تذكير' else 'Reminder' end
       else case when ar then 'ذكرى' else 'Memory' end end end);
 else
   t:=who; b:=title;
 end if;

 if new.batch_count>1 then
   b:=b||case when ar then ' (+'||(new.batch_count-1)||' أخرى)'
     else ' (+'||(new.batch_count-1)||' more)' end;
 end if;
 new.push_title:=left(coalesce(nullif(btrim(t),''),'OneSpace'),120);
 new.push_body:=left(coalesce(nullif(btrim(b),''),' '),240);
 return new;
end $$;

create or replace function private.notify_partner_joined()
returns trigger language plpgsql security definer set search_path to '' as $$
declare other uuid;
begin
 for other in select m.user_id from public.space_members m
   where m.space_id=new.space_id and m.user_id<>new.user_id loop
   perform private.post_notice(new.space_id,other,new.user_id,'joined','space',
     new.space_id,'Joined',null,null,interval '0');
 end loop;
 return new;
end $$;
revoke all on function private.notify_partner_joined() from public,anon,authenticated;
drop trigger if exists notify_partner_joined on public.space_members;
create trigger notify_partner_joined after insert on public.space_members
 for each row execute function private.notify_partner_joined();
;

-- >>>>> 0310_qa_account_deletion_worker_schedule.sql
-- QA only (ugwrpeduzyzrujkizqfo). Never apply to Production.
-- Turns on 7-day account deletion in QA and schedules its workers:
--  * every 5 min: shared-media purge (files of separated couples),
--  * every 5 min: due-account private-media purge,
--  * every 5 min: due-account dispatcher -> finalizer per due account.
-- Worker secrets live in Vault; cron jobs only hold the lookup expression.
-- At the deadline, the leaving account's open invitations are revoked.

-- 1. Worker secrets (created once, random).
do $v$
declare n text;
begin
 foreach n in array array['onespace_qa_auth_finalizer_secret',
   'onespace_qa_account_purge_secret','onespace_qa_media_purge_secret'] loop
  if not exists(select 1 from vault.secrets where name=n) then
   perform vault.create_secret(
     replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),
     n,'OneSpace QA lifecycle worker secret');
  end if;
 end loop;
end $v$;

-- 2. Dispatcher: revoke open invitations of due accounts, then ask the
-- finalizer to process each one (idempotent; it re-runs until complete).
create or replace function private.qa_dispatch_due_account_deletions()
returns integer language plpgsql security definer set search_path='' as $f$
declare r record; n integer:=0;
begin
 if not exists(select 1 from private.qa_account_v2_gate where id=1 and enabled) then
  return 0;
 end if;
 for r in select user_id from public.account_deletion_requests
   where cancelled_at is null and completed_at is null and purge_after<=now()
   order by purge_after limit 10 loop
  update public.space_invitations
     set revoked_at=now(), delivery_status='revoked'
   where invited_by=r.user_id and accepted_at is null and revoked_at is null;
  perform net.http_post(
    url:='https://letcgxbnblohhfyeuigz.supabase.co/functions/v1/onespace-qa-account-finalizer',
    headers:=jsonb_build_object('Content-Type','application/json',
      'x-onespace-qa-auth-finalizer-secret',
      (select decrypted_secret from vault.decrypted_secrets
        where name='onespace_qa_auth_finalizer_secret' limit 1)),
    body:=jsonb_build_object('user_id',r.user_id),
    timeout_milliseconds:=30000);
  n:=n+1;
 end loop;
 return n;
end $f$;
revoke all on function private.qa_dispatch_due_account_deletions() from public,anon,authenticated;

-- 3. Schedules (replace if present).
do $c$
declare j text;
begin
 foreach j in array array['onespace-qa-shared-media-purge',
   'onespace-qa-account-private-media-purge','onespace-qa-due-account-dispatch'] loop
  if exists(select 1 from cron.job where jobname=j) then perform cron.unschedule(j); end if;
 end loop;
 -- The legacy v7 account purge keeps shared content (forbidden by the ADR).
 if exists(select 1 from cron.job where jobname='onespace-account-purge') then
  perform cron.unschedule('onespace-account-purge'); end if;
 perform cron.schedule('onespace-qa-shared-media-purge','*/5 * * * *', $job$
  select net.http_post(
   url:='https://letcgxbnblohhfyeuigz.supabase.co/functions/v1/onespace-qa-shared-media-purge',
   headers:=jsonb_build_object('Content-Type','application/json',
    'x-onespace-qa-media-purge-secret',
    (select decrypted_secret from vault.decrypted_secrets
      where name='onespace_qa_media_purge_secret' limit 1)),
   body:='{}'::jsonb, timeout_milliseconds:=30000);
 $job$);
 perform cron.schedule('onespace-qa-account-private-media-purge','*/5 * * * *', $job$
  select net.http_post(
   url:='https://letcgxbnblohhfyeuigz.supabase.co/functions/v1/onespace-qa-account-private-media-purge',
   headers:=jsonb_build_object('Content-Type','application/json',
    'x-onespace-qa-account-purge-secret',
    (select decrypted_secret from vault.decrypted_secrets
      where name='onespace_qa_account_purge_secret' limit 1)),
   body:='{}'::jsonb, timeout_milliseconds:=30000);
 $job$);
 perform cron.schedule('onespace-qa-due-account-dispatch','*/5 * * * *',
  $job$ select private.qa_dispatch_due_account_deletions(); $job$);
end $c$;

-- 4. Open the QA account-deletion gate.
update private.qa_account_v2_gate set enabled=true where id=1;
;

-- >>>>> 0311_qa_worker_secrets_checked_in_database.sql
-- QA only (ugwrpeduzyzrujkizqfo). Never apply to Production.
-- QA workers check their secret against Vault through this service-only
-- function, so no Edge Function dashboard secrets are needed. The finalizer
-- also needs the Vault activation flag below (its explicit second switch).
create or replace function public.qa_worker_secret_matches(p_name text,p_value text)
returns boolean language sql stable security definer set search_path='' as $f$
 select p_name in ('onespace_qa_auth_finalizer_secret','onespace_qa_account_purge_secret',
                   'onespace_qa_media_purge_secret','onespace_qa_allow_auth_finalization')
   and coalesce(length(p_value),0)>=32
   and exists(select 1 from vault.decrypted_secrets
               where name=p_name and decrypted_secret=p_value);
$f$;
revoke all on function public.qa_worker_secret_matches(text,text) from public,anon,authenticated;
grant execute on function public.qa_worker_secret_matches(text,text) to service_role;

do $v$
begin
 if not exists(select 1 from vault.secrets where name='onespace_qa_allow_auth_finalization') then
  perform vault.create_secret('ENABLED_AFTER_ACCEPTANCE_QA_ACCOUNT_FINALIZER',
    'onespace_qa_allow_auth_finalization','QA account finalizer activation switch');
 end if;
end $v$;
;

-- >>>>> 0312_qa_counters_personal_scope_and_cascade_safe_links.sql
-- QA only (ugwrpeduzyzrujkizqfo). Never apply to Production.
-- 1. r77 link guard is scope-aware (space_id AND private_space_id must match)
--    and only checks links that actually change. Before, deleting a couple
--    space failed ("Counter is in another space") because the ON DELETE
--    SET NULL cascade re-checked links to rows already being deleted, and a
--    private counter could never link a private place or memory.
-- 2. Counters get account-owned private scope like the other modules.

create or replace function private.r77_same_space()
returns trigger language plpgsql security definer set search_path='' as $f$
declare ok boolean;
begin
  if tg_table_name = 'place_visits' then
    if tg_op='INSERT' or new.place_id is distinct from old.place_id then
      select (p.space_id is not distinct from new.space_id
              and p.private_space_id is not distinct from new.private_space_id) into ok
        from public.places p where p.id=new.place_id;
      if not coalesce(ok,false) then raise exception 'Place is in another space'; end if;
    end if;
    if new.memory_id is not null and (tg_op='INSERT' or new.memory_id is distinct from old.memory_id)
       and not exists(select 1 from public.memories m where m.id=new.memory_id
         and m.space_id is not distinct from new.space_id
         and m.private_space_id is not distinct from new.private_space_id) then
      raise exception 'Memory is in another space'; end if;
    return new;
  end if;
  if tg_table_name = 'places' then
    if new.planned_trip_id is not null
       and (tg_op='INSERT' or new.planned_trip_id is distinct from old.planned_trip_id)
       and not exists(select 1 from public.shared_trips t where t.id=new.planned_trip_id
         and t.space_id is not distinct from new.space_id
         and t.private_space_id is not distinct from new.private_space_id) then
      raise exception 'Trip is in another space'; end if;
  elsif tg_table_name = 'space_counters' then
    if new.place_id is not null and (tg_op='INSERT' or new.place_id is distinct from old.place_id)
       and not exists(select 1 from public.places p where p.id=new.place_id
         and p.space_id is not distinct from new.space_id
         and p.private_space_id is not distinct from new.private_space_id) then
      raise exception 'Place is in another space'; end if;
    if new.memory_id is not null and (tg_op='INSERT' or new.memory_id is distinct from old.memory_id)
       and not exists(select 1 from public.memories m where m.id=new.memory_id
         and m.space_id is not distinct from new.space_id
         and m.private_space_id is not distinct from new.private_space_id) then
      raise exception 'Memory is in another space'; end if;
    if new.linked_counter_id is not null
       and (tg_op='INSERT' or new.linked_counter_id is distinct from old.linked_counter_id)
       and not exists(select 1 from public.space_counters c where c.id=new.linked_counter_id
         and c.space_id is not distinct from new.space_id
         and c.private_space_id is not distinct from new.private_space_id) then
      raise exception 'Counter is in another space'; end if;
  end if;
  if tg_op = 'UPDATE' then
    new.space_id := old.space_id; new.private_space_id := old.private_space_id;
    new.created_by := old.created_by; new.updated_at := now();
  end if;
  return new;
end $f$;

-- Personal counters: owner only, never in a couple space.
drop policy if exists "QA owner reads personal counters" on public.space_counters;
create policy "QA owner reads personal counters" on public.space_counters
 for select to authenticated
 using(private_space_id=(select auth.uid()) and created_by=(select auth.uid())
   and visibility='private' and space_id is null);
drop policy if exists "QA owner inserts personal counters" on public.space_counters;
create policy "QA owner inserts personal counters" on public.space_counters
 for insert to authenticated
 with check(private_space_id=(select auth.uid()) and created_by=(select auth.uid())
   and visibility='private' and space_id is null);
drop policy if exists "QA owner updates personal counters" on public.space_counters;
create policy "QA owner updates personal counters" on public.space_counters
 for update to authenticated
 using(private_space_id=(select auth.uid()) and created_by=(select auth.uid()))
 with check(private_space_id=(select auth.uid()) and created_by=(select auth.uid())
   and visibility='private' and space_id is null);
-- Shared counters only between a current pair; private ones never in the couple.
drop policy if exists "QA active pair shared counters" on public.space_counters;
create policy "QA active pair shared counters" on public.space_counters
 as restrictive for insert to authenticated
 with check(private_space_id is not null or (visibility='shared' and space_id is not null
   and private.is_space_member(space_id)
   and (select count(*) from public.space_members m where m.space_id=space_counters.space_id)=2));
drop policy if exists "QA active pair updates shared counters" on public.space_counters;
create policy "QA active pair updates shared counters" on public.space_counters
 as restrictive for update to authenticated using(true)
 with check(private_space_id is not null or (visibility='shared' and space_id is not null
   and private.is_space_member(space_id)));

-- 3. Trips: a personal trip's traveler is its owner (or nobody); a couple
--    trip's traveler must be a member. The old check only knew space_id, so
--    every personal trip with a traveler failed.
create or replace function private.trip_check_traveler()
returns trigger language plpgsql security definer set search_path='' as $f$
begin
  if new.traveler_id is null then return new; end if;
  if new.private_space_id is not null then
    if new.traveler_id is distinct from new.private_space_id then
      raise exception 'A private trip can only be planned for yourself';
    end if;
  elsif not private.user_in_space(new.space_id,new.traveler_id) then
    raise exception 'The traveler must be a member of this space';
  end if;
  return new;
end $f$;

-- 4. Feelings: one private and one shared entry per person per day.
alter table public.daily_checkins drop constraint if exists daily_checkins_created_by_checkin_date_key;
drop index if exists public.daily_checkins_created_by_checkin_date_key;
create unique index if not exists qa_daily_checkins_shared_day_unique
  on public.daily_checkins(created_by,checkin_date) where space_id is not null;
;

-- >>>>> 0313_qa_selfies_scrapbook_revoke_birthdays_holidays_resets.sql
-- QA 0313 (Amr's 21 Nov test findings). QA only; never apply to Production.
--  1. Daily selfies are allowed in the personal space (solo too); one a day.
--  2. A scrapbook owner can withdraw the invitation or stop co-editing.
--  3. Living arrangement & meeting dates need both partners.
--  4. Each person owns their birthday, and chooses whether their partner sees
--     it and whether the year is shown. Both choices reset to "no" whenever
--     the pairing changes (partner joins, leaves, is removed, space deleted).
--  5. Preferred names for a partner reset when the pairing ends.
--  6. Each person chooses their own holiday countries (any country); a
--     current partner sees them too.

-- 1. Daily selfies -------------------------------------------------------
alter table public.memories drop constraint if exists qa_private_memories_story_only;
alter table public.memories add constraint qa_private_memories_story_only
 check(private_space_id is null or memory_type in ('story','scrapbook','daily_selfie')) not valid;
create unique index if not exists qa_one_daily_selfie_per_person_per_day
 on public.memories(created_by, memory_date)
 where memory_type='daily_selfie' and archived_at is null;

-- 2. Scrapbook invitation withdraw / stop co-editing -----------------------
create or replace function public.revoke_scrapbook_invite(p_memory_id uuid)
returns void language plpgsql security definer set search_path to '' as $$
declare me uuid:=auth.uid(); m record;
begin
 select id,created_by,memory_type,visibility,archived_at into m
 from public.memories where id=p_memory_id;
 if me is null or not found or m.created_by<>me or m.memory_type<>'scrapbook'
    or m.visibility<>'shared' or m.archived_at is not null then
  raise exception 'Only the owner of a shared scrapbook can withdraw the invitation'
   using errcode='42501';
 end if;
 delete from public.scrapbook_invites i
  where i.memory_id=p_memory_id and i.status in ('pending','accepted');
 if not found then raise exception 'There is no invitation to withdraw'; end if;
 delete from public.space_notifications n
  where n.kind='scrapbook_invite' and n.object_id=p_memory_id;
end $$;
revoke all on function public.revoke_scrapbook_invite(uuid) from public,anon,authenticated;
grant execute on function public.revoke_scrapbook_invite(uuid) to authenticated;

-- Helper: is p_user my partner in a complete (two-person) couple space?
create or replace function private.qa_is_current_partner(p_user uuid)
returns boolean language sql stable security definer set search_path to '' as $$
 select (select auth.uid()) is not null and p_user is not null
  and p_user<>(select auth.uid())
  and exists(select 1 from public.space_members a
   join public.space_members b on b.space_id=a.space_id
   where a.user_id=(select auth.uid()) and b.user_id=p_user
     and (select count(*) from public.space_members c where c.space_id=a.space_id)=2)
$$;
revoke all on function private.qa_is_current_partner(uuid) from public,anon;
grant execute on function private.qa_is_current_partner(uuid) to authenticated;

-- 3. Relationship settings need two partners --------------------------------
create or replace function private.qa_relationship_settings_need_pair()
returns trigger language plpgsql security definer set search_path to '' as $$
begin
 if (select auth.uid()) is not null
    and (new.relationship_mode is distinct from old.relationship_mode
      or new.last_met_on is distinct from old.last_met_on
      or new.next_meet_on is distinct from old.next_meet_on)
    and (select count(*) from public.space_members m where m.space_id=new.id)<>2 then
  raise exception 'Living arrangement can be set once your partner joins' using errcode='42501';
 end if;
 return new;
end $$;
drop trigger if exists qa_relationship_settings_need_pair on public.spaces;
create trigger qa_relationship_settings_need_pair before update on public.spaces
 for each row execute function private.qa_relationship_settings_need_pair();

-- 4. Account-owned birthdays --------------------------------------------
create table if not exists public.account_birthdays (
 user_id uuid primary key references auth.users(id) on delete cascade default auth.uid(),
 month smallint not null check (month between 1 and 12),
 day smallint not null check (day between 1 and 31),
 year smallint check (year between 1900 and 2100),
 share_with_partner boolean not null default false,
 share_year boolean not null default false,
 updated_at timestamptz not null default now(),
 check (make_date(2000, month, 1) + (day - 1) < (make_date(2000, month, 1) + interval '1 month')::date)
);
alter table public.account_birthdays enable row level security;
drop policy if exists "Own birthday" on public.account_birthdays;
create policy "Own birthday" on public.account_birthdays for all to authenticated
 using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
revoke all on public.account_birthdays from public,anon,authenticated;
grant select,insert,update,delete on public.account_birthdays to authenticated;

-- The partner's birthday, only what they chose to share.
create or replace function public.partner_birthday()
returns table(person_id uuid, month smallint, day smallint, year smallint)
language sql stable security definer set search_path to '' as $$
 select b.user_id, b.month, b.day, case when b.share_year then b.year end
 from public.account_birthdays b
 where b.share_with_partner and private.qa_is_current_partner(b.user_id)
$$;
revoke all on function public.partner_birthday() from public,anon,authenticated;
grant execute on function public.partner_birthday() to authenticated;

-- 6. Account-owned holiday countries ------------------------------------
create table if not exists public.account_holiday_countries (
 user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),
 country_code text not null check (country_code ~ '^[A-Z]{2}$'),
 created_at timestamptz not null default now(),
 primary key (user_id, country_code)
);
alter table public.account_holiday_countries enable row level security;
drop policy if exists "Own holiday countries" on public.account_holiday_countries;
create policy "Own holiday countries" on public.account_holiday_countries for all to authenticated
 using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
drop policy if exists "Partner holiday countries" on public.account_holiday_countries;
create policy "Partner holiday countries" on public.account_holiday_countries for select to authenticated
 using (private.qa_is_current_partner(user_id));
revoke all on public.account_holiday_countries from public,anon,authenticated;
grant select,insert,delete on public.account_holiday_countries to authenticated;

-- 4 + 5. Pairing changed: reset sharing choices and partner names --------
create or replace function private.qa_reset_on_pairing_change()
returns trigger language plpgsql security definer set search_path to '' as $$
declare s uuid:=coalesce(new.space_id, old.space_id);
 people uuid[];
begin
 select array_agg(m.user_id) into people from public.space_members m where m.space_id=s;
 people:=coalesce(people,'{}')||coalesce(new.user_id, old.user_id);
 update public.account_birthdays b set share_with_partner=false, share_year=false, updated_at=now()
  where b.user_id=any(people) and (b.share_with_partner or b.share_year);
 if tg_op='DELETE' then
  update public.profiles p set partner_label=null, partner_labels='{}'
   where p.id=any(people) and (p.partner_label is not null or cardinality(p.partner_labels)>0);
 end if;
 return null;
end $$;
drop trigger if exists qa_reset_on_pairing_change on public.space_members;
create trigger qa_reset_on_pairing_change after insert or delete on public.space_members
 for each row execute function private.qa_reset_on_pairing_change();
;

-- >>>>> 0314_qa_event_participants_shared_scrapbooks_nudge.sql
-- QA 0314 (Amr, 21 Nov afternoon). QA only; never apply to Production.
--  1. Calendar: who an event is for (participants) is independent of who can
--     see it. A private (Only me) event may be for me, for both of us or for
--     my current partner. A partner's account deletion clears the
--     participant instead of deleting my private event.
--  2. Shared scrapbooks are editable by both partners, like every shared
--     item. The invitation step is no longer needed.
--  3. Nudge my partner about a shared memory or scrapbook (notification).

-- 1. Event participants ----------------------------------------------------
create or replace function private.validate_event_person()
returns trigger language plpgsql set search_path to '' as $function$
begin
 if new.private_space_id is not null then
   if new.space_id is not null or new.created_by is distinct from new.private_space_id
     or new.visibility<>'private' then
       raise exception 'Personal calendar event must belong to its account owner';
   end if;
   -- For me, for both of us, or for my current partner (checked when chosen).
   if new.for_user_id is not null and new.for_user_id is distinct from new.created_by
      and (tg_op='INSERT' or new.for_user_id is distinct from old.for_user_id)
      and not private.qa_is_current_partner(new.for_user_id) then
     raise exception 'The selected person is not your current partner';
   end if;
   return new;
 end if;
 if new.for_user_id is not null and not exists(
    select 1 from public.space_members
    where space_id=new.space_id and user_id=new.for_user_id
 ) then raise exception 'The selected person is not part of this space'; end if;
 return new;
end; $function$;

drop policy if exists "QA account owner creates personal events" on public.space_events;
create policy "QA account owner creates personal events" on public.space_events
 for insert to authenticated with check (
  private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and space_id is null);
drop policy if exists "QA account owner edits personal events" on public.space_events;
create policy "QA account owner edits personal events" on public.space_events
 for update to authenticated
 using (private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and space_id is null)
 with check (private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and space_id is null);
drop policy if exists "QA account owner reads personal events" on public.space_events;
create policy "QA account owner reads personal events" on public.space_events
 for select to authenticated using (
  private_space_id=(select auth.uid()) and created_by=(select auth.uid())
  and visibility='private' and space_id is null);

alter table public.space_events drop constraint if exists space_events_for_user_id_fkey;
alter table public.space_events add constraint space_events_for_user_id_fkey
 foreign key (for_user_id) references auth.users(id) on delete set null not valid;

-- 2. Shared scrapbooks: both partners edit ------------------------------------
create or replace function private.may_edit_scrapbook(p_memory uuid, p_user uuid)
returns boolean language sql stable security definer set search_path to '' as $function$
 select exists(select 1 from public.memories m
  where m.id=p_memory and m.memory_type='scrapbook' and m.archived_at is null
   and (
    (m.private_space_id is not null and m.private_space_id=p_user
       and m.created_by=p_user and m.space_id is null and m.visibility='private')
    or
    (m.private_space_id is null and m.space_id is not null
       and exists(select 1 from public.space_members sm
                  where sm.space_id=m.space_id and sm.user_id=p_user)
       and (m.created_by=p_user or m.visibility='shared'))
   ))
$function$;

-- 3. Nudge my partner about a shared memory -------------------------------------
create or replace function public.nudge_partner_about_memory(p_memory_id uuid)
returns void language plpgsql security definer set search_path to '' as $function$
declare me uuid:=auth.uid(); m record; partner uuid;
begin
 select id,space_id,title,memory_type,visibility,archived_at into m
 from public.memories where id=p_memory_id;
 if me is null or not found or m.space_id is null or m.visibility<>'shared'
    or m.archived_at is not null or not private.is_space_member(m.space_id) then
  raise exception 'Only a shared memory can be sent to your partner' using errcode='42501';
 end if;
 select user_id into partner from public.space_members
  where space_id=m.space_id and user_id<>me order by joined_at limit 1;
 if partner is null then raise exception 'Your partner has not joined yet'; end if;
 if exists(select 1 from public.space_notifications n
   where n.recipient_id=partner and n.kind='message' and n.object_id=p_memory_id
     and n.actor_id=me and n.created_at>now()-interval '1 minute') then
  raise exception 'You just nudged your partner. Try again in a minute.';
 end if;
 insert into public.space_notifications(space_id,recipient_id,actor_id,kind,object_kind,
   object_id,headline,detail,generated_automatically)
 values(m.space_id,partner,me,'message',
   case when m.memory_type='scrapbook' then 'scrapbook' else 'memory' end,
   p_memory_id,left(coalesce(nullif(btrim(m.title),''),'Our memory'),180),
   'Would love you to add your part to this memory',true)
 on conflict(recipient_id,kind,object_id) do update set
   actor_id=excluded.actor_id, headline=excluded.headline, detail=excluded.detail,
   created_at=now(), read_at=null;
end $function$;
revoke all on function public.nudge_partner_about_memory(uuid) from public,anon,authenticated;
grant execute on function public.nudge_partner_about_memory(uuid) to authenticated;
;

-- >>>>> 0315_qa_separation_keeps_owner_space_and_notices.sql
-- QA 0315 (Amr, 21 Nov 16:54 Riyadh). QA only; never apply to Production.
-- After a separation:
--  * Partner leaves      -> the owner keeps a (fresh, empty) shared space and
--                           gets a notice; the leaver gets the 3 options + notice.
--  * Owner removes partner -> same: owner keeps a space, removed partner gets
--                           the 3 options; both get a notice.
--  * Owner deletes space -> neither keeps a space; both get a notice.
--  * Account deletion    -> if the remaining partner owns the space they keep it;
--                           otherwise they get the 3 options. They get a notice.
-- Notices live in public.account_notices (not tied to a space, so they survive
-- the space deletion) and show as a fixed banner on Today until dismissed.

create table if not exists public.account_notices (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 kind text not null check (kind in ('partner_left','you_left','partner_removed_you',
   'you_removed_partner','space_deleted','you_deleted_space','partner_deleted_account')),
 title text not null,
 body text not null,
 created_at timestamptz not null default now(),
 dismissed_at timestamptz
);
create index if not exists account_notices_open on public.account_notices(user_id)
 where dismissed_at is null;
alter table public.account_notices enable row level security;
drop policy if exists "Own notices" on public.account_notices;
create policy "Own notices" on public.account_notices for select to authenticated
 using (user_id=(select auth.uid()));
drop policy if exists "Dismiss own notices" on public.account_notices;
create policy "Dismiss own notices" on public.account_notices for update to authenticated
 using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()));
revoke all on public.account_notices from public,anon,authenticated;
grant select on public.account_notices to authenticated;
grant update(dismissed_at) on public.account_notices to authenticated;

-- Keep the audited separation transaction exactly as it is, and wrap it.
do $r$ begin
 if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='private' and p.proname='qa_close_relationship_v2_core') then
  alter function private.qa_close_relationship_v2(uuid,text,text)
   rename to qa_close_relationship_v2_core;
 end if;
end $r$;
revoke all on function private.qa_close_relationship_v2_core(uuid,text,text)
 from public,anon,authenticated;

create or replace function private.qa_first_name(p_user uuid, p_fallback text)
returns text language sql stable security definer set search_path to '' as $$
 select coalesce(nullif(split_part(btrim(coalesce(
   (select p.display_name from public.profiles p where p.id=p_user),'')),' ',1),''),p_fallback)
$$;
revoke all on function private.qa_first_name(uuid,text) from public,anon,authenticated;

create or replace function private.qa_close_relationship_v2(
 p_space uuid, p_action text, p_confirmation text)
returns jsonb language plpgsql security definer set search_path to '' as $function$
declare me uuid:=auth.uid(); owner_id uuid; guest uuid; members int;
 owner_name text; guest_name text; by_deletion boolean; result jsonb;
 kept uuid; new_space uuid;
 safe constant text:=' Shared items were removed. Private items are safe.';
begin
 select s.created_by into owner_id from public.spaces s where s.id=p_space;
 select count(*) into members from public.space_members m where m.space_id=p_space;
 select m.user_id into guest from public.space_members m
  where m.space_id=p_space and m.user_id<>owner_id limit 1;

 result:=private.qa_close_relationship_v2_core(p_space,p_action,p_confirmation);

 -- Only a real pair has someone to tell.
 if members<>2 or guest is null or owner_id is null then return result; end if;
 owner_name:=private.qa_first_name(owner_id,'Your partner');
 guest_name:=private.qa_first_name(guest,'Your partner');
 -- Closed on behalf of an account whose deletion is due.
 by_deletion:=exists(select 1 from public.account_deletion_requests r
   where r.user_id=me and r.cancelled_at is null and r.completed_at is null
     and r.purge_after<=now());

 if by_deletion then
  if me=guest then
   kept:=owner_id;
   insert into public.account_notices(user_id,kind,title,body) values(owner_id,
    'partner_deleted_account',guest_name||' deleted their account',
    'Your space is still here, ready for a new partner.'||safe);
  else
   insert into public.account_notices(user_id,kind,title,body) values(guest,
    'partner_deleted_account',owner_name||' deleted their account',
    'Their shared space was closed. You can join a partner, invite one, or create your own space.'||safe);
  end if;
 elsif p_action='leave_space' then
  kept:=owner_id;
  insert into public.account_notices(user_id,kind,title,body) values
   (owner_id,'partner_left',guest_name||' left your space',
    'Your space is still here, ready for a new partner.'||safe),
   (guest,'you_left','You left '||owner_name||'''s space',
    'You can join a partner, invite one, or create your own space.'||safe);
 elsif p_action='remove_partner' then
  kept:=owner_id;
  insert into public.account_notices(user_id,kind,title,body) values
   (owner_id,'you_removed_partner','You removed '||guest_name,
    'Your space is still here, ready for a new partner.'||safe),
   (guest,'partner_removed_you',owner_name||' removed you from their space',
    'You can join a partner, invite one, or create your own space.'||safe);
 elsif p_action='delete_space' then
  insert into public.account_notices(user_id,kind,title,body) values
   (owner_id,'you_deleted_space','You deleted your shared space',
    'You can invite a partner, join one, or create a new space.'||safe),
   (guest,'space_deleted',owner_name||' deleted the shared space',
    'You can join a partner, invite one, or create your own space.'||safe);
 end if;

 -- The owner keeps a space (fresh and empty) so nothing changes for them,
 -- unless their own account is being deleted.
 if kept is not null and not private.qa_account_pending_delete(kept)
    and not exists(select 1 from public.space_members m join public.spaces s on s.id=m.space_id
                   where m.user_id=kept and s.personal_owner is null) then
  insert into public.spaces(created_by) values(kept) returning id into new_space;
  insert into public.space_members(space_id,user_id) values(new_space,kept);
  result:=result||jsonb_build_object('owner_space_kept',new_space);
 end if;
 return result;
end $function$;
revoke all on function private.qa_close_relationship_v2(uuid,text,text) from public,anon,authenticated;
grant execute on function private.qa_close_relationship_v2(uuid,text,text) to service_role;
grant execute on function private.qa_close_relationship_v2_core(uuid,text,text) to service_role;
;

-- >>>>> 0316_qa_invitation_resend_limits.sql
-- QA 0316 (Amr, 21 Nov): resending an invitation or sending a replacement
-- code was refused for 15 minutes. Allow the same recipient again after one
-- minute (still blocks double taps) and up to 10 emails an hour per sender.
create or replace function public.claim_app_invitation_email_send(
 p_sender_id uuid, p_space_id uuid, p_recipient_digest text)
returns boolean language plpgsql set search_path to '' as $function$
begin
  if current_user <> 'service_role' then
    raise exception 'service role only';
  end if;
  if p_sender_id is null or p_space_id is null
      or p_recipient_digest !~ '^[0-9a-f]{64}$' then
    return false;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('app-invite-mail'),pg_catalog.hashtext(p_sender_id::text)
  );
  if (select count(*) from private.app_invitation_email_sends
       where sender_id=p_sender_id
         and created_at > pg_catalog.now()-interval '1 hour') >= 10 then
    return false;
  end if;
  if exists (select 1 from private.app_invitation_email_sends
       where sender_id=p_sender_id and recipient_digest=p_recipient_digest
         and created_at > pg_catalog.now()-interval '1 minute') then
    return false;
  end if;
  insert into private.app_invitation_email_sends(sender_id,space_id,recipient_digest)
  values(p_sender_id,p_space_id,p_recipient_digest);
  return true;
end;
$function$;
;

-- >>>>> 0317_qa_decline_invitation.sql
-- QA 0317 (Amr, 21 Nov): an existing account with no space must accept or
-- decline an invitation (no automatic join). Declining ends the invitation
-- and tells the inviter with a banner on their Today screen.
alter table public.account_notices drop constraint if exists account_notices_kind_check;
alter table public.account_notices add constraint account_notices_kind_check check (kind in
 ('partner_left','you_left','partner_removed_you','you_removed_partner','space_deleted',
  'you_deleted_space','partner_deleted_account','invitation_declined'));

create or replace function public.decline_my_invitation(p_token text)
returns void language plpgsql security definer set search_path to '' as $function$
declare me uuid:=auth.uid(); my_email text; inv record;
begin
 select lower(u.email) into my_email from auth.users u where u.id=me;
 if me is null or my_email is null then
  raise exception 'Sign in required' using errcode='42501';
 end if;
 select i.id,i.invited_by,i.invited_email into inv from public.space_invitations i
  where i.token=p_token and i.accepted_at is null and i.revoked_at is null
    and i.expires_at>now()
  for update;
 if not found then return; end if;  -- already gone: nothing to decline
 if lower(coalesce(inv.invited_email,'')) is distinct from my_email then
  raise exception 'This invitation belongs to another email address' using errcode='42501';
 end if;
 update public.space_invitations set revoked_at=now() where id=inv.id;
 insert into public.account_notices(user_id,kind,title,body) values(inv.invited_by,
  'invitation_declined',private.qa_first_name(me,'Your invitee')||' declined your invitation',
  'You can invite them again or invite someone else from My Space.');
end $function$;
revoke all on function public.decline_my_invitation(text) from public,anon;
grant execute on function public.decline_my_invitation(text) to authenticated;
;

-- >>>>> finalize.sql
-- Production finalize: runs at the end of supabase/production/upgrade.sql,
-- inside the same transaction.
--
-- 1. Existing data: Production has items made before private spaces existed.
--    A private item there sits in the couple space (space_id) with
--    visibility='private'. In the new model a private item belongs to its
--    creator's private space (private_space_id = created_by, a row of
--    public.user_private_spaces) and has no couple space, so
--    ending a couple never deletes anyone's private items. Shared items stay
--    where they are. Children (checklist items, comments, photos) follow their
--    parent row and need no change.
-- 2. Switch on leave/remove/delete space and 7-day account deletion (the two
--    gates QA turned on after its acceptance tests).
-- 3. Checks: anything unexpected aborts the whole upgrade.

do $move$
declare
  t text;
  moved int;
  report text := '';
begin
  -- Every account owns a personal space (0243 does this too; harmless again).
  perform private.ensure_personal_space(u.id) from auth.users u where u.deleted_at is null;
  -- Every account has its private namespace (0227 does this too).
  insert into public.user_private_spaces(owner_id)
    select id from auth.users on conflict(owner_id) do nothing;

  for t in
    select c.table_name
      from information_schema.columns c
     where c.table_schema='public' and c.column_name='private_space_id'
       and exists(select 1 from information_schema.columns k where k.table_schema='public'
                  and k.table_name=c.table_name and k.column_name='visibility')
       and exists(select 1 from information_schema.columns k where k.table_schema='public'
                  and k.table_name=c.table_name and k.column_name='created_by')
       and exists(select 1 from information_schema.columns k where k.table_schema='public'
                  and k.table_name=c.table_name and k.column_name='space_id')
       -- Private counters live in the account's personal space (spaces with
       -- personal_owner), not in private_space_id. Production has none today.
       and c.table_name <> 'space_counters'
     order by 1
  loop
    -- Scope guards forbid moving a row between spaces from the app. This is
    -- the one-time move, so they are paused for this table only, inside this
    -- transaction, and switched back on straight after.
    execute format('alter table public.%I disable trigger user', t);
    execute format($u$
      update public.%I r
         set private_space_id = r.created_by,
             space_id = null
       where r.visibility::text = 'private'
         and r.private_space_id is null
         and r.created_by is not null
         and not exists(select 1 from public.spaces s
                         where s.id = r.space_id and s.personal_owner is not null)$u$, t);
    get diagnostics moved = row_count;
    execute format('alter table public.%I enable trigger user', t);
    if moved > 0 then report := report || t || '=' || moved || ' '; end if;
  end loop;
  raise notice 'private items moved to personal spaces: %', coalesce(nullif(report,''),'none');
end
$move$;

-- 2. Lifecycle switches.
insert into private.qa_relationship_v2_gate(id,enabled) values(1,true)
  on conflict (id) do update set enabled=true;
insert into private.qa_account_v2_gate(id,enabled) values(1,true)
  on conflict (id) do update set enabled=true;

-- 3. Checks.
do $check$
declare n int;
begin
  -- No private item may still sit in a couple space.
  select count(*) into n from (
    select 1 from public.activities where visibility::text='private' and private_space_id is null
    union all select 1 from public.notes where visibility::text='private' and private_space_id is null
    union all select 1 from public.tasks where visibility::text='private' and private_space_id is null
    union all select 1 from public.space_events where visibility::text='private' and private_space_id is null
    union all select 1 from public.occasion_plans where visibility::text='private' and private_space_id is null
  ) x;
  if n > 0 then raise exception 'finalize: % private items still in a couple space', n; end if;

  -- Moved items sit in their creator's private space and nowhere else.
  select count(*) into n from (
    select 1 from public.activities where private_space_id is not null and (private_space_id<>created_by or space_id is not null)
    union all select 1 from public.notes where private_space_id is not null and (private_space_id<>created_by or space_id is not null)
    union all select 1 from public.tasks where private_space_id is not null and (private_space_id<>created_by or space_id is not null)
    union all select 1 from public.space_events where private_space_id is not null and (private_space_id<>created_by or space_id is not null)
    union all select 1 from public.occasion_plans where private_space_id is not null and (private_space_id<>created_by or space_id is not null)
  ) x;
  if n > 0 then raise exception 'finalize: % private items in the wrong private space', n; end if;

  -- Every account has exactly one personal space.
  select count(*) into n from auth.users u where u.deleted_at is null
     and not exists(select 1 from public.spaces s where s.personal_owner=u.id);
  if n > 0 then raise exception 'finalize: % accounts without a personal space', n; end if;

  -- Worker schedules point at Production, never at QA.
  select count(*) into n from cron.job where command like '%ugwrpeduzyzrujkizqfo%';
  if n > 0 then raise exception 'finalize: % scheduled jobs still point at QA', n; end if;

  -- The old account purge (keeps shared content) is gone.
  select count(*) into n from cron.job where jobname='onespace-account-purge';
  if n > 0 then raise exception 'finalize: old account purge is still scheduled'; end if;

  -- Key functions the app calls exist.
  if to_regprocedure('public.decline_my_invitation(text)') is null
     or to_regprocedure('public.qa_end_current_relationship(uuid,text,text)') is null
     or to_regprocedure('public.resolve_my_addressed_invitation(text)') is null
     or to_regprocedure('public.create_addressed_invitation(uuid,text,boolean)') is null
     or to_regprocedure('public.qa_request_account_deletion()') is null
     or to_regprocedure('public.qa_find_my_addressed_invitation()') is null
  then raise exception 'finalize: an app function is missing'; end if;
end
$check$;
